\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 61\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  93\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Introductio}}\plain \f1\lang1033\fs26  Decreti Gratiani. (61\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Concordia canonum discordancium iuxta determinacionem Graciani episcopi}}\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 que in tres principaliter dividitur partes\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 prima constat \plain \f1\lang1033\fs26 [de]\plain \f1\i\lang1033\fs26  diccionibus centum et secunda causis xxxvi \plain \f1\lang1033\fs26 ... (93\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 In xxxvi\plain \f1\i\super\lang1033\fs24 a\plain \f1\i\lang1033\fs26  causa de raptoribus agitur\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 qui sint raptores et que penitencia sit eis imponenda\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 et an rapte post rapinam purgatam raptoribus suis licite copulari valeant\plain \f1\lang1033\fs26 . \endash  Vgl. Kuttner, Repertorium der Kanonistik, 1937, S. 14, 20, 29; R. Weigand, Fr\u252 \'fche Kanonisten und ihre Karriere in der Kirche, in: ZRG KA, 76 (1990), S. 135 \endash  155, bes. S. 152 \endash  155; Kenneth Pennington, The Biography of Gratian, the Father of Canon Law, in: Villa\-nova Law Review 59, (2014), S. 679 \endash  706, bes. S. 700 \endash  702. }

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 94\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  131\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  Abbreviatio Decreti Gratiani. (94\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) ({\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 V)}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 idit Jacob scalam mire altitudinis}}\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  que superposita terram osculans \plain \f1\lang1033\fs26 ... \plain \f1\i\lang1033\fs26 Gratianus autem cum Jacob scalam ascendens\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  ex ipsa scala sine admodum scale librorum composuit decretorum\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 qui intendens providere statui universalis ecclesie\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 compilavit opus suum\plain \f1\lang1033\fs26  \u8230 \'85 (95\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 In prima distinctione ostendit\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 quid sit lex humana\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 quid ius divinium\plain \f1\lang1033\fs26  \u8230 \'85 (104\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) (N)\plain \f1\i\lang1033\fs26 unc magister Gracianus aggreditur secundum partem sui operis et incipit a prima causa et hec\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 secunda pars protenditur usque ad xxvi causam\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 in qua incipit tractare de juramentis\plain \f1\lang1033\fs26  \u8230 \'85 (105\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) (E)\plain \f1\i\lang1033\fs26 xpedito tractatu de symonia\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 cuius comparatione cetera crimina pro nichilo reputantur\plain \f1\lang1033\fs26  \u8230 \'85 (123\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) Rubrik: \plain \f1\i\lang1033\fs26 De consecracione distinctio prima\plain \f1\lang1033\fs26 . Text: (D)\plain \f1\i\lang1033\fs26 istinctio autem prima dividitur in xxvi partes\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 in quorum prima ostendit\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 quod non debemus missas celebrare\plain \f1\lang1033\fs26  \u8230 \'85 (131\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 In xiiii autem parte dicitur et ultimo probat, quod a spiritu sancto omnia perficiuntur \plain \f1\lang1033\fs26 ... \plain \f1\i\lang1033\fs26 quin procedat similiter a filio ut id est de spiritu sancto et capitulum salvator etc\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Sit laus deo patri et sancta trinitate\plain \f1\lang1033\fs26 . \endash  Abgek\u252 \'fcrzte, exzerpierte Version des {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Decretum Gratiani}}\plain \f1\lang1033\fs26 ; trotz gleichlautenden Initiums nicht iden\-tisch mit dem bei Antonio Garc\u237 \'eda y Garc\u237 \'eda, Canonistica Hispanica (II), in: Traditio 23 (1967), S. 508 \endash  511 abgedruckten Text. \endash  132\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  136\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  leer. }

