\pard\fi0\li0\qj\ri0\sb0\sa600\itap0 \plain \f1\lang1033\fs26 11 Bl.\~\~\u183 \'b7\~\~Rhein-Neckar-Region (Heidelberg ?)\~\~{\field{\*\fldinst HYPERLINK "hida://5060[0].5064/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 15. Jh. Mitte}}
\par \pard\fi0\li0\qj\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs22 Fol. 98 \endash  108\~\u183 \'b7\~\~Wasserzeichen: Amboss mit Kreuz, mehrere Varianten: 1. sehr \u228 \'e4hnlich und \u228 \'e4hnlich WZIS DE2730-PO-122641 (Aschaffenburg 1453); 2. sehr \u228 \'e4hnlich WZIS IT8355-PO-122615 (Udine 1443); 3. \u228 \'e4hnlich Piccard, Werkzeuge und Waffen, Werkzeug, Amboss, Nr. IV, 1115 (Hall/ Tirol 1444)\~\~\u183 \'b7\~\~Schriftraum: 21 \endash  22 x 13,5 \endash  16; Schriftraumbegrenzung blind vorgepr\u228 \'e4gt\~\~\u183 \'b7\~\~36 \endash  38 Zeilen\~\~\u183 \'b7\~\~Bastarda von mehreren, wohl drei H\u228 \'e4nden\~\~\u183 \'b7\~\~98\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  Titelvermerk des 16. / 17. Jhs.\~\~\u183 \'b7\~\~in der Regel 3-7zeilige Initialen, vereinzelt mit vegetabilischen Fleuronn\u233 \'e9e-Ornamenten (Knospen, Fadenwerk) in brauner Feder; 100\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22  fig\u252 \'fcrliche Initiale mit Hund im Binnengrund; 103\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22  und 99\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  nur Aussparungen f\u252 \'fcr Initialen; 103\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22  mit Rubrikatorvorgabe.}

