\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  106\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Pius II. Papa}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Historia Bohemica}}\plain \f1\lang1033\fs26 . (1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) Rubrik: (E)\plain \f1\i\lang1033\fs26 nei Picolominei Senensis cardinalis sanct\plain \f2\i\lang1024\fs26 \u281 \'ea Sabin\u281 \'ea ad Alfonsum Aragonum regem clarissimum in ystoriam Boemicam prefacio incipit feliciter\plain \f1\lang1033\fs26 . Prolog: ({\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 I)}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 nteritura esse queque nascuntur}}\plain \f1\lang1033\fs26  ... (3\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) Rubrik: (E)\plain \f1\i\lang1033\fs26 neas Silvii Picolominei Senensis cardinalis Istorie Bohemice liber primus incipit feliciter\plain \f1\lang1033\fs26 . Buch 1: ({\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 B)}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 ohemia in solo Barbarico trans Danubium sita}}\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  Germanie porcio est\plain \f1\lang1033\fs26  ... (106\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 nobis persuasum est armis acquiri regna\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 non legibus\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Finis laus deo\plain \f1\lang1033\fs26 . (106\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Quo anno Eneas Silvius Picolomineus Senensis sancte Sabine cardinalis Hystoriam hanc Bohemeam edidit assumptus est ad summum pontificatum et nominatus Pius Secundus\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Idem mox pro salute Christiani populi\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  conventum Mantuanum indixit ac peregit\plain \f1\lang1033\fs26 . \endash  Druck\plain \f2\lang1024\fs26 : {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f2\lang1024\fs26\chcbpat17 GW M33748, M33750 \endash  M33753, M33755}}\plain \f2\lang1024\fs26 ; Dana Mart\u237 \'ednkov\u225 \'e1 u. a. (Hrsg.), Aenaeae Silvii Historia Bohemica. Enea Silvio Historia Bohemica. Historie \u268 \'c8esk\u225 \'e1, Prag 1998 (Clavis Monumentorum Litterarum (Regnum Bohemiae) Bd. 4; Fontes rerum Regni \plain \f1\lang1033\fs26 Bohemiae, Bd. 1), S. 2 \endash  256; Rothe, Kritische Ausgabe, 1991 (s. Lit.), S. 31, Nr. 21, S. 33; Hejnic/ Rothe, Historia Bohemica, 2005 (s. Lit.), S. 4 \endash  626; vgl. ebenda, S. 0127 und 0137; Weinig, Aeneam suscipite, 1998 (s. Lit.), S. 11, S. 154, Nr. 79. \endash  107\plain \f1\super\lang1033\fs24 r/v\plain \f1\lang1033\fs26  leer. }

