\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 75\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  89\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Nicolaus de Clemangiis}}\plain \f1\lang1033\fs26  (?), {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Epistolae}}\plain \f1\lang1033\fs26  nomine et mandato Universitatis Parisiensis scriptae pro schismatis extinctione. (75\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Sequitur quedam epistole eiusdem nomine universitatis Parisiensis\plain \f1\lang1033\fs26 <. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Acerbissima clades, que plebibus imminet Christianis vestras}}\plain \f1\i\lang1033\fs26 , commoveat animos\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  eggregii viri \plain \f1\lang1033\fs26 ... \plain \f1\i\lang1033\fs26 Audistis\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 ut credimus\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 quantam stragem soldanus Babilonie nobis comminetur universis\plain \f1\lang1033\fs26  ...; (76\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Epistola universitatis Parisiensis ad papam pro sedacione\plain \f1\lang1033\fs26  (!) \plain \f1\i\lang1033\fs26 scismatis\plain \f1\lang1033\fs26 <. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Coegit nos tandem pater beatissime}}\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 Christi fides\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 coegit Christiame religionis sincera devotio\plain \f1\lang1033\fs26  ...; (78\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Item epistola eiusdem universitatis Parisiensis ad eundem papam contra id quod dicit precedentem epistolam esse malam et venesam \plain \f1\lang1033\fs26 (!)<. {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Paucis abhinc, pater beatissime diebus exactis}}\plain \f1\i\lang1033\fs26  nobis in mentem venerat\plain \f1\lang1033\fs26  ...; (80\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Item alia epistola eiusdem universitatis Parisiensis ad dominos cardinales pro efficaciter laborando ad extirpacionem scismatis exhoratoria\plain \f1\lang1033\fs26 <. {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Iustum erat, venerabiles domini fratresque}}\plain \f1\i\lang1033\fs26  in Christo carissimi\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 ut quos benignissima mater ecclesia suo\plain \f1\lang1033\fs26  [in] \plain \f1\i\lang1033\fs26 sinu foverat\plain \f1\lang1033\fs26  ...; (82\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Parisiensis universtitas ad universitatem Coloniensem\plain \f1\lang1033\fs26 <. {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Litteras magistri venerabiles vestra nobis ex parte directas}}\plain \f1\i\lang1033\fs26  vidimus\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 quibus ad virtuosam inceptis preserverenciam stabilemque constanciam nos hortamur\plain \f1\lang1033\fs26  ...; (83\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Item epistola eiusdem universitatis Parisiensis ad cardinales exhortatoria ad extirpacionem scismatis\plain \f1\lang1033\fs26 <. {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Et si firmam, reverendissimi patres, animo spem}}\plain \f1\i\lang1033\fs26  ante conceperamus per vestre sollicitudinis vigillantionem sacro sanctam ecclesiam\plain \f1\lang1033\fs26  ...; (84\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Item epistola eiusdem universitatis Parisiensis ad regales literas responsoria \plain \f1\lang1033\fs26 ...<. {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Gratissimas regalis vestre magnificencie princeps serenissimis}}\plain \f1\i\lang1033\fs26  literas sincerissimi ad salutem pacem\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 que ecclesie affectus \plain \f1\lang1033\fs26 ...; (85\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Epistola eiusdem universitatis Parsiensis ad Benedictum xiii\plain \f1\i\super\lang1033\fs24 um\plain \f1\i\lang1033\fs26  in papam electum exhortatoria ad viam cessonis\plain \f1\lang1033\fs26 <. {\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Quanquam}}\plain \f1\lang1033\fs26\chcbpat17 , {\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 pater beatissime}}{\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 , }}{\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 quando ad nos}}\plain \f1\i\lang1033\fs26  Christum perlata fuit Romani pontificatus vacacio\plain \f1\lang1033\fs26  ... (89\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 vestro\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 pater beatissime\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 inggressu\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 spiritus sanctus aspiret progressu\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 comes assistat\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 egressuque exitum feliciter terminent\plain \f1\lang1033\fs26 . \endash  Sammlung von acht Briefen der Universit\u228 \'e4t Paris, in der Regel aus dem Jahr 1394, hier Nicolaus de Clemangiis zugeschrieben; der Anfang identisch mit {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Berlin, SBB PK, Ms. theol. lat. qu. 323}}\plain \f1\lang1033\fs26 , 21\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  und {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Saint Omer, Biblioth\u232 \'e8que de l\rquote agglom\u233 \'e9ration, Ms. 676}}\plain \f1\lang1033\fs26 , Div. 3; vgl. L\u233 \'e9opold Delisle, Le formulaire de Clairmarais, in: Journal des Savants, M\u228 \'e4rz 1899, S. 172 \endash  195, bes. S. 190; alle anderen Briefe sind gedruckt in: C\u233 \'e9sare Egasse Du Boulay, Historia Universitatis Parisiensis, 6 Bde., Paris 1665 \endash  1673, Bd. 4 (1668), S. 699 \endash  715, 719 \endash  720; Denifle, Chartularium, 1891 \endash  1897, Bd. 3 (1894), (76\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ), S. 631 \endash  633, Nr. 1690, (78\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) S. 634 \endash  636, Nr. 1693, (82\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) S. 629, Nr. 1688. }

