\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 89\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Epistola}}\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Lentuli}}\plain \f1\lang1033\fs26 . {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Apparuit temporibus istis et adhuc est homo}}\plain \f1\i\lang1033\fs26  magne virtutis\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  cui nomen est Christus Jesus\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  qui dicitur a gentibus propheta veritatis\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 in colloquio gravis rarus et modestus speciosus inter filios hominum\plain \f1\lang1033\fs26 . \endash  Druck: Ernst von Dobsch\u252 \'fctz, Christusbilder. Untersuchungen zur christlichen Legende, Leipzig 1899, S. 319** \endash  324** ; vgl. ebenda S. 324** \endash  330**; {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Stegm\u252 \'fcller, RB, Nr. 158,1}}\plain \f1\lang1033\fs26 ; VL(2), Bd. 5 (1985), Sp. 705 \endash  709 (Kurt Ruh); Text auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 1021}}\plain \f1\lang1033\fs26 , 108\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26 , vgl. DA LuHB Kat. 4.}

