\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 1\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 , 20\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Ex antiquitatibus regni Bohemiae}}\plain \f1\lang1033\fs26 . (1\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Anno domini M\u176 \'b0 ccccii\u176 \'b0 refacta est dissensio inter magistros}}\plain \f1\i\lang1033\fs26  Theutuicorum et Bohemorum propter bullam cruciatam\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 super Ladislawum regem Napolie datam\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 Anno domini M\u176 \'b0 ccccix facta est visitatio plebanorum per manum secularium per totam terram Bohemie\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 et captiviat \plain \f1\lang1033\fs26 (!)\plain \f1\i\lang1033\fs26  in mediastini civitatis positi\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 nudi cum mulieribus ducti\plain \f1\lang1033\fs26  (20\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 luto maculati in aquis proiecti post confuse de civitatibus expulsi\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 Anno domini M\u176 \'b0cccc xviii et sequentibus percussit dominus terram iiii\plain \f1\i\super\lang1033\fs24 or\plain \f1\i\lang1033\fs26  plagis malis\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 et fetet in terra\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Beatus ab ea et immaculatus\plain \f1\lang1033\fs26 . \endash  Text l\u228 \'e4uft ohne Unterbrechung durch; Druck (nach dieser Handschrift): H\u246 \'f6fler, Geschichtschreiber, 1856 (s. Lit.), S. 76 \endash  78; teilweise auch bei Gelasius Dobner, Monumenta Historica Boemi\u230 \'e6 ..., Bd. 6, Prag 1785, S. 483 \endash  491, bes. S. 487 \endash  489, unter dem Titel: \u8222 \'84Anonymi brevis compilatio chronologica ab anno 1310 usque ad annum 1432\rdblquote ; Palack\u253 \'fd, Documenta, 1869 (s. Lit.), S. 730 \endash  737; vgl. H\u246 \'f6fler (s.o.), S. LV \endash  LVI, Nr. 8. \endash  1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  leer.}

