\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 9\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  29\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Thomas Oliverus}}\plain \f1\lang1033\fs26  (Oliverus Paderbornensis), {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Historia regum Terrae Sanctae}}\plain \f1\lang1033\fs26 , unvollst\u228 \'e4ndig. (9\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) Prolog: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Altissimus super unamquamque gentem posuit custodem}}\plain \f1\i\lang1033\fs26  \plain \f1\lang1033\fs26 ... Kapitel 1: \plain \f1\i\lang1033\fs26 Cum autem pro peccatis suis recepisset duplicia\plain \f1\lang1033\fs26  ... (29\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 nec longo tempore post imperator profectus in Apuliam Salernum expugnavit potenter\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 Panormitanum palatium ac totum regnum\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Sicilie sibi debitum victoriosus obtinuit\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Sic civitas sancta peccatis nostris exigentibus permansit in potestate paganorum\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Hanc historiam cum magna stili brevitate compilavit magister Oliverus Scolasticus Coloniensis apud Damiatam et hanc\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  que sequitur anno m\u176 \'b0 cc\u176 \'b0 xix\u176 \'b0\plain \f1\lang1033\fs26 . \endash  Text bricht in Kapitel 106 ab; Druck: Hoogeweg, Oliverus, 1894 (s. Lit.), S. 83 \endash  153; vgl. ebenda S. LVIII; weitere Lit. s. 3\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 . }

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 29\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  44\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Thomas Oliverus}}\plain \f1\lang1033\fs26  (Oliverus Paderbornensis), {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Historia Damiatina}}\plain \f1\lang1033\fs26 , unvollst\u228 \'e4ndig. (29\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) Prolog: \plain \f1\i\lang1033\fs26 Letetur mons Syon et exultent filie Jude\plain \f1\lang1033\fs26  ... (Ps 47,1 2) \plain \f1\i\lang1033\fs26 scribentes et predicantes annuncient mirabilia\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 dei\plain \f1\lang1033\fs26  ... (29\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) Kapitel 1: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Anno m\u176 \'b0 cc\u176 \'b0 xvii expirante treuga Christianorum et Sarracenorum}}\plain \f1\i\lang1033\fs26  in primo passagio generali post concilium Lateranense congregatus est exercitus domini in Accon\plain \f1\lang1033\fs26  ... (43\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 in super camelorum plurima dampna sustinuerunt Sarraceni\plain \f1\lang1033\fs26 . Unmittelbar anschlie\u223 \'dfend Erg\u228 \'e4nzung: \plain \f1\i\lang1033\fs26 Hiis ita gestis peregrini nostri ocio et crapula torpentes et lucris terrenis inhiantes contra se iram omnipotentis provocabant\plain \f1\lang1033\fs26  ... (44\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 et sedundum diversas naciones dispersi summus in obprobrium nostri sempiternum\plain \f1\lang1033\fs26 . \endash  Redaktion 2 nach Hoogeweg, Oliverus, 1894 (s. Lit.); der Text endet mit Kapitel 53; danach folgt eine Erweiterung \u252 \'fcber das Ende des Kreuzzuges, der nur in der vorliegenden Handschrift \u252 \'fcberliefert wird und nach Hoogeweg nicht von Thomas Oliverus stammt; Druck: Hoogeweg, Oliverus, 1894 (s. Lit.), S. 161 \endash  256 und 280 \endash  282; vgl. ebenda, S. CXLIX \endash  CLXI; Thomas W. Smith, Oliver of Cologne's \plain \f1\i\lang1033\fs26 Historia Damiatina\plain \f1\lang1033\fs26 . A New Manuscript Witness in Dublin, Trinity College Library, Ms 496, in: Hermathena 194 (2013), S. 37 \endash  68, bes. S. 66, Sigle D; weitere Lit. s. 3\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 . }

