\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 111\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Theodoricus de Niem}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Introductio ad Divisionem Regnorum}}\plain \f1\lang1033\fs26 . Am Rand: \plain \f1\i\lang1033\fs26 Testamentum Karoli\plain \f1\lang1033\fs26 . Text: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Quia supra proxime tangitur felix obitus divi Karoli Magni}}\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 ut in aliquibus hystoriis descriptis inferius continetur\plain \f1\lang1033\fs26 . >\plain \f1\i\lang1033\fs26 Hec T. Verdensis electus\plain \f1\lang1033\fs26 <. \endash  Von Kr\u252 \'fcger, Darmst\u228 \'e4dter Handschrift, 1956 (s. Lit.), S. 213 f\u252 \'fcr Theodoricus de Niem in Anspruch genommen; Druck: ebenda S. 213 \endash  214 (nach dieser Handschrift); Colberg/ Leuschner, Dietrich von Nieheim, 1980 (MGH \endash  SS. Staatsschriften, 5,2) (s. Lit.), S. 295 \endash  296; vgl. Mordek, Bibliotheca, 1995 (s. Lit.), S. 119, Sigle DA; weitere Lit. s.u. 115\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 . }

