\pard\fi0\li0\qj\ri0\sb0\sa600\itap0 \plain \f1\lang1033\fs26 94 Bl.\~\~\u183 \'b7\~\~{\field{\*\fldinst HYPERLINK "hida://5130[0]/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Rheinbrohl}}\plain \f1\lang1033\fs26 \~\~{\field{\*\fldinst HYPERLINK "hida://5060[0].5064/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 1434}}
\par \pard\fi0\li0\qj\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs22 Fol. 3 \endash  96\~\~\u183 \'b7\~\~Wasserzeichen: Traube, zweikonturiger Stiel mit Schlaufe, tropfenf\u246 \'f6rmige Beeren, mehrere Varianten, darunter: 1. identisch und sehr \u228 \'e4hnlich WZIS DE2730-PO-129303 (Wetzlar 1435); 2. WZIS DE2730-PO-129271 (Frankfurt a. M. 1433); 3. WZIS DE2040-PO-129243 (Bensberg 1436); 4. sehr \u228 \'e4hnlich WZIS DE3285-PO-129124 (G\u246 \'f6ttingen 1437/38); Krone ohne B\u252 \'fcgel; Reif dreikonturig, Mittelzinken einkonturig mit blattf\u246 \'f6rmigen Enden, mehrere Varianten, darunter: 1. identisch und sehr \u228 \'e4hnlich WZIS DE2040-PO-50510 (1435); 2. WZIS DE2730-PO-50529 (1435); 3. WZIS DE0960-Mgf1303_213 (1401/1500); 4. sehr \u228 \'e4hnlich WZIS DE4620-PO-50515 (Eisenberg 1433); zwei gekreuzte Schl\u252 \'fcssel, runder Griff, zwei Varianten: 1. identisch und sehr \u228 \'e4hnlich WZIS DE2040-PO-120960 (Reifferscheid 1433); 2. sehr \u228 \'e4hnlich WZIS DE2040-PO-120922 (Burg 1435); Pferd, ganze Figur (Gro\u223 \'dffolioformat), sehr \u228 \'e4hnlich Briquet Nr. 3568 (Grammont 1434); S\u228 \'e4ule, zweiteilige Basis und zweiteiliges Kapitel, dar\u252 \'fcber Krone, mehrere Varianten, darunter: 1. WZIS DE2040-PO-100197 (1435); 2. identisch und sehr \u228 \'e4hnlich WZIS DE4215-PO-100209 (1434); 3. \u228 \'e4hnlich WZIS DE5580-Clm6502_232 (1433/1440, Basel (Konzil))\~\~\u183 \'b7\~\~Schriftraum: 23 \endash  24,5 x 15 \endash  16; seitliche Schriftraumbegrenzung mit Graphitstiftlinien oder durch L\u228 \'e4ngsfaltungen\~\~\u183 \'b7\~\~36 \endash  55 Zeilen; Zeilenzahl je nach Text und Schreiberhand variierend\~\~\u183 \'b7\~\~Bastarda mit Schleifen wohl von mehreren, mindestens drei H\u228 \'e4nden (s.u.)\~\~\u183 \'b7\~\~Explizit 92\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22  und \u220 \'dcberschriften in Textura; \u220 \'dcberschriften au\u223 \'dferdem in vergr\u246 \'f6\u223 \'dfertem Schriftgrad, einger\u252 \'fcckt und abgesetzt; 22\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  \endash  49\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  in Rot; 3\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  \endash  21\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  auf die Blattr\u228 \'e4nder ger\u252 \'fcckte, unterstrichene Lemmata\~\~\u183 \'b7\~\~22\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  \endash  49\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  rubriziert\~\~\u183 \'b7\~\~Raum f\u252 \'fcr 3-7zeilige Anfangsbuchstaben ausgespart, z.T. mit Rubrikatorvorgaben.}

