\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 121\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  143\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Konrad von Soltau}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Lectura}}\plain \f1\lang1033\fs26  super \u8218 \'82Firmiter credimus\lquote . (121\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) ({\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 F)}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 irmiter credimus et simpliciter confitemur}}\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Fidem Orthodoxam fidelium\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 solidum et primum omnium virtutum immobile fore fundamentum, auctorizans magister gencium Paulus Apostolus ad Heb. \plain \f1\lang1033\fs26 ... (142\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Post articulum de gloriosa resurreccione proponitur nunc articulus de gaudiosa ipsius ascensione\plain \f1\lang1033\fs26  ... (143\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 et hoc fecit Christus in eius ascensione\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 Ad questionem secundam\plain \f1\lang1033\fs26 : \plain \f1\i\lang1033\fs26 An Christus ascenderit in celum\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 secundum quod homo\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 vel secundum quod deus\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  videtur quod non assit\plain \f1\lang1033\fs26  \u9553 \'a6. \endash  Text endet unvermittelt; vgl. Ludwig Schmitz-Kallenberg, Conrad von Soltau, Diss. Leipzig 1891; {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Stegm\u252 \'fcller, RS, Nr. 176}}\plain \f1\lang1033\fs26 ; Bloomfield/ Guyot, Incipits, Nr. 2146; Newhauser/ Bejczy, Bloomfield, 2008, Nr. 2146; Jana Nechutov\u224 \'e0, Konrad von Soltau: \u8222 \'84Lectura super caput Firmiter\ldblquote , in: Fritz Peter Knapp u.a. (Hrsg.), Schriften im Umkreis mitteleurop\u228 \'e4ischer Universit\u228 \'e4ten um 1400. Lateinische und volkssprachige Texte aus Prag, Wien und Heidelberg: Unterschiede, Gemeinsamkeiten, Wechselbeziehungen. Leiden 2004 (Education and Society in the Middle Ages and Renaissance, Bd. 20), S. 3 \endash  19; VL(2), Bd. 11 (2004), Sp. 880 \endash  886, bes. Sp. 883 \endash  884 (Franz Josef Worstbrock); C.A.L.M.A., Bd. 3 (2011), S. 8 \endash  9 (E. Chiti). \endash  143\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  leer. }

