\pard\fi0\li0\qj\ri0\sb0\sa600\itap0 \plain \f1\lang1033\fs26 108 Bl.\~\~\u183 \'b7\~\~{\field{\*\fldinst HYPERLINK "hida://5130[0]/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Rheinland}}\plain \f1\lang1033\fs26  (?)\~\~{\field{\*\fldinst HYPERLINK "hida://5060[0].5064/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 15. Jh. Mitte}}
\par \pard\fi0\li0\qj\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs22 Fol. 144 \endash  246\~\~\u183 \'b7\~\~Wasserzeichen: Traube, zweikonturiger Stiel mit Schlaufe, tropfenf\u246 \'f6rmige Beeren, mehrere Varianten, darunter: 1. sehr \u228 \'e4hnlich WZIS DE2610-PO-129020 (Plochingen 1441); 2. sehr \u228 \'e4hnlich WZIS DE2610-PO-129015 (Esslingen 1440); Traube, einkonturiger Stiel mit Schlaufe, tropfenf\u246 \'f6rmige Beeren, mehrere Varianten, darunter: 1. WZIS DE2730-PO-128855 (1452); 2. WZIS DE2040-PO-128850 (Blankenburg 1445)\~\~\u183 \'b7\~\~Reklamanten, beschnitten, z.T. verloren\~\~\u183 \'b7\~\~144\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  \endash  167\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  jeweils recto auf dem Kopfsteg mittig, alte Tintenfoliierung mit arabischen Ziffern in Rot: \plain \f1\i\lang1033\fs22 I \endash  24\plain \f1\lang1033\fs22 \~\~\u183 \'b7\~\~Schriftraum: 21,5 \endash  22,5 x 14,5 \endash  16; seitliche Spaltenbegrenzungen entweder mit Tintenlinien oder durch L\u228 \'e4ngsfaltungen\~\~\u183 \'b7\~\~zweispaltig; 242\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  dreispaltig; 242\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22  vierspaltig\~\~\u183 \'b7\~\~36 \endash  45 Zeilen; Zeilenzahl je nach Schreiberhand variierend\~\~\u183 \'b7\~\~Bastarda mit Schleifen von mehreren, mindestens drei H\u228 \'e4nden\~\~\u183 \'b7\~\~144\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs22  \endash  167\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs22 , 221\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs22  \endash  222\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs22  rote, vereinzelt auch rot unterstrichene \u220 \'dcberschriften; 167\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22  \endash  221\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  und 222\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22  \endash  244\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22  \u220 \'dcberschriften nur einger\u252 \'fcckt und abgesetzt\~\~\u183 \'b7\~\~144\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs22  \endash  167\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs22  und 221\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs22  \endash  222\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs22  rubriziert\~\~\u183 \'b7\~\~144\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs22  \endash  167\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs22  und 222\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs22  2zeilige rote Lombarden, 167\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22  \endash  221\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  und 222\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22  \endash  224\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22  Aussparungen f\u252 \'fcr 2zeilige Anfangsbuchstaben, oft mit Rubrikatorvorgaben\~\~\u183 \'b7\~\~144\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs22  9zeilige rote S-Initiale mit Aussparungsornamentik\~\~\u183 \'b7\~\~191\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs22  gro\u223 \'dfe Notahand in brauner Federzeichnung.}

