\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 35\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  42\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Johannes de Garlandia}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Liber de compositionibus}}\plain \f1\lang1033\fs26 . (35\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 An si proponas, puto, scindit de dat, infert}}\plain \f1\lang1033\fs26  ... (42\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 ars dat contiguum naturaque continuum dat\plain \f1\lang1033\fs26 . >\plain \f1\i\lang1033\fs26 Explicit textus composicionem\plain \f1\lang1033\fs26 <. \endash  Vereinzelt mit punktuellen Glossen und Erg\u228 \'e4nzungen auf den Blattr\u228 \'e4ndern; vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 885}}\plain \f1\lang1033\fs26 ; Bursill-Hall, Johannes de Garlandia, 1976 (s. 3\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ), S. 172 \endash  173, Nr. 18; weitere Lit. s. 3\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ; Text auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 22}}\plain \f1\lang1033\fs26 , 144\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 . }

