\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 43\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  50\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Johannes de Garlandia}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Liber de deponentialibus}}\plain \f1\lang1033\fs26  (Verba deponentialia). (43\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Vescor cum potior}}\plain \f1\lang1033\fs26\chcbpat17 , {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 fungor addas}}\plain \f1\i\lang1033\fs26  fruor\plain \f1\lang1033\fs26  (?) \plain \f1\i\lang1033\fs26 et utor\plain \f1\lang1033\fs26  ... (50\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Exequitur regis mandatum quisque fidelis\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Explicit textus verborum deponencium\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 deo gracias\plain \f1\lang1033\fs26 . \endash  Druck: {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 GW M13855 \endash  13930}}\plain \f1\lang1033\fs26 ; vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 20264}}\plain \f1\lang1033\fs26 ; Bursill-Hall, Johannes de Garlandia, 1976 (s. 3\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ), S. 167 \endash  169, Nr. 13; weitere Lit. s. 3\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 .}

