\pard\fi0\li0\qj\ri0\sb600\sa0\itap0 \plain \f1\lang1033\fs26 54\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  55\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Versus}}\plain \f1\lang1033\fs26  de diversis.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (54\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  54\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) Versus de signis zodiaci. (54\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Aries. In capiti facies aries cum luna refulget}}\plain \f1\lang1033\fs26  ... (54\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Pisces\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 plantas ne medites legatos mittere potes\plain \f1\lang1033\fs26 . \endash  Vgl. Roth, Mittellat. Hss., 1891, S. 259; {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 1403, 2408, 8837, 10484, 19012}}\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Proverbia, Nr. II/1, 1255; II/3, 21123; II/1, 3402; II/2, 14108; II/1, 2327; II/5, 31038}}\plain \f1\lang1033\fs26 ; \u228 \'e4hnlich {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Proverbia, Nr. II/3, 16681}}\plain \f1\lang1033\fs26 ; Thorndike/ Kibre 1963, Sp. 666,1; Druck: Ph. Rosenthal, Poeseos medii aevi medicae specimina nonnulla minus cognita, Breslau 1842, S. 38 \endash  39; Salvatore de Renzi (Hrsg.), Collectio Salernitana ossia documenti inediti e trattati di medicina appartenenti alla scuola medica Salernitana, 5 B\u228 \'e4nde, Neapel 1852 \endash  1859 (Biblioteca di Storia della Medicina, Bd. 2,5), Reprint Bologna 1967, Bd. 5, S. 53, Vers 1831 \endash  1863. 
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (54\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) Merkvers zu Sternzeichen und Himmelsrichtungen mit \u252 \'fcbergeschriebenen Buchstaben. \plain \f1\i\lang1033\fs26 Orientalia\plain \f1\lang1033\fs26  (dar\u252 \'fcber: \plain \f1\i\lang1033\fs26 c\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 s\plain \f1\lang1033\fs26 ), \plain \f1\i\lang1033\fs26 meridionalia\plain \f1\lang1033\fs26  (dar\u252 \'fcber: \plain \f1\i\lang1033\fs26 f\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 s\plain \f1\lang1033\fs26 ), \plain \f1\i\lang1033\fs26 occidentalia\plain \f1\lang1033\fs26  (dar\u252 \'fcber: \plain \f1\i\lang1033\fs26 c\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 h\plain \f1\lang1033\fs26 ), \plain \f1\i\lang1033\fs26 Ar. le. da. than. ur. cap. gemi. lib. aqua\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Septentrionalia\plain \f1\lang1033\fs26  (dar\u252 \'fcber: \plain \f1\i\lang1033\fs26 f\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 h\plain \f1\lang1033\fs26 ), \plain \f1\i\lang1033\fs26 can. ster. pisces\plain \f1\lang1033\fs26 . 
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (54\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \endash  55\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) Versus de Apostolis. (54\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) Rubrik: \plain \f1\i\lang1033\fs26 Versus de martiriis Apostolorum\plain \f1\lang1033\fs26 . Text: \plain \f1\i\lang1033\fs26 Petrus et Andreas, Philippus sunt crucifixi\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 Barnebas ustus\plain \f1\lang1033\fs26  (!), \plain \f1\i\lang1033\fs26 Matheus fessus in ara\plain \f1\lang1033\fs26 . \endash  Acht Verse; vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 14055, 14046}}\plain \f1\lang1033\fs26 ; (54\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \endash  55\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) Rubrik: \plain \f1\i\lang1033\fs26 Versus et significationes quatuor Ewangelistarum\plain \f1\lang1033\fs26 . (54\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) Text: \plain \f1\i\lang1033\fs26 Est homo Matheus\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 Lucas vitulus\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 leo Marcus\plain \f1\lang1033\fs26  ... (55\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Lucas bos pictus in cruce victima Christus\plain \f1\lang1033\fs26 . \endash  Acht Verse; vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 5689}}\plain \f1\lang1033\fs26 ; (55\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) Rubrik: \plain \f1\i\lang1033\fs26 Versus de actibus Apostolorum quas quisquis gentes convertit\plain \f1\lang1033\fs26 . Text: \plain \f1\i\lang1033\fs26 Petrus\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Per me Romana plebs respuit ydolo vana\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 Philippus. Ydola calcavi Persas baptismate lavi\plain \f1\lang1033\fs26 . \endash  Zw\u246 \'f6lf Verse; vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 13947}}\plain \f1\lang1033\fs26 ; (55\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) Rubrik: \plain \f1\i\lang1033\fs26 Versus de singulis martyriis Apostolorum magistri Gerhardi\plain \f1\lang1033\fs26 . Text: \plain \f1\i\lang1033\fs26 Petrus\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Scala crucis tibi in ore ducis Petre fit via lucis\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 Mathyas\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Pandit iter patrie geminatus mutus\plain \f1\lang1033\fs26  (?) \plain \f1\i\lang1033\fs26 Mathye\plain \f1\lang1033\fs26  (?). \endash  Zw\u246 \'f6lf Verse; vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 17312}}\plain \f1\lang1033\fs26 ; (55\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) Rubrik: \plain \f1\i\lang1033\fs26 De omnibus Apostolis duo versus\plain \f1\lang1033\fs26 . Text: \plain \f1\i\lang1033\fs26 Dominibus sanctus. More ducum ferentes collant pro rege cohortes\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 per varias sortes varias exordine mortes.\plain \f1\lang1033\fs26  \endash  Zwei Verse; (55\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Petrus eram quem petra tegit\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 sic dimisit utraque petra Petrum\plain \f1\lang1033\fs26 . \endash  Sechs Verse; vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 14050}}\plain \f1\lang1033\fs26 ; \plain \f1\i\lang1033\fs26 Respice qui transis\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 cineri cinis indico\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 quam sis\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 Tu qui es ante sui nunc memor esto tui\plain \f1\lang1033\fs26 . \endash  Vier Verse; vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 16667}}\plain \f1\lang1033\fs26 ; \plain \f1\i\lang1033\fs26 Quisquis ades\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 qui morte cades sta prolege plora\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 et postrema dies hec sit\plain \f1\lang1033\fs26  (?) \plain \f1\i\lang1033\fs26 prima quies\plain \f1\lang1033\fs26 . \endash  Sechs Verse; vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 16140}}\plain \f1\lang1033\fs26 ; \plain \f1\i\lang1033\fs26 Da Petre claviger ut polus astriger huic reseretur\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 flexerat huc iter\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 ut tibi dulciter obsequeretur\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Huius defunctii post mortem discite cuncti\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 Utere prospeciare hiis hominum tumulis\plain \f1\lang1033\fs26 . \endash  Zehn Verse; die beiden ersten Verse bei Wilhelm Wattenbach, Zwei Handschriften der k. Hof- und Staatsbibliothek, in: Sitzungsberichte der philosophisch-philologischen und historischen Classe der k. b. Akademie der Wissenschaften zu M\u252 \'fcnchen 3 (1873), S. 685 \endash  747, bes. S. 745; Rubrik: \plain \f1\i\lang1033\fs26 Tot fuerunt angeli\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 qui de celo ceciderunt.\plain \f1\lang1033\fs26  Text: \plain \f1\i\lang1033\fs26 Nota decies x faciunt centum\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 decies centum faciunt mille\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 decem phalagies faciunt turmam\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 decem turme homini si invenis decem appone singulis vii\plain \f1\i\super\lang1033\fs24 te\plain \f1\lang1033\fs26 . \endash  Acht Verse. }

