\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 56\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  57\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Versus}}\plain \f1\lang1033\fs26  de conflictu vitiorum et virtutum. (56\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) Rubrik: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Hic incipitur arborum bonorum et malorum versifice}}\plain \f1\lang1033\fs26 . Text: \plain \f1\i\lang1033\fs26 Prima radix\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Despiceo \plain \f1\lang1033\fs26 (!)\plain \f1\i\lang1033\fs26  miseros quia dicere maximus eros\plain \f1\lang1033\fs26 : \plain \f1\i\lang1033\fs26 Superbus dicit\plain \f1\lang1033\fs26  ... (57\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Conclusio postrema huius arboris\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Nullis applaudo nec parco sed omnia claudo\plain \f1\lang1033\fs26 : \plain \f1\i\lang1033\fs26 Mors dicit\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Do vite fructum mortis sunt exercere luctum\plain \f1\lang1033\fs26 : \plain \f1\i\lang1033\fs26 vita perhennis\plain \f1\lang1033\fs26 . \endash  Vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 4291}}\plain \f1\lang1033\fs26 ; au\u223 \'dferdem enthalten: {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Nr. 2500}}\plain \f1\lang1033\fs26 ; Walther, Streitgedicht, 1920/ 1984, S. 115 \endash  126; Bloomfield/ Guyot, Incipits, Nr. 1529; Newhauser/ Bejczy, Bloomfield, 2008, Nr. 1529. }

