\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 58\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Publius Lentulus}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Epistula}}\plain \f1\lang1033\fs26  ad senatum Romanum. Vers: \plain \f1\i\lang1033\fs26 Forma Jesu qualis fuerit\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  dat litera talis\plain \f1\lang1033\fs26 . Text: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Legitur in libris annalibus Romanorum}}\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 quod dominus noster Jesus Christus\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 qui dictus fuit a gentibus propheta veritatis\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 ipse enim est rex glorie\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 in quem desiderant angeli prospicere\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 cuius puchritudinem sol et luna mirantur\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 salvator mundi\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 auctor vite\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  ipsi honor et gloria et potestas et imperium per mirifica seculorum secula amen\plain \f1\lang1033\fs26 . \endash  \u8222 \'84Annalen-Text a\ldblquote  nach Dobsch\u252 \'fctz (s.u.); Druck: Dobsch\u252 \'fctz, Christusbilder, 1899, Beilage VIII.B, S. 319**; vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Stegm\u252 \'fcller, RB, Nr. 158,1}}\plain \f1\lang1033\fs26 ; VL(2), Bd. 5 (1985), Sp. 705 \endash  709 (Kurt Ruh); Text auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 535}}\plain \f1\lang1033\fs26 , 44\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ; vgl. DA LuHB Kat. 4, S. 147; {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 2276}}\plain \f1\lang1033\fs26 , 50\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ; vgl. DA ULB Kat. 5,2. }

