\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 59\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  59\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Salomon et Marcolfus}}\plain \f1\lang1033\fs26 , Auszug. (59\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Hic est disputatio Salomonis cum Marcolfo etc\plain \f1\lang1033\fs26 .< {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Salomon dicit: Mulier bona super omnia bona}}\plain \f1\i\lang1033\fs26  et mulier mala super omnia mala\plain \f1\lang1033\fs26  ... (59\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Item Salomon interrogat Marcolfum\plain \f1\lang1033\fs26 <. \plain \f1\i\lang1033\fs26 Ubi est tuus pater et tua mater\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 iocunda risit\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 modo pregnans plorat\plain \f1\lang1033\fs26 . \endash  Zum Textbestand vgl. Benary, Salomon et Marcolfus, 1914 (s. Lit.), S. XXIV \endash  XXV; Druck: ebenda, S. 1 \endash  45; vgl. Griese, Salomon und Markolf, 1999, S. 3 \endash  6 mit Abb. 1a und 1b (59\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  und 59\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ), S. 36 \endash  37, 59, 73, Sigle D; VL(2), Bd. 2 (1980), Sp. 80 \endash  86 (Michael Curschmann); Nancy Mason Bradbury, Rival Wisdom in the Latin Dialogue of Solomon and Marcolf, in: Speculum 83/2 (2008), S. 331 \endash  365; bes. S. 331, Anm. 1; direkt anschlie\u223 \'dfend Sprichwort: \plain \f1\i\lang1033\fs26 Das cui vis\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 quod vis\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 quantum vis\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 tempore quovis\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Tu spiras\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 ubi vis\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 tua munera dividis\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 ut\plain \f1\lang1033\fs26  (?) \plain \f1\i\lang1033\fs26 vis\plain \f1\lang1033\fs26 . \endash  Vgl. Werner, Sprichw\u246 \'f6rter, \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs26 1966, S. 37, Nr. 14; {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Proverbia, Nr. II/1, 4962}}\plain \f1\lang1033\fs26 ; TPMA, Bd. 13 (2002), S. 218, Z. 272; }

