\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 59\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \endash  60\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Carmen}}\plain \f1\lang1033\fs26  \u8218 \'82Vado mori\lquote . (59\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Vado mori res certa quidem nil cercius illa}}\plain \f1\lang1033\fs26  ... (60\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Spernens presentem sic bene vado mori\plain \f1\lang1033\fs26 . \endash  Vgl. Storck, \u8218 \'82Vado mori\lquote ,1910, S. 422 \endash  428, bes. S. 426 \endash  428 (Druck)\plain \f2\lang1024\fs26 ; Rudolf, Ars moriendi, 1957, S. 49 \endash  51, 122 \endash  123; Zato\u269 \'e8il, Lateinische Texte,\plain \f1\lang1033\fs26  1977, S. 7 \endash  21; {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 4962}}\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Proverbia, Nr. II/1, 4962}}\plain \f1\lang1033\fs26  (?); Text auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 815}}\plain \f1\lang1033\fs26 , hinterer Spiegel; {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 1988}}\plain \f1\lang1033\fs26 , 146\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 . }

