\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 61\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Versus}}\plain \f1\lang1033\fs26  de diversis. 1. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Per primum potum unum non est mihi notum}}\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 per potum quartum mens mea tendit in altum\plain \f1\lang1033\fs26 . \endash  Vier Verse; Druck: Roth, Mittellat. Hss., 1891, S. 259; {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 13957 \endash  13958}}\plain \f1\lang1033\fs26 ; 2. \plain \f1\i\lang1033\fs26 Est tarde nimium\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 qui post flatum vult claudere culum\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Est tarde nimium\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 qui post litem vult querere scutum\plain \f1\lang1033\fs26 . \endash  Zwei Verse; Druck: Roth, Mittellat. Hss., 1891, S. 259; Werner, Sprichw\u246 \'f6rter, \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs26 1966, S. 48, Nr. 106; 3. \plain \f1\i\lang1033\fs26 Quatuor\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 ut fantur\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 sunt\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 que numquam faciantur\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Ignis\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 os\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 fulve\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 pelagus\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 infernique furago\plain \f1\lang1033\fs26 . \endash  Druck: Roth, Mittellat. Hss., 1891, S. 259; Werner, Sprichw\u246 \'f6rter, \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs26 1966, S. 97, Nr. 53 (mit tw. abweichendem Wortlaut); {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Proverbia, Nr. II/4, 23696}}\plain \f1\lang1033\fs26 ; 4. \plain \f1\i\lang1033\fs26 Vult sal cultellum\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 coclearia mensa\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 flabellum\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 dicit\plain \f1\lang1033\fs26  (?) \plain \f1\i\lang1033\fs26 discos\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 saturas\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 panes\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 ciphos\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 quoque mapas\plain \f1\lang1033\fs26 . \endash  Druck: Roth, Mittellat. Hss., 1891, S. 259; Werner, Sprichw\u246 \'f6rter, \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs26 1966, S. 127, Nr. 144 (mit tw. abweichendem Wortlaut); 5. \plain \f1\i\lang1033\fs26 Propter pulmentum sunt coclearia bene centum\plain \f1\lang1033\fs26 . \endash  Druck: Werner, Sprichw\u246 \'f6rter, \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs26 1966, S. 94, Nr. 135; 6. \plain \f1\i\lang1033\fs26 Induit hunc sacro reliquium\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 qui prevalet uno\plain \f1\lang1033\fs26 . \endash  Druck: Roth, Mittellat. Hss., 1891, S. 260; Werner, Sprichw\u246 \'f6rter, \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs26 1966, S. 62, Nr. 86 (mit tw. abweichendem Wortlaut); {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 9293}}\plain \f1\lang1033\fs26 ; 7. \plain \f1\i\lang1033\fs26 Armati nudum non privant quatuor unum\plain \f1\lang1033\fs26 . \endash  Druck: Roth, Mittellat. Hss., 1891, S. 260; Werner, Sprichw\u246 \'f6rter, \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs26 1966, S. 23, Nr. 115; {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 1489}}\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Proverbia, Nr. II/1, 1358}}\plain \f1\lang1033\fs26 ; 8. \plain \f1\i\lang1033\fs26 Debetur \plain \f1\lang1033\fs26 (?) \plain \f1\i\lang1033\fs26 palpare non posse visum habere\plain \f1\lang1033\fs26 . 9. \plain \f1\i\lang1033\fs26 Pulchrior nunc esset, si firmus non cecidisset\plain \f1\lang1033\fs26 . \endash  Druck: Werner, Sprichw\u246 \'f6rter, \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs26 1966, S. 95, Nr. 156; {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Proverbia, Nr. II/3, 22852}}\plain \f1\lang1033\fs26 ; 10. \plain \f1\i\lang1033\fs26 Hic cui sor dederit\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 sponsam secum bene ducit\plain \f1\lang1033\fs26 . Druck: Werner, Sprichw\u246 \'f6rter, \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs26 1966, S. 57, Nr. 16; 11. \plain \f1\i\lang1033\fs26 Morbo cessante manet eger\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 ut fuit ante\plain \f1\lang1033\fs26 . \endash  Druck: Werner, Sprichw\u246 \'f6rter, \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs26 1966, S. 70, Nr. 40; {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Proverbia, Nr. II/2, 15048}}\plain \f1\lang1033\fs26 ; 12. \plain \f1\i\lang1033\fs26 Libera res cunctas precellit in orbe voluntas\plain \f1\lang1033\fs26 . }

