\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 67\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Versus}}\plain \f1\lang1033\fs26  de diversis, dt. u. lat. 1. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Manig man treit banzer}}\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 est viribus quasi cancer\plain \f1\lang1033\fs26 . \endash  Druck: Roth, Mittellat. Hss., 1891, S. 260; {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 10651}}\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Proverbia, Nr. II/2, 14424}}\plain \f1\lang1033\fs26 ; 2. \plain \f1\i\lang1033\fs26 Lenonem lena non diligit abseque crumena\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Non diligo te propter te\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 sed te tua propter\plain \f1\lang1033\fs26 . \endash  Druck: Roth, Mittellat. Hss., 1891, S. 260; Werner, Sprichw\u246 \'f6rter, \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs26 1966, S. 67, Nr. 33; {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 10256}}\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Proverbia, Nr. II/2, 13659}}\plain \f1\lang1033\fs26 ; 3. \plain \f1\i\lang1033\fs26 Mus et canes intimi \plain \f1\lang1033\fs26 (?)\plain \f1\i\lang1033\fs26  sunt semper ad mensam primi\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 non invitati veniunt prandem parati\plain \f1\lang1033\fs26 . \endash  Druck: Werner, Sprichw\u246 \'f6rter, \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs26 1966, S. 72, Nr. 97 (mit tw. abweichendem Wortlaut); {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Proverbia, Nr. II/2, 15786}}\plain \f1\lang1033\fs26 ; 4. \plain \f1\i\lang1033\fs26 Si fueris quarum partiter particulorum\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 hanc discas artem maiorem suscipe partem\plain \f1\lang1033\fs26 . \endash  {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Proverbia, Nr. II/4, 28520}}\plain \f1\lang1033\fs26 ; 5. \plain \f1\i\lang1033\fs26 Gutta cavat lapidem non vi\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 sed sepe cadendo\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Sic homo addiscit non vi\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  sed sepe legendo\plain \f1\lang1033\fs26 . \endash  Druck: Werner, Sprichw\u246 \'f6rter, \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs26 1966, S. 56, Nr. 36; {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Proverbia, Nr. II/2, 10508}}\plain \f1\lang1033\fs26 ; 6. \plain \f1\i\lang1033\fs26 Ter quinquaginta David canit ordine Psalmus\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Versus bis mille sescentos sex canit ille\plain \f1\lang1033\fs26 . \endash  Druck: Werner, Sprichw\u246 \'f6rter, \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs26 1966, S. 119, Nr. 25; {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 19209}}\plain \f1\lang1033\fs26 ; 7. \plain \f1\i\lang1033\fs26 Qui Psalmos resecat et verba Davitica curtat\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 talia lucrum ferat tamque sua ligwa \plain \f1\lang1033\fs26 (!)\plain \f1\i\lang1033\fs26  taceret\plain \f1\lang1033\fs26 . \endash  Druck: Werner, Sprichw\u246 \'f6rter, \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs26 1966, S. 100, Nr. 120 (mit tw. abweichendem Wortlaut); {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 15615}}\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Proverbia, Nr. II/4, 24574}}\plain \f1\lang1033\fs26 ; 8. \plain \f1\i\lang1033\fs26 Ludos stultorum dominorum sive luporum\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 semper vitabis et eis te numquam associabis\plain \f1\lang1033\fs26 . \endash  Druck: Werner, Sprichw\u246 \'f6rter, \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs26 1966, S. 68, Nr. 68; 9. \plain \f1\i\lang1033\fs26 Est arbor quedam ramos duodenos tenens in se\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Ramorum quisque quatuor nidos tenet in se\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Nidorum quisque septem volucres tenet in se\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Et volucrum quisque nomen habebit spirituale\plain \f1\lang1033\fs26 . \endash  Druck: Werner, Sprichw\u246 \'f6rter, \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs26 1966, S. 46, Nr. 27 (m. abweichendem Wortlaut); {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 5596}}\plain \f1\lang1033\fs26 ; die gleichen Verse als Glosse zu Alexander de Villa Dei, Doctrinale, Pars 1 auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 2642}}\plain \f1\lang1033\fs26 , 91\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ; sowie als R\u228 \'e4tsel in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 86}}\plain \f1\lang1033\fs26 , 67\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 .  }

