\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  123\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Francesco Petrarca}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 De vita solitaria}}\plain \f1\lang1033\fs26 . (1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Liber Francisci Petrarche de vita solitaria\plain \f1\lang1033\fs26 <. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Paucos homines novi quibus opusculorum meorum}}\plain \f1\i\lang1033\fs26  tanta dignetio\plain \f1\lang1033\fs26  (!) ... (123\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Recte consulis verum dicis\plain \f1\lang1033\fs26 . >\plain \f1\i\lang1033\fs26 Explicit liber Francisci Petrarche poete laureati de laude vite solitarie\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Scriptus et completus anno domini 1450 ipso die beati Johannis Ewangeliste ante Portam Latinam \plain \f1\lang1033\fs26 (6. Mai 1450). \plain \f1\i\lang1033\fs26 Deo gracias\plain \f1\lang1033\fs26 <. \endash  Druck: Martelotti, Francesco Petrarca. Prose, 1955, S. 286 \endash  590; Mann/ Carraud, P\u233 \'e9traque. De vita solitaria, 1999; Teiledition (Buch 1): Enenkel, De vita solitaria, 1990, S. 55 \endash  123; zur handschriftlichen \u220 \'dcberlieferung vgl. ebenda, S. 42 \endash  51, bes. S. 44, Nr. 18; au\u223 \'dferdem Sottili, Studenti, 1968 (s. Lit.), S. 65 \endash  66; ders., I codici, 1971, S. 469 \endash  470, Nr. 15; Text auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 673}}\plain \f1\lang1033\fs26 , 36\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs26 ; vgl. DA LuHB Kat. 4, S. 158; {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 671}}\plain \f1\lang1033\fs26 , 5\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 . }

