\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 62\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  66\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Gebet}}\plain \f1\lang1033\fs26  \u8218 \'82Von dem inneren Leiden Jesu Christi\lquote , dt. (62\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 >Dat is dat inwendige liden uns leywen heren Jesu Christi\plain \f1\lang1033\fs26 <. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Dit is dat inwendige liden uns leyven heren Jesu Christi}}\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  dat en sal neman lesen noch horen lesen, dan mit inwendiger bewegingen sinre selen ind\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 mit ernstiger andacht\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 In deme hilgen avent essen do du myn alre leyfste here Jesu Christe gewesschen haddes dynre leyver iongeren voisse\plain \f1\lang1033\fs26  ... (66\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 also dat ich myne leve dage dyn unschuldich liden in myme hertzen dragen mochte\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Amen\plain \f1\lang1033\fs26 . \endash  Text auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 2694}}\plain \f1\lang1033\fs26 , 133\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ; vgl. DA LuHB Kat. 6, S. 133; {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 1923}}\plain \f1\lang1033\fs26 , 54\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 3136}}\plain \f1\lang1033\fs26 , 2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ; vgl. DA LuHB Kat. 1, S. 231 und 301; au\u223 \'dferdem in {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 K\u246 \'f6ln, HistASt, W 12\u176 \'b0 60}}\plain \f1\lang1033\fs26 , 148\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 .}

