\uc1
\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 100\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  102\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Spr\u252 \'fcche}}\plain \f1\lang1033\fs26 , deutsch. \endash  Meist kurze, gelegentlich auch l\u228 \'e4ngere Zitate und Spr\u252 \'fcche, u.a. Augustinus, Anselmus, Bernardus, Gregorius und Ambrosius zugewie\-sen; mystische Lebensweisheiten und Verhaltensregeln zu unterschiedlichen Themen. }

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

