\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 158\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Vom Wunder bewirken}}\plain \f1\lang1033\fs26 . {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Ein meister spricht: He sin lude up ertriche de mynire zichen}}\plain \f1\i\lang1033\fs26  doynt dan sent Peter dede\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 dat he de doden up dede stayn\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 und blynde syen dede\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 und kruppel gaynde\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 dat sterven bewelt gode bas unde is\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 in lustiger\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 want it van mynnem geschuyt dan of he hondert dusent doden up dede stayn\plain \f1\lang1033\fs26 . >\plain \f1\i\lang1033\fs26 Dit Ier\plain \f1\lang1033\fs26 <. \endash  Ein gottgef\u228 \'e4lliges Leben zu f\u252 \'fchren ist mehr wert, als hunderttausend Tote zu erwecken oder Wunder zu bewirken; Parallel\u252 \'fcberlieferung: {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 K\u246 \'f6ln, HistASt, GB oct. 10}}\plain \f1\lang1033\fs26 , 6\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 .}

