\pard\fi0\li0\qj\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs22 Roth, Literatur, 1891, S. 18\~\~\u183 \'b7\~\~Staub, Wimpfen, 1980, S. 23 und 85\~\~\u183 \'b7\~\~Dicke/ Grubm\u252 \'fcller, Fabeln, 1987, S. LXIII\~\~\u183 \'b7\~\~Kr\u228 \'e4mer, Handschriftenerbe, 1989, Bd. 2, S. 838\~\~\u183 \'b7\~\~Hasebrink, Latinit\u228 \'e4t, 2000, S. 49 \endash  76, bes. 49 \endash  50\~\~\u183 \'b7\~\~Almut Suerbaum, Litterae et mores. Zur Textgeschichte der mittelalterlichen Avian-Kommentare, in: Klaus Grubm\u252 \'fcller (Hrsg.), Schulliteratur im sp\u228 \'e4ten Mittelalter, M\u252 \'fcnchen 2000 (M\u252 \'fcnstersche Mittelalter-Schriften, Bd. 69), S. 383 \endash  434, bes. S. 432\~\~\u183 \'b7\~\~Aaron E. Wright, \u8218 \'82Hie lert uns der meister\lquote . Latin Commentary and the German Fable 1350 \endash  1500, Tempe (Arizona State University) 2001 (Medieval and Renaissance Texts and Studies, Bd. 218), S. 15 \endash  22 (mit falscher Signatur: Cod. 23b)\~\~\u183 \'b7\~\~Baldzuhn, Schulb\u252 \'fccher, 2009, Bd. 2, S. 491 \endash  494\~\~\u183 \'b7\~\~Klein-Ilbeck, dat. Hss.}

