\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 107\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Merkverse}}\plain \f1\lang1033\fs26  \u8218 \'82Pro scholaribus\lquote . 1. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Quinque sunt claves sapiencie: timor domini, reverencia magistri}}\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 assidua lectio\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 memoria lectorum\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 frequens questio\plain \f1\lang1033\fs26 . \endash  Vgl. Hasebrink, Latinit\u228 \'e4t, 2000, bes. S. 49 \endash  50; 2. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Quinque sunt moderamina doctrine: correctio viciorum, instructio in moribus}}\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 gratus sermo\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 congrua distribucio doctrine\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 solicitatio frequens\plain \f1\lang1033\fs26 . 3.{\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17  Discipulus debet esse subiectus magistro, attentus exercitio, benivolus anim}}\plain \f1\i\lang1033\fs26 o\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 docilis ingenio\plain \f1\lang1033\fs26 , [discipulus debet] \plain \f1\i\lang1033\fs26 evitare coitum\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 gulositatem\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 ornatum vestium\plain \f1\lang1033\fs26 . 4. {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Discolus est ille, qui discurrit per vicos et plateas}}\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 omnibus istis scola est postposita\plain \f1\lang1033\fs26 . \endash  (Pseudo-)Anicius Manlius Severinus, De disciplina scolarium, Kapitel 2,3; Druck: Olga Weijers (Hrsg.), Pseudo-Bo\u232 \'e8ce. De disciplina scolarium, Leiden/ K\u246 \'f6ln 1976, S. 99 \endash  100; Henkel, \u220 \'dcbersetzungen, 1988, S. 224 \endash  225. \endash  107\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  leer.}

