\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 6\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \endash  13\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  (Pseudo-){\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Alexander Hispanus}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Melleus liquor physicae artis}}\plain \f1\lang1033\fs26 , Exzerpt (De radicibus et herbis). (6\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) ({\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 G)}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 alganum vel Galgana est siccum et calidum}}\plain \f1\i\lang1033\fs26  et est radix valde bona et utilis \plain \f1\lang1033\fs26 \u8230 \'85 (13\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Agrimonia est herba valde bona \plain \f1\lang1033\fs26 \u8230 \'85 \plain \f1\i\lang1033\fs26 Solsequium est herba alta \plain \f1\lang1033\fs26 \u8230 \'85 \plain \f1\i\lang1033\fs26 fuerit cum albugine ovi et parum\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Recipe\plain \f1\lang1033\fs26 : \plain \f1\i\lang1033\fs26 Accipe solsequium cum radice sua \plain \f1\lang1033\fs26 \u8230 \'85 \plain \f1\i\lang1033\fs26 de mane et vespere dicti pacienti ut supra dictum est\plain \f1\lang1033\fs26 . Unmittelbar anschlie\u223 \'dfend: Rubrik: \plain \f1\i\lang1033\fs26 Reseptum \plain \f1\lang1033\fs26 (!) \plain \f1\i\lang1033\fs26 de Terciana\plain \f1\lang1033\fs26 . Text: {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Recipe: Accipias santauriam et illam decoque cum aceto}}\plain \f1\i\lang1033\fs26  \plain \f1\lang1033\fs26 \u8230 \'85 \plain \f1\i\lang1033\fs26 tunc illam frigidam bibas\plain \f1\lang1033\fs26 . \endash  35 Kapitel (in der Reihenfolge der Hs.): Galganum, Zinciber, Muscatum, Gariofulus, Cimamonum, Ceduar, Piper, Allium, Cepa, Porrum, Sinape, Papaver, Enula campana, Raphanus maior, Raphanus minor, Rapula, Casaeus, Faba, Pisa, Canapum, Rosa, Fiola, Salvia, Ruta, Isopus, Petrosilium, Artimesia, Absinthium, Ruta de minor, Millefolium, Plantago, Pipilena (!), Betonia, Menta, Agrimonia, Solsequium; Druck: Sudhoff, Alexander Hispanus, 1936 (s. 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ), S. 308 \endash  312 und ders., Alexander Hispanus \u8230 \'85 Fortsetzung und Schlu\u223 \'df, in: ebenda 30 (1937), S. 1 \endash  5; Poul Hauberg (Hrsg.), Henrik Harpestr\u230 \'e6ng. Liber Herbarum, Kopenhagen 1936, S. 48 \endash  126, 135 \endash  153; vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Thorndike/ Kibre 1963 Sp. 575}}\plain \f1\lang1033\fs26 ; Bernhard Schnell (Hsrg.), Der deutsche \u8218 \'82Macer\rquote . Vulgatfassung. Mit einem Abdruck des lateinischen Macer floridus \u8218 \'82De viribus herbarum\rquote , T\u252 \'fcbingen 2003 (Texte und Textgeschichte, Bd. 50); S. 150 \endash  151; weitere Lit. s.o. 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 . \endash  13\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  leer. }

