\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 15\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26  \endash  15\plain \f1\super\lang1033\fs24 vc\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Armengaudus Blasii}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Tabula Antidotarii}}\plain \f1\lang1033\fs26 , Fragment. (15\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26 ) <Yera pigra> \u8230 \'85 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Videlicet contra passionem stomachi et splenis et capitis}}\plain \f1\i\lang1033\fs26  \plain \f1\lang1033\fs26 \u8230 \'85 (15\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Aurea Allexandria \plain \f1\lang1033\fs26 \u8230 \'85 (15\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Sulphur cymium \plain \f1\lang1033\fs26 \u8230 \'85 (15\plain \f1\super\lang1033\fs24 vc\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Sulphur est calide \plain \f1\lang1033\fs26 \u8230 \'85 \plain \f1\i\lang1033\fs26 si convenienter ministretur \plain \f1\lang1033\fs26 \u9553 \'a6. \endash  Ein Blatt, Fragment der Tabula Antidotarii, Anfang und Schlu\u223 \'df fehlen; Druck und vgl. Michael McVaugh/ Lola Ferre (Hrsg.), The Tabula Antidotarii of Armengaud Blaise and Its Hebrew Translation, Philadelphia 2000 (Transactions of the American Philosophical Society. Held at Philadelphia For Promoting Useful Knowledge, Bd. 90, Teil 6), S. 22 \endash  165, bes. S. 124 \endash  154 (Druck); vgl. ebenda S. 1 \endash  21; Lynn Thorndike, Little Known Medical Works And Authors in Basel Manuscripts, in: Annals of Medical History 107 (1940) [i.e. 3. Ser. 2,1 (1940)], S. 280 \endash  290, bes. S. 282 und 288; {\field{\*\fldinst HYPERLINK "hida:/