\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 19\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  24\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Serlo Wiltoniensis}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Regulae bene loquendi et scribendi metricae}}\plain \f1\lang1033\fs26  cum glossis. (19\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Unam semper amo, cuius non solvar ab hamo}}\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 dicitur arbor\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  acer\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  vir fortis et inprobus acer\plain \f1\lang1033\fs26  ... (24\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Que tua facta noces\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 fatorum consule voces\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Multi videre\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 que non potuere videre\plain \f1\lang1033\fs26 . Nachtrag: \plain \f1\i\lang1033\fs26 Presens pone venit non preteritum breve venit\plain \f1\lang1033\fs26  (?). \plain \f1\i\lang1033\fs26 Sic presentis\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 icit\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 sic preteriti sanit\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 icit \plain \f1\lang1033\fs26 (?). \plain \f1\i\lang1033\fs26 Si locus est mete venit\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Explicit ergo valete\plain \f1\lang1033\fs26 . \endash  Rubrik auf dem Kopfsteg verbla\u223 \'dft, auch unter UV-Licht nicht mehr lesbar; von einer in etwa zeitgleichen kursiven Glossenhand interlinear und marginal, z.T. franz\u246 \'f6sische Wortglossen sowie marginal auch weitere Verse nachgetragen; von \u214 \'d6berg, Serlon de Wilton, 1965 (s. Lit.), S. 42 \endash  51 der Textfamilie Y zugeordnet (Sigle Da); zum Textbestand vgl. ebenda, S. 166 \endash  169; Druck: \u214 \'d6berg, Serlon de Wilton, 1965 (s. Lit.), S. 79 \endash  162; M. Haur\u233 \'e9au, Notice sur les m\u233 \'e9langes po\u233 \'e9tiques d\rquote Hildebert de Lavardin, in: Notices et extraits des manuscrits de la Biblioth\u232 \'e8que Nationale et autres biblioth\u232 \'e8ques 28 (1878), S. 289 \endash  448, bes. S. 428 \endash  435, Nr. XXV; {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 19623}}\plain \f1\lang1033\fs26  (mit dieser Hs.); {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Proverbia, II/5, Nr. 32133}}\plain \f1\lang1033\fs26 ; Bursill-Hall, Census, 1981, Nr. 81.101.7, 149.38.8. }

