lain \f1\lang1033\fs26\chcbpat17 GW 11697}}\plain \f1\lang1033\fs26 , Parva Practica, Tractatus 4, 167\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs26 ; vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Thorndike/ Kibre 1963, Sp. 317}}\plain \f1\lang1033\fs26  und {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 284}}\plain \f1\lang1033\fs26 ; Parallel\u252 \'fcberlieferung: {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Vatikan, BAV, Cod. Pal. lat. 1084}}\plain \f1\lang1033\fs26 , 79\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26  \endash  81\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 ebenda, Cod. Pal. lat. 1085}}\plain \f1\lang1033\fs26 , 37\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs26  \endash  39\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs26 ; Text auch in {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 501}}\plain \f1\lang1033\fs26 , CXI\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs26  (Kapitel 4 \endash  7). }

