\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 76\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26  \endash  76\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 De medicinis laxativis}}\plain \f1\lang1033\fs26 . (76\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Acuere medicinas laxativas licet non videatur esse}}\plain \f1\i\lang1033\fs26  de arte quia non aliquo auctore precipitur\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Iuxta artem tamen esse iii\plain \f1\i\super\lang1033\fs24 a\plain \f1\lang1033\fs26  ... (76\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Sciendum autem quoniam omnia ista acummina et eorum doses diversificantur scilicet diversificantem regionum\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  etatum\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 sexuum\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  habitudinem\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 et aliorum particularium hors\plain \f1\lang1033\fs26  (?) \plain \f1\i\lang1033\fs26 eth\plain \f1\lang1033\fs26  (?). \endash  Enthalten sind u.a. Angaben zu Hermodactilus, Scamonea, Esula, Turbith, Euphorbium, Pollipodium, Agaritus, Aloe, Colloquintus, (H)elleborus. Anschlie\u223 \'dfend nachgetragenes Rezept f\u252 \'fcr ein Kr\u228 \'e4uter\u246 \'f6l. >\plain \f1\i\lang1033\fs26 Oleum herbarum\plain \f1\lang1033\fs26 <. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Nota, quod hoc modo fit oleum de herbis}}\plain \f1\lang1033\fs26 : \plain \f1\i\lang1033\fs26 Bulleantur herbe in aquis\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 item illud quid distillabit ab olla superiori perforata in ollam inferiorem dicetur olveri de calibus lignis\plain \f1\lang1033\fs26 . \endash  76\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs26  leer. }

