\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 77\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26  \endash  105\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Bartholomaeus Salernitanus}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Practica}}\plain \f1\lang1033\fs26 . (77\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Incipit Practica magistri Bartholomei\plain \f1\lang1033\fs26 <. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Practica dividitur in duas partes: in scientiam conservativam sanitatis}}\plain \f1\i\lang1033\fs26  et curativam egritudinis\plain \f1\lang1033\fs26  ... (104\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 De sciatica\plain \f1\lang1033\fs26 <. \plain \f1\i\lang1033\fs26 Restat nunc tractare de sciatica passione et podagra et primum de sciatica\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  que nomen habet a scia\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 postea purgetur tibi apozimate de cassia folii et tamarindis\plain \f1\lang1033\fs26  (?) \plain \f1\i\lang1033\fs26 etc\plain \f1\lang1033\fs26 . >\plain \f1\i\lang1033\fs26 De podagra\plain \f1\lang1033\fs26 <. \plain \f1\i\lang1033\fs26 Post predicta sequitur de podagra dicitur autem podagra a pede tiraga a manu\plain \f1\lang1033\fs26  ... (105\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26 ) >\u8218 \'82\plain \f1\i\lang1033\fs26 Ego infectos\plain \f1\lang1033\fs26  (?) \plain \f1\i\lang1033\fs26 liberavi cum isto antidoto\rquote \plain \f1\lang1033\fs26 <. \plain \f1\i\lang1033\fs26 Recipe huiusmodi dramma ix capparis\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 dramma iiii diagridii\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 dramma ii piperis nigri et libro \plain \f1\lang1033\fs26 (?)\plain \f1\i\lang1033\fs26  zinziber\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 cinamoni\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 aleanne beni\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  angelica\plain \f1\lang1033\fs26  (?) \plain \f1\i\lang1033\fs26 dramma ii\plain \f1\lang1033\fs26 . >\plain \f1\i\lang1033\fs26 Enim quod sufficit\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Explicit\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Grates reddo deo finito Bartholomeo\plain \f1\lang1033\fs26 <. \endash  Schlu\u223 \'df im Vergleich zum Druck um ein Kapitel erweitert; Druck: De Renzi, Collectio Salernitana, 1852 \endash  1859, Bd. 4 (1856), S. 321 \endash  405;  vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Thorndike/ Kibre 1963, Sp. 1080}}\plain \f1\lang1033\fs26 ; zum Verfasser VL(2), Bd. 1 (1978), Sp. 623 \endash  625 (Gundolf Keil); C.A.L.M.A., Bd. 2 (2008), S. 56 \endash  59 (Marco Toste). }

