\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 105\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Diaeta}}\plain \f1\lang1033\fs26  contra calculum. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Calculorum dieta. Contra calculum}}\plain \f1\lang1033\fs26 . >\plain \f1\i\lang1033\fs26 Calculum\plain \f1\lang1033\fs26 <. \plain \f1\i\lang1033\fs26 Panis cuius \plain \f1\lang1033\fs26 (?) \plain \f1\i\lang1033\fs26 sit mundus a furfure\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 cum aqua decoctionis circum nigri\plain \f1\lang1033\fs26 . Unmittelbar anschlie\u223 \'dfend auf dem Fu\u223 \'dfsteg zwei nachgetragene Notizen: 1. {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Rezept}}\plain \f1\lang1033\fs26  zur Augenheilkunde. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Item ad oculos multum lesus et excunctos summatur}}\plain \f1\i\lang1033\fs26  aqua feniculi vel succus eiusdem\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 super oculos donec\plain \f1\lang1033\fs26 . 2. (105\plain \f1\super\lang1033\fs24 rab\plain \f1\lang1033\fs26 ) Deutsch-lateinische Aufz\u228 \'e4hlung von Arzneien gegen Fieber. {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Contra febris herbam dictam Duvelsbeit}}\plain \f1\i\lang1033\fs26  est nigris\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 item Schellen herba\plain \f1\lang1033\fs26  (?) \plain \f1\i\lang1033\fs26 Spurkele Holc\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 den gelen Schellen\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 item den grenen Schellen herba\plain \f1\lang1033\fs26  (?) \plain \f1\i\lang1033\fs26 Holencern\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 item Werrelen herba Helen Wassende\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 et ambulet\plain \f1\lang1033\fs26 . }

