\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 Vorderer Umschlag innen 1. (\plain \f1\super\lang1033\fs24 ab\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Versus}}\plain \f1\lang1033\fs26  de ebrietate. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Nunc attendatis, quis sit status ebrietatis}}\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 sic Bachi turba laborat\plain \f1\lang1033\fs26 . \endash  Druck: Fr. Koehler, Ehstl\u228 \'e4ndische Klosterlek\-t\u252 \'fcre. Ein Beitrag zur Kenntniss der Pflege des geistigen Lebens in Ehstland im Mittel\-alter, Reval 1892, S. 112, Nr. 35; vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 12431}}\plain \f1\lang1033\fs26 ; 2. (\plain \f1\super\lang1033\fs24 a\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Alanus ab Insulis}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Anticlaudianus}}\plain \f1\lang1033\fs26 , Distinctio quinto, Capitulum 9. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Hic superos cives proprio precellit honore}}\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 egrotat medicus\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 ut sanet morbidus egrum\plain \f1\lang1033\fs26 . \endash  Druck: PL, Bd. 210, Sp. 538 \endash  540; Thomas Wright, The Anglo-Latin Satirical Poets and Epigrammatists of The Twelfth Century, zwei B\u228 \'e4nde, London 1872, Bd. 2, S. 362 \endash  364; vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 8123}}\plain \f1\lang1033\fs26 .}

