\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 23\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \endash  24\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  Kurze {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Rezepte}}\plain \f1\lang1033\fs26  und Tipps zur Pferdemedizin. (23\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Sciendum, quod ista, que sequntur habent impingnare equos}}\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 Furfur modicum infusum cum aqua cepida\plain \f1\lang1033\fs26  ... (24\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 De etate pulli equi\plain \f1\lang1033\fs26 <. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Etatis conderacio talis est}}\plain \f1\lang1033\fs26  ... >\plain \f1\i\lang1033\fs26 De equo restivo\plain \f1\lang1033\fs26 <. {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Si equus restivus fuerit sic enim curabis}}\plain \f1\i\lang1033\fs26  \plain \f1\lang1033\fs26 ... (24\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 De interferitura\plain \f1\lang1033\fs26 <. {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Interferitura facit equum clandicare}}\plain \f1\lang1033\fs26  ... >\plain \f1\i\lang1033\fs26 Item de vermibus\plain \f1\lang1033\fs26 <. \plain \f1\i\lang1033\fs26 De vermibus. {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Si vermes carnem hominis aut pecoris commedant}}\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 Ad aquis currentes si oculis bibe rutam\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 et succum verbene\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 dolentes extrahit dolorem et est maxi innannitatem\plain \f1\lang1033\fs26  (?). \plain \f1\i\lang1033\fs26 Avicenna ex partis\plain \f1\lang1033\fs26 . }

