\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 Hinterer Umschlag innen: {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Gesundheitsregeln}}\plain \f1\lang1033\fs26 . 1. De coloribus sanguinis. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Si sanguis spumosus vicium peccatoris est}}\plain \f1\i\lang1033\fs26  ... si sanguis superius et aqua inferius ydropasim signavit, cum sit parum aque candide signum optime sanitatis\plain \f1\lang1033\fs26 . 2. {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Sprichw\u246 \'f6rter}}\plain \f1\lang1033\fs26 . a. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Sal primi pone, primi sal inde repone}}\plain \f1\lang1033\fs26 . \endash  Vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Proverbia, II/4, Nr. 27434a}}\plain \f1\lang1033\fs26 ; b. {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Salque synape piper de mensu collige primo}}\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 post escam paves elemosina potus in ymo\plain \f1\lang1033\fs26 . \endash  Vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Proverbia, II/4, Nr. 27437}}\plain \f1\lang1033\fs26 ; c. {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Ut vites penam, cum potibus incipe cenam}}\plain \f1\lang1033\fs26 . \endash  Vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Proverbia, II/5, Nr. 32634}}\plain \f1\lang1033\fs26 ; d. {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 De magna cena s