\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 47\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  56\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 De arte dictandi}}\plain \f1\lang1033\fs26  ad Iuvenes. (47\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) ({\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 A)}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 d iuvenes in arte dictandi minus peritis quidam facilis}}\plain \f1\i\lang1033\fs26  \plain \f1\lang1033\fs26 ... \plain \f1\i\lang1033\fs26 Notandum primo\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 quod antiquitus modernus scribende erit talis\plain \f1\lang1033\fs26 : \plain \f1\i\lang1033\fs26 Quod in dorso litere non scribebant plusquam nomen et locum habitacionis\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 illius\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  cui litere scribatur\plain \f1\lang1033\fs26  ... (56\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Et tunc in narracione debet uti eosdem tribus ceteris sic\plain \f1\lang1033\fs26 : \plain \f1\i\lang1033\fs26 Vestram noviter discretio scienciarum flosculis\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 insigniti per presentes\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 vel\plain \f1\lang1033\fs26 : \plain \f1\i\lang1033\fs26 presentibus cupio paceficit\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Et sic est finis huius opusculi\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 communicatis\plain \f1\lang1033\fs26  (?) (Knaus / Polak: \plain \f1\i\lang1033\fs26 communicationis\plain \f1\lang1033\fs26 ). \endash  Die vom Text zitierten Beispiele enthalten h\u228 \'e4ufig Ortsbezeichungen aus dem niederl\u228 \'e4ndisch-niederrheinischen Raum, z.B. (77\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 officis curie Leodiensis plebanus clericus eadem\plain \f1\lang1033\fs26 ; (52\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 archiepiscopi Colonensi;\plain \f1\lang1033\fs26  (54\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 comes Hollandie\plain \f1\lang1033\fs26 ; \plain \f1\i\lang1033\fs26 curie Traiectensis\plain \f1\lang1033\fs26 ; vgl. Polak, Letter Treatises, 1993 \endash  2015, Bd. 2, S. 368.}

