\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 66\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Sprichw\u246 \'f6rter}}\plain \f1\lang1033\fs26  und {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Verse}}\plain \f1\lang1033\fs26 . \endash  Die ersten vier Verse (107 \endash  110, 111) aus Kapitel 17 des Graecismus von {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Eberhardus Bethuniensis}}\plain \f1\lang1033\fs26 ; Druck: Wrobel, Grecismus, 1887, S. 174; au\u223 \'dferdem enthalten (in der Reihenfolge der Hs.): {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 10896}}\plain \f1\lang1033\fs26  (Anfangsverse des {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Compendium theologiae veritatis}}\plain \f1\lang1033\fs26  des {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hugo Argentinensis}}\plain \f1\lang1033\fs26 , als solche auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 492}}\plain \f1\lang1033\fs26 , 1\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 539}}\plain \f1\lang1033\fs26 , 1\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 796}}\plain \f1\lang1033\fs26 , 2\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 1015}}\plain \f1\lang1033\fs26 , 127\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26 ; vgl. DA LuHB Kat. Bd. 5,1, S. 59, 68, 118, 131); {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Proverbia, II/4, Nr. 23426}}\plain \f1\lang1033\fs26 ; Vers 181 aus dem {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Facetus}}\plain \f1\lang1033\fs26  \u8218 \'82Cum nihil utilius\ldblquote ; Druck: Schr\u246 \'f6der, Facetus, 1911, S. 27; {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Proverbia II/4, Nr. 25249}}\plain \f1\lang1033\fs26 ; \u228 \'e4hnlich {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 II/3, Nr. 17252; II/1, Nr. 2492}}\plain \f1\lang1033\fs26 . }

