\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 67\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Notizen}}\plain \f1\lang1033\fs26  zur Grammatik; anschlie\u223 \'dfend sechs {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 R\u228 \'e4tsel}}\plain \f1\lang1033\fs26  mit L\u246 \'f6sungen. 1. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Est unum vere, quod nemo gliscitis habere}}\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 quod si contigerum perdere noluerum.\plain \f1\lang1033\fs26  \endash  >\plain \f1\i\lang1033\fs26 Senectus\plain \f1\lang1033\fs26 <; 2. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Montes sunt celsi, de quibus domitur vel se}}\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 uniunt\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 mellificant\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 qui possunt solvere solvant.\plain \f1\lang1033\fs26  \endash  >\plain \f1\i\lang1033\fs26 Alpes\plain \f1\lang1033\fs26 <; 3. {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 In silvis perge venacum bis cave quino}}\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 quod capio\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 perdo\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 quod sugit\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 hoc habeo.\plain \f1\lang1033\fs26  \endash  >\plain \f1\i\lang1033\fs26 Pediculus\plain \f1\lang1033\fs26 <; 4. {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Ponitur in mensa res, qui regine densa}}\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 legumine tolle simul remanebit ibi\plain \f1\lang1033\fs26 . \endash  >\plain \f1\i\lang1033\fs26 Cepe\plain \f1\lang1033\fs26 <; 5. {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Floribus et lignis vidi materiale certum}}\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 quod ligno carnit et sine flore fuit\plain \f1\lang1033\fs26 . \endash  >\plain \f1\i\lang1033\fs26 Peripsoma\plain \f1\lang1033\fs26 <; 6. {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Est arbor, ramos, quedam retinuens duodenos}}\plain \f1\i\lang1033\fs26  ... et volucris quique nomen retinet speciale\plain \f1\lang1033\fs26 . \endash  >\plain \f1\i\lang1033\fs26 Anuus\plain \f1\lang1033\fs26 <. \endash  Nr. 6 in sehr \u228 \'e4hnlicher Form bei Werner, Sprichw\u246 \'f6rter, \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs26 1966, S. 46, Nr. 27; {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 5596}}\plain \f1\lang1033\fs26 ; die gleichen Verse als Glosse zu Alexander de Villa Dei, Doctrinale, Pars 1 auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 2642}}\plain \f1\lang1033\fs26 , 91\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ; und in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 2225}}\plain \f1\lang1033\fs26 , 67\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ; danach Sprichwort vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Proverbia, II/4, Nr. 28545}}\plain \f1\lang1033\fs26 . }

