\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 67\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \endash  69\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Sprichwortsammlung}}\plain \f1\lang1033\fs26 . (67\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Quis scit ad hunc an nos plures complebimus annos}}\plain \f1\lang1033\fs26  ... (69\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Sunt tria\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 que nullus sapientium debet amare\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 multum iacant\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 lapidem saltantque -nare\plain \f1\lang1033\fs26 . \u9553 \'a6 Nachtrag: \plain \f1\i\lang1033\fs26 Non in velle canum\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 quod equi moriuntur in anno\plain \f1\lang1033\fs26 . \endash  Umfangreiche, in der Regel ungeordnete Sammlung von Sprichw\u246 \'f6rtern; zwischen 69 und 70 fehlt ein Bl., m\u246 \'f6glicherweise mit Textverlust; enthalten sind in der Reihenfolge der Handschrift {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 16109}}\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Proverbia, II/4, Nr. 25440; II/3, Nr. 21311a; II/5, Nr. 33116; II/3, Nr. 21520; II/4, Nr. 28608; II/5, Nr. 34174; II/4, Nr. 28380; II/1, Nr. 2406; II/3, Nr. 22349; II/2, Nr. 7385; II/5, Nr. 29981; II/5, Nr. 31591; II/4, Nr. 28603; II/4, Nr. 24407; II/4, Nr. 25526; II/3, Nr. 19457; II/3, Nr. 18813; II/4, Nr. 23688a; II/3, Nr. 21691; II/1, Nr. 4173; II/5, Nr. 31577; II/1, Nr. 3660; II/3, Nr. 19199; II/3, Nr. 18536; II/4, Nr. 27367; II/2, Nr. 11478; II/3, Nr. 20064; II/4, Nr. 26480; II/4, Nr. 28372; II/1, Nr. 4138; II/5, Nr. 33466; II/4, Nr. 29427; II/4, Nr. 29152; II/1, Nr. 5213; II/1, Nr. 6725; II/2, Nr. 10142; II/2, Nr. 9746; II/5, Nr. 32279; II/4, Nr. 27350; II/5, Nr. 32813; II/4, Nr. 25230; II/9, Nr. 42869a; II/5, Nr. 30848a; II/3, Nr. 19596; II/3, Nr. 22009}}\plain \f1\lang1033\fs26 ; Nachtrag (69\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) vgl. Werner, Sprichw\u246 \'f6rter, \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs26 1966, S. 102, Nr. 168. }

