\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 70\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  Zw\u246 \'f6lf {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Verse}}\plain \f1\lang1033\fs26 , \u252 \'fcberwiegend theologischer Thematik. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 De Jesu fari tibi dulce sit et meditari}}\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 Jesus in aure melos\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 iubilus cordis\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 mel in ore \plain \f1\lang1033\fs26 ... \plain \f1\i\lang1033\fs26 Plus sera milla sera fit era que possidet era\plain \f1\lang1033\fs26 . \endash  Ab Vers 7 mit interlinearen Kommentaren; enthalten sind u.a. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Proverbia, II/1, Nr. 397}}\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 388}}\plain \f1\lang1033\fs26  (\u228 \'e4hnlich); {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Nr. 14264}}\plain \f1\lang1033\fs26 ; zu Vers 9: vgl. Tony Hunt, Teaching and Learning Latin in 13th-Century England, 3 B\u228 \'e4nde, Cambridge 1991, Bd. 1, S. 306. }

