\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Devise}}\plain \f1\lang1033\fs26  (s.o.), sonst leer; 1\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \endash  4\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  bis auf Einrichtung des Schriftspiegels (s.o.) leer. }

