\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 48\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  51\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Petrus Alfonsi}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Disciplina clericalis}}\plain \f1\lang1033\fs26 , Exzerpte. (48\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 De facecia manducandi\plain \f1\lang1033\fs26 <. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Arabs docuit filium suum dicens}}\plain \f1\lang1033\fs26\chcbpat17 : {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Cum ablueris manus}}\plain \f1\i\lang1033\fs26  ut comedas nichil aliud tangas \plain \f1\lang1033\fs26 ... (50\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 De servo pigro et guloso\plain \f1\lang1033\fs26 <. \plain \f1\i\lang1033\fs26 Mercator quidam dives habebat servum gulosum\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 pigrum, stultum\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 garrulum et nugigerulum\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 cui nomine erat Maymundus\plain \f1\lang1033\fs26  ... (51\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Tunc dominus valde conturbatus ad vicinos suos venit orans eos ut reciperetur in alicus domo et hospitaretur\plain \f1\lang1033\fs26  >\plain \f1\i\lang1033\fs26 etc factum est\plain \f1\lang1033\fs26 <. \endash  Enthalten sind in der Reihenfolge der Handschrift Exzerpte der Exempla 26, (De modo commedendi), 29 (De duobus burgensibus et rustico), 20 (De regii incisoris discipulo Nedui nomine), 27 (De Maimundo servo) der Ausgabe Hilka/ S\u246 \'f6derhjelm, 1911 (s. 40\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ), S. 40, Zeile 16 \endash  36; S. 30, Zeile 8 \endash  15; S. 45 \endash  47, S. 30, Zeile 26 \endash  31, Zeile 35; S. 41, Zeile 22 \endash  S. 42, Zeile 28.}

