\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 54\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  62\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Petrus Alfonsi}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Disciplina clericalis}}\plain \f1\lang1033\fs26 , Exzerpte. (54\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Gravatum cito se debere redimere\plain \f1\lang1033\fs26  (?)<. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Si gravatus fueris aliquo modo et possis facile liberari}}\plain \f1\lang1033\fs26  ... (60\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Aliud huic simile describam calliditatis eximie salutare exemplum\plain \f1\lang1033\fs26 : \plain \f1\i\lang1033\fs26 Dives quidam ad civitatem Parisius mercandi gratia commeatum faciens detulit secum sacculum mille argenti\plain \f1\lang1033\fs26  (61\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 talenta continentem\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 nec non et aureum serpentem iacinctinos oculos habentem\plain \f1\lang1033\fs26  ... (62\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 sicque ingenio philosophi pauper de angustia liberatus letus abivit\plain \f1\lang1033\fs26 . \endash  Enthalten sind in der Reihenfolge der Handschrift Exzerpte der Kapitel 6 (De versificatore et gibboso), 7 (De clerico domum potatorum intrante), 12 (De rege et fabulatore suo), 15 (De decem coffris), 16 (De decem tonellis olei), 17 (De aureo serpente) der Ausgabe Hilke/ S\u246 \'f6derhjelm 1911 (s. 40\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ), S. 12, Zeile 21 \endash  S. 13, Zeile 31; S. 17 \endash  18, S. 22 \endash  27; die Kapitelanf\u228 \'e4nge h\u228 \'e4ufig abweichend.}

