\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 62\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \endash  63\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Valerius Maximus}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Facta et dicta memorabilia}}\plain \f1\lang1033\fs26 , Exzerpt aus Buch 7, Kapitel 3. (62\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Demostenes orator egregius, ut ait Valerius Maximus libro septimo}}\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 ancille sue tali modo astutum\plain \f1\lang1033\fs26  ... (63\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 ancilla liberata est ac liberatoris immensas graciarum actiones rependit\plain \f1\lang1033\fs26 . \endash  Absatz 5 von Kapitel 3; Schlu\u223 \'df im Vergleich zum Druck abweichend; Druck: Kempf, Factorum et Dictorum Memorabilium, 1854 (s. 43\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ), S. 561, Zeile 3 \endash  14; Briscoe, Facta et Dicta Memorabilia, 1998 (s. 43\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ), Bd. 2, S. 462, Zeile 195 \endash  S. 463, Zeile 208. }

