\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 67\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  71\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Gesta Romanorum}}\plain \f1\lang1033\fs26 , Exemplum \u8218 \'82De Ingrato et Guidone\lquote . (67\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 De ingratitudine\plain \f1\lang1033\fs26 <. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Dum quidam prepotens rex vice quadam equicaret}}\plain \f1\i\lang1033\fs26  per territorios regni obvium habuit quendam pauperem in amictu deformi scilicet vultu gracioso\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 quem rex interrogabat unde et quis esset et quo censeretur nomine\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Ille respondens ait\plain \f1\lang1033\fs26 : \plain \f1\i\lang1033\fs26 Domine mi in regno vestre celsitudinis natus sum\plain \f1\lang1033\fs26  ... (70\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Dominus Guido autem suscepit officium eius\plain \f1\lang1033\fs26  (71\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 ac substantiam et in pace vitam suam terminavit\plain \f1\lang1033\fs26 . \endash  Druck: Wilhelm Dick (Hrsg.), Die Gesta Romanorum nach der Innsbrucker Handschrift vom Jahre 1432 und vier M\u252 \'fcnchener Handschriften herausgegeben, Erlangen/ Leipzig 1890 (Erlanger Beitr\u228 \'e4ge zur Englischen Philologie Bd. 7), Kapitel 145, S. 86 \endash  92; vgl. Oesterley, Gesta Romanorum, 1872, S. 119, Nr. 59; {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Tubach, Index exemplorum, 1969 (s. 63}}{\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\super\lang1033\fs36\chcbpat17 r}}{\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 ), S. 26, Nr. 256}}\plain \f1\lang1033\fs26 . }

