\pard\fi0\li0\qj\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs22 Walther, Kenntni\u223 \'df, 1867, S. 66\~\~\u183 \'b7\~\~Roth, Literatur, 1891, S. 20\~\~\u183 \'b7\~\~Knaus, Fischer von Waldheim, 1964, S. 258 \endash  259 und S. 270 \endash  271\~\~\u183 \'b7\~\~Gerhardt Powitz, Das \u187 \'bbCatholicon\u171 \'ab \endash  Umrisse der handschriftlichen \u220 \'dcberlieferung, in: Michael Borgolte/ Herrad Spilling (Hrsg.), Litterae medii aevi. Festschrift f\u252 \'fcr Johanne Autenrieth zu ihrem 65. Geburtstag, Sigmaringen 1988, S. 209 \endash  223, bes. 221 \endash  223.}

