\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 1\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26  \endash  456\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Johannes Ianuensis}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Catholicon}}\plain \f1\lang1033\fs26 . (1\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Prosodia quedam pars gramatice nuncupatur}}\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Pars si quidem gramatice sunt quatuor\plain \f1\lang1033\fs26  ... (1\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Prima ergo pars istius libri, ut dixi, est de orthogravia}}\plain \f1\lang1033\fs26  ... (456\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Zozimus\plain \f1\lang1033\fs26 , -\plain \f1\i\lang1033\fs26 ma\plain \f1\lang1033\fs26 , -\plain \f1\i\lang1033\fs26 mum\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 id est vivax vel vividus\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Unmensas\plain \f1\lang1033\fs26  (!) \plain \f1\i\lang1033\fs26 omnipotenti deo\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 patri et filio et spiritu sancto graciarum referimus acciones\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 qui nostrum Catholicon ex multis et diversis doctorum texturis elaboratum atque contextum licet per multa annorum curricula in millesimo tamen ducentesimo octogesimo sexto anno domini nonis Marcii ad finem usque perduxit\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 ubi regnat ex amussim dominus noster Jesus Christus\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 dei filius benedictus\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 in cuius nomine flectitur omne genu celestium terrestrium et infernorum\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 cui est gloria et honor magnitudo et magnificencia virtus et potestas regnum et imperium in secula seculorum\plain \f1\lang1033\fs26 . >\plain \f1\i\lang1033\fs26 Amen\plain \f1\lang1033\fs26 <. \endash Druck: {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 GW 03182 \endash  03205}}\plain \f1\lang1033\fs26 ; vgl. Powitz, Catholicon \endash  Sicht, 1988, S. 125 \endash  137, bes. S. 132; ders., Catholicon \endash  Esquisse, 1996, S. 299 \endash  336, bes. S. 324, Zusammenstellung der handschriftlichen \u220 \'dcberlieferung auf S. 322 \endash  336; au\u223 \'dferdem Marigo, Derivationes, 1936, S. 31 \endash  40; Grubm\u252 \'fcller, Vocabularius Ex quo, 1967, S. 26, Anm. 3; Text in Ausz\u252 \'fcgen auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 317}}\plain \f1\lang1033\fs26 , 76\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26 ; vgl. DA ULB Kat. 5,2 in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 739}}\plain \f1\lang1033\fs26 , 152\plain \f1\super\lang1033\fs24 vab\plain \f1\lang1033\fs26 , in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 1988}}\plain \f1\lang1033\fs26 , 144\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 . \endash  I\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \endash  II\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 , 456\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs26  \endash  458\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  leer. }

