\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 63\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26  \endash  78\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs26  [62\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26  \endash  78\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs26 ] De Medicina. (63\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26 ) ({\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 M)}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 edicina est scientia qua humani corporis dispositiones cognoscuntur}}\plain \f1\i\lang1033\fs26  ex parte\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  qua sanatur\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 Item non est estimandum\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  cum dicimus\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  quod pars medicine alia theorica alia practica\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  quod velimus dicere\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  quod una dictionum\plain \f1\lang1033\fs26  (?) \plain \f1\i\lang1033\fs26 sit scire\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  altera operari\plain \f1\lang1033\fs26  ... (63\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Item pulmo, epar, splen et renes sua substancia non sentiunt\plain \f1\lang1033\fs26  ... (64\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Item dicimus\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 quod membrorum alia generantur ex spermate\plain \f1\lang1033\fs26  ... (78\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Scias\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 quod nonus est dies fortis prelatus\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 Scias\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 quod\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 apostemata parva fuerit singula pura\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 scilicet plura eorum fuerunt comportari\plain \f1\lang1033\fs26 . \endash  Wahrscheinlich Exzerpte aus {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Avicenna}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Canon Medicinae}}\plain \f1\lang1033\fs26  (Translatio {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Gerardi Cremonensis}}\plain \f1\lang1033\fs26 ); das Initium und Teile des Textes weisen gro\u223 \'dfe \u196 \'c4hnlichkeit auf mit {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 BAV, Cod. Pal. lat. 1105}}\plain \f1\lang1033\fs26 , 138\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  153\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  Compendium tractans generalia speculabilia in Medicina; Text stimmt jedoch nicht v\u246 \'f6llig \u252 \'fcberein; vgl. Thorndike/ Kibre 1963, Sp. 858; Xhayet, M\u233 \'e9decine, 2010, S. 55. }

