\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 125\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26  \endash  152\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Johannes de Garlandia}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Tractatus}}\plain \f1\lang1033\fs26  de Aequivocis (Liber de terminis defectivis) cum commento. (125\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs26 ) Text beginnt: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 A nomen signat: trahitur, profertur}}\plain \f1\lang1033\fs26  ... (152\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26 ) Text endet: \plain \f1\i\lang1033\fs26 Zelo cupit nimium\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 sic invidet ac commitatur\plain \f1\lang1033\fs26 . >\plain \f1\i\lang1033\fs26 Expliciunt Equivoca a Magistro Matheo Vindocinensi composita\plain \f1\lang1033\fs26 <. (125\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26 ) Kommentar beginnt: {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Quoniam scire distinguere sophistarum ampullas exprimit}}\plain \f1\lang1033\fs26  ... (152\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs26 ) Kommentar endet: \plain \f1\i\lang1033\fs26 Noli emulari in malignantibus neque zelaveris facientes iniquitatem\plain \f1\lang1033\fs26  (Ps 36,1). \plain \f1\i\lang1033\fs26 Id est non in uteris\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Unde Christus\plain \f1\lang1033\fs26 . \endash  Druck: {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 GW M1363710, M1364410, M13638 \endash  M13657}}\plain \f1\lang1033\fs26 ; vgl. Roth, Mittheilungen, 1888, S. 595; Roth, Literatur, 1891, S. 20 \endash  21; Werner, Beitr\u228 \'e4ge, \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs26 1905, S. 185 \endash  186; Manitius, Geschichte, 1931, Bd. 3, S. 746 \endash  747; {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 54}}\plain \f1\lang1033\fs26 ; Kristeller, Iter, Bd. 3 (1983), S. 513; Bd. 6 (1992), S. 505; Bursill-Hall, Johannes de Garlandia, 1976, S. 166 \endash  167, Nr. 11b; Munari, Handschriften, 1995, S. 185 \endash  196, bes. S. 188; Bursill-Hall, Census, 1981, S. 57 \endash  58; zu 141\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26  \u8218 \'82Lentus\lquote  vgl. Friedrich Osann (Hrsg.), Vitalis Blesensis, Aphitryon et Aulularia Eclogae, Darmstadt 1836, S. VIII; Text auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 2225}}\plain \f1\lang1033\fs26 , 17\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 . }

