\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 152\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs26  \endash  152\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Johannes Ianuensis}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Catholicon}}\plain \f1\lang1033\fs26 , Fragment. (152\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs26 ) ({\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 A)}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 lma interpretatur virgo abscondita}}\plain \f1\lang1033\fs26  ... (152\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs26 ) (A)\plain \f1\i\lang1033\fs26 bdo\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 -dis\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 -didi\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 -itum id est abscondere removere ex ab et do\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 das componitur\plain \f1\lang1033\fs26 . (A)\plain \f1\i\lang1033\fs26 bdomen Grece pinguendo carnis secundum Papiam\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Ugucio vero dicit abdomen\plain \f1\lang1033\fs26  \u9553 \'a6<Grece pinguedo porci ... >. \endash  Text endet unvermittelt; Druck: {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 GW 03182 \endash  03205}}\plain \f1\lang1033\fs26 ; vgl. Powitz, Catholicon \endash  Sicht, 1988, S. 125 \endash  137; ders., Catholicon \endash  Esquisse, 1996, S. 299 \endash  336, Zusammenstellung der handschriftlichen \u220 \'dcberlieferung auf S. 322 \endash  336; au\u223 \'dferdem Marigo, Derivationes, 1936, S. 31 \endash  40; Grubm\u252 \'fcller, Vocabularius Ex quo, 1967, S. 26, Anm. 3; W