\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 153\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26  \endash  165\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f2\fs26\chcbpat17 Ab\u363 \'fb-Ma\u703 ?\u353 \'f0ar \u486 ?a\u703 ?far Ibn-Mu\u7717 ?ammad}}\plain \f2\fs26  (Albumasar), {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f2\fs26\chcbpat17 Flores astrologiae}}\plain \f2\fs26  (Translatio {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f2\fs26\chcbpat17 Johannis Hispalensis}}\plain \f2\fs26 ). (153\plain \f2\super\fs24 ra\plain \f2\fs26 ) \plain \f2\i\fs26 Hic est liber\plain \f2\fs26 , \plain \f2\i\fs26 quem collegit Albusmusar De Floribus eorum\plain \f2\fs26 , \plain \f2\i\fs26 que signat res superiores\plain \f2\fs26  ... {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f2\i\fs26\chcbpat17 Dixit Albumasar: Oportet te primum scire}}\plain \f2\fs26  ... (165\plain \f2\super\fs24 vb\plain \f2\fs26 ) \plain \f2\i\fs26 exposui tibi\plain \f2\fs26 ,\plain \f2\i\fs26  si deus voluerit et ipse est auxiliator\plain \f2\fs26 . \plain \f2\i\fs26 Finit liber Florum Albumasar sub laude dei et eius adiutorio\plain \f2\fs26 , \plain \f2\i\fs26 quem secuntur Liber Experimentorum eiusdem Albumasar\plain \f2\fs26 , \plain \f2\i\fs26 Tractatus tercius positio in revolutione annorum mundi\plain \f2\fs26 . \endash  Druck: {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f2\fs26\chcbpat17 GW 00837 \endash  00840}}\plain \f2\fs26 ; vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f2\fs26\chcbpat17 Thorndike/ Kibre 1963, Sp. 447 und Sp. 1013}}\plain \f2\fs26 ; Francis J. Carmody, Arabic Astronomical and Astrological Sciences in Latin Translation. A Critical Bibliography, Berkeley/ Los Angeles 1956, S. 92 \endash  94, Nr. 13,3. }

