\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 246\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26  \endash  252\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26  [243\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26  \endash  249\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26 ] {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Quadrans vetus}}\plain \f1\lang1033\fs26 . (246\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Geometrie due sunt partes: theorica et practica}}\plain \f1\lang1033\fs26  <...>\u9553 \'a6 \plain \f1\i\lang1033\fs26 ca est\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 que Solis mentis\plain \f1\lang1033\fs26  ... (249\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Secunda pars mensurandi huius doctrine\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 que est planumetria \plain \f1\lang1033\fs26 (!)\plain \f1\i\lang1033\fs26  habet 2 partes\plain \f1\lang1033\fs26  ... (252\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 per eius altitudinem et productum dabit capacitatem\plain \f1\lang1033\fs26 . >\plain \f1\i\lang1033\fs26 Explicit Quadrans\plain \f1\lang1033\fs26 <. \endash  Der Anfang stark verbla\u223 \'dft, auch unter UV-Licht kaum noch lesbar; z.T. bereits in mittelalterlicher Zeit nachgezogen; Text entspricht wohl der 1. bei Hahn (s.u.) gedruckten Fassung; Druck: Paul Tannery, Le Trait\u233 \'e9 du Quadrant, in: Notices et extraits des manuscrits de la Biblioth\u232 \'e8que Nationale et autres Biblioth\u232 \'e8ques 35 (1897), S. 561 \endash  632, bes. S. 593 \endash  632; Nan L. Hahn, Medieval Mensuration. Quadrans Vetus And Geometrie Due sunt Partes Principales, Philadelphia 1982 (Transactions of the American Philosophical Society, Bd. 72,8), S. 6 \endash  112; zur Verfasserfrage vgl. ebenda XV \endash  XXIII; Thomson, Writings, 1940; S. 261, Nr. 53; Lynn Thorndike, Who Wrote Quadrans Vetus, in: Isis 37,3/4 (1947), S. 150 \endash  153; {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Thorndike/ Kibre 1963, Sp. 585}}\plain \f1\lang1033\fs26 ; Glorieux, Facult\u233 \'e9, Nr. 399b.); Weijers, Travail, 1994ff., Bd. 25,8 (2010), S. 154 \endash  156 unter: {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Robertus Anglicus}}\plain \f1\lang1033\fs26  (in Montepessulano magister) [vers 1270], bes. S. 155 \endash  156; Text auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 2661}}\plain \f1\lang1033\fs26 , 135\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 , Exzerpte auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 780}}\plain \f1\lang1033\fs26 , 244\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 . }

