\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 252\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs26  \endash  252\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs26  [249\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs26  \endash  249\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs26 ] {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Kommentar}}\plain \f1\lang1033\fs26  zu (Pseudo-){\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f2\fs26\chcbpat17 \u7790 ?\u257 \'e2bit Ibn-Qurra}}\plain \f2\fs26  (Thebit Ben Corat), De motu octavae sphaerae. (252\plain \f2\super\fs24 ra\plain \f2\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f2\i\fs26\chcbpat17 Zodiacus mobilis qui etc. Scire debes, quod secundum positionem}}\plain \f2\i\fs26  Thebit Benthora filii Tore\plain \f2\fs26  \plain \f2\i\fs26 dupliciter est Zodiachus\plain \f2\fs26 :\plain \f2\i\fs26  Unus fixus\plain \f2\fs26  \plain \f2\i\fs26 et hic est in contrario sphera. Alius mobilis\plain \f2\fs26  ... (252\plain \f2\super\fs24 va\plain \f2\fs26 ) \plain \f2\i\fs26 et recessus Arietis et Libre et per consequens stellarum\plain \f2\fs26  \plain \f2\i\fs26 ex hic motu Arietis et Libra\plain \f2\fs26 , \plain \f2\i\fs26 quem posuit Thebit\plain \f2\fs26 . \endash  Vgl. Carmody, Latin Translation, 1956 (s.o. 153\plain \f2\super\fs24 ra\plain \f2\fs26 ), S. 117 \endash  188, Nr. 18.1; ders., The Astronomical Works of Thabit B. Qurra, Berkeley/ Los Angeles 1960, bes. S. 99; {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f2\fs26\chcbpat17 Thorndike/ Kibre 1963, Sp. 1620}}\plain \f2\fs26 ; Parallel\u252 \'fcberlieferung: {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f2\fs26\chcbpat17 Vatikan, BAV, Cod. Vat. lat. 4275}}\plain \f2\fs26 , 85\plain \f2\super\fs24 v\plain \f2\fs26 . }

