\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 155\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26  \endash  158\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f2\fs26\chcbpat17 Ya\u703 ?aqov Ben-M\u257 \'e2\u7733 ?\u238 ?r Ibn-Tibb\u333 \'f4n}}\plain \f2\fs26  (Prophatius \plain \f1\lang1033\fs26 Judaeus), {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Canon super Almanach perpetuum}}\plain \f1\lang1033\fs26 . (155\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Quia omnes homines naturaliter scire desiderant}}\plain \f1\lang1033\fs26  ... (158\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 et habebis numerum digitorum eclipsis dyametri Solis et motum etiam cursus a principio eclipsis usque infinem eius\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Addantur in Saturno iiii\plain \f1\i\super\lang1033\fs24 or\plain \f1\i\lang1033\fs26  gradus et lvii minuta\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 in Jove removeantur xxiii minuta\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Explicit doctrina canonum super Almanach perpetuum\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Deo gracias\plain \f1\lang1033\fs26 . \endash  Der gleiche Text auf auf 101\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26 ; zu Druck und Sekund\u228 \'e4rliteratur s.o. }

