\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 215\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs26  \endash  215\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Regulae}}\plain \f1\lang1033\fs26  Aequationum Planetarum. (215\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Regule equationum planetarum\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Regule equationis Solis\plain \f1\lang1033\fs26 <. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Cum volueris equare Solem}}\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 extrae\plain \f1\lang1033\fs26  (!) \plain \f1\i\lang1033\fs26 medium cursum eius ex annis collectis\plain \f1\lang1033\fs26  ... >\plain \f1\i\lang1033\fs26 Equatio Lune\plain \f1\lang1033\fs26 <. \plain \f1\i\lang1033\fs26 Cum volueris equare Lunam extrahe medium cursum eius de tabulis suis sicut fecisti de Sole\plain \f1\lang1033\fs26  ... >\plain \f1\i\lang1033\fs26 Equatio Jovis\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 Saturnis et Martis\plain \f1\lang1033\fs26 <. (215\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Cum volueris equare aliquem trium superiorem planetarum\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 ertraes\plain \f1\lang1033\fs26  (!) \plain \f1\i\lang1033\fs26 medium cursum illius\plain \f1\lang1033\fs26  ... >\plain \f1\i\lang1033\fs26 Equatio Veneris et Mercurii\plain \f1\lang1033\fs26 <. \plain \f1\i\lang1033\fs26 Cum volueris equare Veneriem aut Mercurium extrahe residuum cuius eorum locum\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 scire volueris de\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 tabulis\plain \f1\lang1033\fs26  ... (215\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Equatio capitis draconis\plain \f1\lang1033\fs26 <. \plain \f1\i\lang1033\fs26 Cum volueris equare Ieuzahar extractum medium eius cursum\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 et tercia minue de fine gemmorum\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 iii gradus\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 xxiii minutis\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 xli secundis\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 remanent in gemmis xxvi gradu\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 xxx vi p. xix secundis\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 mcxl v xx die Martis\plain \f1\lang1033\fs26 . >\plain \f1\i\lang1033\fs26 Expliciunt regule equationum planetarum\plain \f1\lang1033\fs26 <. \endash  Vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Thorndike/ Kibre 1963, Sp. 353}}\plain \f1\lang1033\fs26 ; Saaby Pedersen, Toledan Tables, 2002 (s. Lit.), Part 1, S. 105, Part 3, S. 755, S. 1211 \endash  1212, CE40, Sigle Da2. }

