\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 82\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  110\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Johannes de Sacrobosco}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 De Sphaera mundi}}\plain \f1\lang1033\fs26 . (82\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Tractatum de Spera quatuor capitulis distinguitur, dicentes primo}}\plain \f1\lang1033\fs26 : \plain \f1\i\lang1033\fs26 Quid sit spera\plain \f1\lang1033\fs26  ... (110\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Aut deus nature patitur\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 aut mundana machina dissolvitur\plain \f1\lang1033\fs26 . \endash  Druck: Thorndike, Sphere, 1949, S. 76 \endash  117; vgl. ebenda, S. 1 \endash  75; Glorieux, Facult\u233 \'e9, S. 235 \endash  236, Nr. 267a.); {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Thorndike/ Kibre 1963, Sp. 1577}}\plain \f1\lang1033\fs26 ; VL(2), Bd. 4 (1983), Sp. 731 \endash  736 (Francis B. Br\u233 \'e9vart/ Menso Folkerts), bes. Sp. 732 \endash  734; Weijers, Travail, 1994ff., Bd. 11,5 (2003), S. 157 \endash  160, bes. S. 159; Text auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 2728}}\plain \f1\lang1033\fs26 , 10\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 2640}}\plain \f1\lang1033\fs26 , 156\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 2661}}\plain \f1\lang1033\fs26 , 116\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ; dazwischen 85\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  ganzseitige Tabelle f\u252 \'fcr die Jahre 1044 \endash  1548. \endash  85\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 , 111\plain \f1\super\lang1033\fs24 r/v\plain \f1\lang1033\fs26 , 112\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  leer. }

