\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  10\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Johannes de Sacrobosco}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Algorismus}}\plain \f1\lang1033\fs26 . (1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Omnia, que a primeva rerum origine processerunt}}\plain \f1\lang1033\fs26  ... (10\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 et hec de radicum extractione\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 dicta sufficiant\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  tam in numeris quadratis quam cubicis\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Explicit\plain \f1\lang1033\fs26 . \endash  Druck: Pedersen, Opera Petri Philomenae, 1983, S. 174 \endash  201; vgl. ebenda S. 167 \endash  172;\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Thorndike/ Kibre 1963, Sp. 991}}\plain \f1\lang1033\fs26 ; Glorieux, Facult\u233 \'e9, S. 235 \endash  236, Nr. 267d.); VL(2), Bd. 4 (1983), Sp. 731 \endash  736 (Francis B. Br\u233 \'e9vart/ Menso Folkerts), bes. Sp. 735 \endash  736; Weijers, Travail, 1994ff., Bd. 11,5 (2003), S. 157 \endash  160, bes. S. 158; Text auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 1227}}\plain \f1\lang1033\fs26 , 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 1415}}\plain \f1\lang1033\fs26 , 36\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 2769}}\plain \f1\lang1033\fs26 , 185\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 2661}}\plain \f1\lang1033\fs26 , 108\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 . }

