\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 27\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \endash  54\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Johannes de Sacrobosco}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Compotus Ecclesiasticus}}\plain \f1\lang1033\fs26  seu De Anni Ratione. (27\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Conpotus est sciencia considerans tempora}}\plain \f1\i\lang1033\fs26  ex solis et lune motibus\plain \f1\lang1033\fs26  ... (54\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 dicitur iterum evum idem quod mora\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Unde Boecius\plain \f1\lang1033\fs26 : \plain \f1\i\lang1033\fs26 O qui perpetua mundum ratione gubernas\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 tu stabilire vel opus hoc per temporis evum amen\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Explicit\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 M Christi bis C. C. quarto deno quater anno\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 ecclesie Christi\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  quod nos hinc fructificemus\plain \f1\lang1033\fs26 . \endash  Die letzten f\u252 \'fcnf Zeilen des abschlie\u223 \'dfenden Boethius-Zitats von anderer Hand nachgetragen; Druck (Textabgleich mit): {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 VD16: ZV 8727}}\plain \f1\lang1033\fs26 ; vgl. Glorieux, Facult\u233 \'e9, S. 235 \endash  236, Nr. 267b.); {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Thorndike/ Kibre 1963, Sp. 243}}\plain \f1\lang1033\fs26 ; VL(2), Bd. 4 (1983), Sp. 731 \endash  736 (Francis B. Br\u233 \'e9vart/ Menso Folkerts), bes. Sp. 735; Weijers, Travail, 1994ff., Bd. 11,5 (2003), S. 157 \endash  160, bes. S. 159; Text auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 1227}}\plain \f1\lang1033\fs26 , 21\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 2661}}\plain \f1\lang1033\fs26 , 170\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 .}

