\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 55\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26  \endash  56\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Johannes Peckham}}\plain \f1\lang1033\fs26  (?), {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Defensio fratrum mendicantium}}\plain \f1\lang1033\fs26 . (55\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 O Christe}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17  (?) }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 vicarie monarcha terrarum}}\plain \f1\lang1033\fs26\chcbpat17 , {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 sacratum gracie cella scripturarum}}\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 minister iusticie et meta causarum\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 mee querimonie aurem prebe parum\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 Hos ergo conuenio\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 ut\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 apud me reos\plain \f1\lang1033\fs26  (55\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs26 ) \u9553 \'a6<\plain \f1\i\lang1033\fs26 tales in me seviunt\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 in me debaccantur\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 sermones confleviunt ut me prosequantur\plain \f1\lang1033\fs26  ...< (56\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 cum autem increbuit fama tanti viri\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 hereticus voluit illam experiri\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 sed virtum non potuis iactu demoliri\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 per quod idem combuit fide stabiliri de predicatoribus possem multa fari\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 pleni sunt sermonibus\plain \f1\lang1033\fs26  (?) \plain \f1\i\lang1033\fs26 in honestate clari desideram se esse consimiles fratribus minoribus denique\plain \f1\lang1033\fs26  (?) \plain \f1\i\lang1033\fs26 finis\plain \f1\lang1033\fs26  (?). \endash  Aufgrund von Beschneiden des Kopfsteges fehlt (55\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs26 ) ein Vers (s.o.); Text endet unvermittelt mit Vers 246 der Ausgabe von Kingsford/ Little/ Tocco (s.u.); Schlu\u223 \'dfverse abweichend; die Autorschaft ist umstritten; der Text wurde auch {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Guido de Marchia}}\plain \f1\lang1033\fs26  und {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Bernardinus Senensis}}\plain \f1\lang1033\fs26  zugeschrieben; Druck: C. L. Kingsford/ A. G. Little/ F. Tocco (Hrsg.), Fratris Johannis Pecham quondam Archiepiscopi Cantuariensis, Tractatus tres de Paupertate ..., Aberdeen 1910 (British Society of Franciscan Studies, Bd. 2), S. 159 \endash  171; vgl. ebenda S. 148 \endash  159; Livarius Oliger, Das Streitgedicht Mundus et Religio in einer Prosabearbeitung des 15. Jahrhunderts, in: Collectanea variae doctrinae Leoni S. Olschki ... M\u252 \'fcnchen 1921, S. 171 \endash  186; {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 12544}}\plain \f1\lang1033\fs26 ; Walther, Streitgedicht, 1920/ 1984, S. 165 \endash  166; Glorieux, Facult\u233 \'e9, S. 231 \endash  232; Glorieux, R\u233 \'e9pertoire, Bd. 2, S. 87 \endash  98, bes. S. 96, Nr. bj.; Weijers, Travail, 1994ff., Bd. 11,5 , S. 139 \endash  146. \endash  56\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs26  leer. }

