\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 142\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  142\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Versus}}\plain \f1\lang1033\fs26  super anno 1349. (142\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Versibus inscriptis videas mala facta sub annis mille trecentenis bis vicenas quoque novenis}}\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Eterni regis oritur confusio legis\plain \f1\lang1033\fs26  ... (142\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Postea durabant motus quoque continuabant annos ultra duos\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  ut scio continuos. Amen\plain \f1\lang1033\fs26 . \endash  Verse zu den Ereignissen der Jahre 1348 und 1349 wie Pest, Flagellantenbewegung etc.; erw\u228 \'e4hnt wird explizit: Basel. }

