\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 143\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  144\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Gebetsanweisung}}\plain \f1\lang1033\fs26  \u8222 \'84F\u252 \'fcnf Messen\ldblquote , dt. (143\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Diz sint andere (?) funf gude messen}}\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Requiem eterna\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Wer dyse funf messen dut sprechin einre selen\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 di wirt herloset\plain \f1\lang1033\fs26  ...; \plain \f1\i\lang1033\fs26 In der ersten messen sol man got manen der unschuldigen gevengnisse\plain \f1\lang1033\fs26  ...; \plain \f1\i\lang1033\fs26 In der ander messen sol man got manen\plain \f1\lang1033\fs26  (143\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 des unschuldigen geriches\plain \f1\lang1033\fs26  ...; \plain \f1\i\lang1033\fs26 In der drithen messen sol man got manen dez unsculdigen nigels\plain \f1\lang1033\fs26  ...; (144\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 In der virden messen sol man got manen der wunden\plain \f1\lang1033\fs26  ...; \plain \f1\i\lang1033\fs26 In der funfte messen sol got man manen daz er begraben wart in die erde\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 dazsie hat verschuldiget mit rethen zunge und von irme eigen willen\plain \f1\lang1033\fs26 . \endash  Zu dem Text vgl. Franz, Messe, 1902 (s.o. 140\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ), S. 261 \endash  263; Druck: ebenda, S. 262; Ruth Wiederkehr, Das Hermetschwiler Gebetbuch. Studien zu deutschsprachiger Gebetbuchliteratur der Nord- und Zentralschweiz im Sp\u228 \'e4tmittelalter, Berlin/ Boston 2013 (Kulturtopographie des alemannischen Raums, Bd. 5), S. 345 \endash  346; Parallel\u252 \'fcberlieferung: {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Berlin, SBB PK, Ms germ. oct. 572}}\plain \f1\lang1033\fs26 , 2\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 M\u252 \'fcnchen, BSB, Cgm 456}}\plain \f1\lang1033\fs26 , 61\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 ebenda, Clm 4391}}\plain \f1\lang1033\fs26 , 122\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Sarnen, Benediktinerkollegium, Cod. chart. 208}}\plain \f1\lang1033\fs26 , 80\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 . }

