\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 148\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  148\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Versus}}\plain \f1\lang1033\fs26  (Wetterregel). (148\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Clara dies Pauli largas fruges notat anni}}\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Si nix vel pluvia tunc fient tempora cara\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 si fuerint nebula\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 pereunt animalia multa etc\plain \f1\lang1033\fs26 . Nachtrag: \plain \f1\i\lang1033\fs26 Swinenfley\plain \f1\lang1033\fs26 (s). \endash  Text endet unvermittelt; dar\u252 \'fcber und darunter Federproben, z. T. radiert; Druck: Werner, Sprichw\u246 \'f6rter, \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs26 1966, S. 28, Nr. 46; vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Thorndike/ Kibre 1963, Sp. 226, 12}}\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 2827}}\plain \f1\lang1033\fs26 ; das gleiche Sprichwort in einer lat.-ital. Version auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 264}}\plain \f1\lang1033\fs26 , 14\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 . \endash  148\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 , hinterer Spiegel Federproben. }

