\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 35\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Opus veri magistri secundum Turbam Philosophorum}}\plain \f1\lang1033\fs26 , Fragment. >\plain \f1\i\lang1033\fs26 Opus veri magistrii secundum Turbam Philosophorum\plain \f1\lang1033\fs26 <. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Recipe precii libra i et sit limatura munda et commisce cum x uncia calcem albi terendo in mortario}}\plain \f1\i\lang1033\fs26  cum sale modico\plain \f1\lang1033\fs26  \u8230 \'85 >\plain \f1\i\lang1033\fs26 Declaracio predicorum per Dicta Philosophorum\plain \f1\lang1033\fs26 <. \plain \f1\i\lang1033\fs26 Nunc pater reverendo revertar ad prius dicta singulariter applicans super ea Dicta Philosophorum obscura\plain \f1\lang1033\fs26  \u8230 \'85 >\plain \f1\i\lang1033\fs26 Primum verbum operis\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 est corporum in Mercuris reductio\plain \f1\lang1033\fs26 \u8230 \'85 >\plain \f1\i\lang1033\fs26 Secundum responsium est\plain \f1\lang1033\fs26 <: \plain \f1\i\lang1033\fs26 Quod sit terra mundificata\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 de quo Morienes dicitur\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 et sic habens quatuor elementa\plain \f1\lang1033\fs26 . >\plain \f1\i\lang1033\fs26 Cetera Dicta Philosophorum\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Recipe infra in quodam folio nigro\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Aqua vite pro cetero opere sic fit\plain \f1\lang1033\fs26 :< \plain \f1\i\lang1033\fs26 Recipe libra i salis armoniaci\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 super lapidem unum in loco humide\plain \f1\lang1033\fs26 . >\plain \f1\i\lang1033\fs26 Item hec est aqua benedicta\plain \f1\lang1033\fs26 <. \endash  Vor allem zu Beginn bestehend aus kurzen Exzerpten aus (Pseudo-){\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Arnoldus de Villa Nova}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Flos Florum}}\plain \f1\lang1033\fs26 ; vgl. Calvet, \u338 \'8cuvres alchimiques, 2011, S. 382 \endash  391; eine weitere, abgek\u252 \'fcrzte Version des Flos Florum auch auf 67\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  (s.u.); Parallel\u252 \'fcberlieferung: {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Vatikan, BAV, Cod. Pal. lat. 1335}}\plain \f1\lang1033\fs26 , 151\plain \f1\super\lang1033\fs24 r \plain \f1\lang1033\fs26 (k\u252 \'fcrzer).}

