\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 50\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \endash  53\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Raimundus Gaufredi}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Verbum abbreviatum de Leone viridi}}\plain \f1\lang1033\fs26 . (50\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Verbum abbreviatum verisissimum et approbatum de occultis enucleatum omnibus philosophie}}\plain \f1\i\lang1033\fs26  filiis in opere Solis alias Lune compilatum \plain \f1\lang1033\fs26 \u8230 \'85 (52\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 si autem color fuerit valde rubeus\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  erit melior\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 ...\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Quatuor elementa seorsum separata\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Idcirco vero ostendere intendimus in verbo nostro abbreviato\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  quam omnia ponitus sunt manifesta\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 In hoc\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  quod lapidem nostrum rediximus \plain \f1\lang1033\fs26 \u8230 \'85 (53\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 cuius una pars tinget centum partes Mercurii in veris Solem etc. finitur opus\plain \f1\lang1033\fs26 . >\plain \f1\i\lang1033\fs26 Explicit verbum abbreviatum\plain \f1\lang1033\fs26 <. \endash  Der Schlu\u223 \'df im Vergleich zum Druck abweichend; Druck: Sanioris medicinae magistri D. Rogeri Baconis Angli de arte chymiae scripta, cui accesserunt opuscula alia eiusdem authoris, Frankfurt am Main 1603, S. 264 \endash  279 ({\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 VD 17: 39:115705L}}\plain \f1\lang1033\fs26 ); vgl. Glorieux, R\u233 \'e9pertoire, S. 60 \endash  76, Nr. 312, bes. S. 62, Nr. 312m.); Glorieux, Facult\u233 \'e9, S. 338 \endash  342, bes. S. 339, Nr. 416m.); Andrew George Little, Roger Bacon\rquote s Works With References to the Mss. and Printed Editions, in: ders. (Hrsg.), Roger Bacon Essays Contributed by Various Writers on the Occasion of the Commemoration of the Seventh Centenary of His Birth, Oxford 1914, S. 373 \endash  419, bes. S. 397 \endash  398, Nr. 21; Thorndike, History, 1923 \endash  1958, Bd. 3 (1934), S. 95; Bd. 4 (1934), S. 15 \endash  17; {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Thorndike/ Kibre 1963, Sp. 1688}}\plain \f1\lang1033\fs26 ; Mohan, Initia, 1975 \endash  1978, (1976), S. 313, (1978), S. 482. }

