\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 58\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \endash  66\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  (Pseudo-){\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Arnoldus de Villa Nova}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Rosarius philosophorum}}\plain \f1\lang1033\fs26 , Versio abbreviata. (58\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 >Incipit compendium Physice Arnordi \plain \f1\lang1033\fs26 (!)\plain \f1\i\lang1033\fs26  de Villa Nova\plain \f1\lang1033\fs26 <. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Scribitur in libro perfecti magisterii, qui in legendis libros deses extiterit}}\plain \f1\i\lang1033\fs26  \plain \f1\lang1033\fs26 ... (66\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Idcirco karissime\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 occultes ipsum \plain \f1\lang1033\fs26 ...\plain \f1\i\lang1033\fs26  indignis et porcis non est largienda \plain \f1\lang1033\fs26 (?). \plain \f1\i\lang1033\fs26 etc\plain \f1\lang1033\fs26 . >\plain \f1\i\lang1033\fs26 Et est finis compendii a magistro Arnoldo de Nova Villa doctore ingeniosissimo subtiliter compilati\plain \f1\lang1033\fs26 <. \endash  Stark abgek\u252 \'fcrzte, aus kurzen Exzerpten bestehende Textversion; vgl. Glorieux, Repertoire, S. 418 \endash  439, S. 423, Nr. 211ai.); {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Thorndike/ Kibre 1963, Sp. 1413}}\plain \f1\lang1033\fs26 ; Thorndike, History, 1923 \endash  1958, Bd. 3 (1934), S. 57 \endash  59, 669 \endash  671; zu {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Arnoldus de Villa Nova}}\plain \f1\lang1033\fs26  s.u. 76\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ; zum Rosarius Philosophorum s.u. 85\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ; Druck (Textabgleich mit): Mangetus, Bibliotheca, 1702, Bd. 1, S. 663 \endash  676; Calvet, Les \u339 \'9cuvres alchimiques, 2011, S. 269 \endash  356; Text auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 1988}}\plain \f1\lang1033\fs26 , 27\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 . }

