\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 66\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \endash  67\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  (Pseudo-){\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Roger Bacon}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 De Sulpure}}\plain \f1\lang1033\fs26 . (66\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Dixerat Philosophus: Sulfur nostrum non est sulfur}}\plain \f1\i\lang1033\fs26  \plain \f1\lang1033\fs26 ...\plain \f1\i\lang1033\fs26  \plain \f1\lang1033\fs26 (67\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 et quando fuit rubam vocaverunt eam sulfur\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 iam tinctum\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 et sanguine et nomine omnis rei rubei\plain \f1\lang1033\fs26 . \endash  Vgl. Dorothea Waley Singer, Catalogue of Latin and Vernacular Alchemical Manuscripts in Great Britain and Ireland Dating From Before the XVI\plain \f1\super\lang1033\fs24 th\plain \f1\lang1033\fs26  Century, 3 B\u228 \'e4nde, Br\u252 \'fcssel 1931, Nr. 209; Parallel\u252 \'fcberlieferung: {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 London, BL, Ms Add. 10764}}\plain \f1\lang1033\fs26 , 230\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 . }

