\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 67\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  68\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  (Pseudo-){\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Arnoldus de Villa Nova}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Flos Florum}}\plain \f1\lang1033\fs26 , Versio abbreviata. (67\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Compostio maioris operis auri secundum Turbam Philosophorum}}\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Recipe solis puri partem unam et sic limatura munda\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Et misce cum septem partibus Mercurii \plain \f1\lang1033\fs26 \u8230 \'85 (68\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Honorate regem vestrum ab igne venientem, dyademate coronatum\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 et ipsum misce quosque ad perfectionem etate perveniat. Cuius pater Sol, mater Luna. Luna pro corpore imperfectionis, Sol pro corpore perfectionis\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Sufficiat enim hic pro opere isto regnacieris \plain \f1\lang1033\fs26 (?) \plain \f1\i\lang1033\fs26 igitur deo\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  qui nobis in parvo domini contulit tam magnum\plain \f1\lang1033\fs26 . \endash  Es handelt sich erneut um eine abgek\u252 \'fcrzte Textversion (s.o. 58\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ); zu Arnoldus de Villa Nova s.u. 76\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ; Exzerpte aus dem Flos florum auch auf 35\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  (s.o.); Druck: Theatrum chemicum ... (s. 39\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ), Bd. 3 (1659), S. 128 \endash  136; Mangetus, Bibliotheca, 1702, Bd. 1, S. 679 \endash  683; Calvet, \u338 \'8cuvres alchimiques, 2011, S. 382 \endash  402. }

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 69\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  75\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Thesaurus Philosophiae}}\plain \f1\lang1033\fs26 . (69\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Incipit Secretum Secretorum omnium philosophorum Ortus Deliciarum et aromatum omnium Thesaurorum \plain \f1\lang1033\fs26 ... <: \plain \f1\i\lang1033\fs26 Thezaurus Philosophie\plain \f1\lang1033\fs26 . Text: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Restat enim illum salutare, cuius sunt omnia, que enim celum}}\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 terram\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 mareque de nichilo creare potuit \plain \f1\lang1033\fs26 \u8230 \'85 (75\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Et nota\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  quando amicitia facta est inter ignem et mercurium \plain \f1\lang1033\fs26 \u8230 \'85 \plain \f1\i\lang1033\fs26 currit et fluit in ictu oculi\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  ut oleum et est ingressivus \plain \f1\lang1033\fs26 \u8230 \'85 \plain \f1\i\lang1033\fs26 tam in duris coporibus quam in mollibus etc. Finitur opus\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  quod nominatus est a philosophis Thezaurus Philosophie\plain \f1\lang1033\fs26 . \endash  Im Vergleich zu den Drucken mit abweichendem Schlu\u223 \'df; vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Thorndike/ Kibre 1963, Sp. 1353}}\plain \f1\lang1033\fs26 ; James Corbett, Catalogue des manuscrits alchimiques latins, 2 B\u228 \'e4nde, Br\u252 \'fcssel 1939 und 1951, Bd. 2 (1951) , S. 146; Druck: Theatrum chemicum ... (s. 39\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ), Bd. 3 (1659), S. 151 \endash  165; Mangetus, Bibliotheca, 1702, Bd. 2, S. 192 \endash  197; Parallel\u252 \'fcberlieferung: {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Orl\u233 \'e9ans, Biblioth\u232 \'e8que municipale, Ms 290 (244)}}\plain \f1\lang1033\fs26 , 209\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 . }

