\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 76\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \endash  78\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  (Pseudo-){\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Arnoldus de Villa Nova}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Cathena aurea}}\plain \f1\lang1033\fs26 . (76\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Vidi senem clarificatum virum surgentem}}\plain \f1\i\lang1033\fs26  in manu sua librum clausum septem signaculis sigillatum tenentem \plain \f1\lang1033\fs26 \u8230 \'85 (78\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Igitur\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  que vidisti intellige et aperietur tibi liber\plain \f1\lang1033\fs26 . \endash  Schlu\u223 \'df im Vergleich zum Druck leicht verk\u252 \'fcrzt; vgl. Glorieux, R\u233 \'e9pertoire, S. 437, Nr. 211ea.); Thorndike, History, 1923 \endash  1958, Bd. 3 (1934), S. 61 \endash  62, Nr. 27, S. 654 \endash  676, bes. S. 675; {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Thorndike/ Kirbe 1963, Sp. 1696}}\plain \f1\lang1033\fs26 ; Paniagua, Corpus cientifico, 1995, bes. S. 22, Nr. III.24; Pereira, L\rquote alchimia, 1995 (s. 76\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ), bes. S. 140; Calvet, Le corpus alchimique, 2005, bes. S. 455; Calvet, Les \u338 \'8cuvres alchimiques, 2011, S. 250 \endash  252; Druck: Theatrum chemicum ... (s. 39\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ), Bd. 3 (1659), S. 761 \endash  763; Calvet, Les \u338 \'8cuvres alchimiques, 2011, S. 548 \endash  554; weitere Lit. s.o. 76\plain \f1\super\lang1033\fs24 r}

