\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 78\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \endash  85\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  (Pseudo-){\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Plato}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Liber quartorum vel Summa Platonis}}\plain \f1\lang1033\fs26 , Exzerpt (Liber II). (78\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Dixit Plato: Cum res ex eodem genere sit radix earum}}\plain \f1\i\lang1033\fs26 .\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Una est diversitas\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  ergo rerum est ex superfluitate \plain \f1\lang1033\fs26 \u8230 \'85 (84\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Dictum est enim\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 quod operatur debet esse diligens in omnibus statibus operis \plain \f1\lang1033\fs26 \u8230 \'85 (85\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Et serva ordinem primi operis in hac secunda operacione\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Si autem fuerit defectus ex parte vasis\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 recipe aliud vas \plain \f1\lang1033\fs26 ...\plain \f1\i\lang1033\fs26  et operare in illo vase ut prius\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 De tanta operis perfectione sit nomen domini benedictum in secula\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Amen\plain \f1\lang1033\fs26 . \endash  Vgl. Corbett, Manuscrits alchimiques latins, 1939 und 1951 (s. 69\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ), Bd. 1 (1939), S. 14, Bd. 2 (1951), S. 146; Dorothea Waley Singer, Alchemical Texts Bearing the Name of Plato, in: Ambix. Being the Journal of the Society for the Study of Alchemy and Early Chemistry Dec. 1946, S. 115 \endash  128, bes. S. 116 \endash  118 und 124 \endash  125; Carmody, Arabic Sciences, 1956, S. 128 \endash  129, Nr. 11d.; Thorndike, History, 1923 \endash  1958, Bd. 2 (1929), S. 782; Bd. 3 (1934), S. 47; {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Thorndike/ Kibre 1963, Sp. 336}}\plain \f1\lang1033\fs26 ; Parallel\u252 \'fcberlieferung: {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Orl\u233 \'e9ans, Biblioth\u232 \'e8que municipale, Ms 290 (244)}}\plain \f1\lang1033\fs26 , 207\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Paris, BN, Ms. lat. 5055}}\plain \f1\lang1033\fs26 , 178\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 . }

