\uc1
\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 112\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  Alchemistische {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Notizen}}\plain \f1\lang1033\fs26  \u252 \'fcberwiegend zum Thema \u8222 \'84De magisterio\ldblquote , u.a.: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Invidi dixerunt philosophi, non omnis qui subliniat}}\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  coquit aliqui \plain \f1\lang1033\fs26 \u8230 \'85 \plain \f1\i\lang1033\fs26 Item dixerunt\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 quod magisterio tribuit\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  quod debet ad errore \plain \f1\lang1033\fs26 \u8230 \'85 \plain \f1\i\lang1033\fs26 Hoc magisterium est nec archanum \plain \f1\lang1033\fs26 \u8230 \'85; au\u223 \'dferdem Zeichnung alchemistischer \u214 \'d6fen.}

