\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 780}}\plain \f1\lang1033\fs26 , 269\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 , vgl. Thorndike, History, 1923 \endash  1958, Bd. 2 ( 1929), S. 223, Anm. 1; Thorndike, Images, 1947, S. 238 \endash  239.}

