\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 51\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \endash  53\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  (Pseudo-){\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Apollonius Tyanensis}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 De imaginibus septem planetarum}}\plain \f1\lang1033\fs26 . (51\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Opus Bellenii de septem imaginibus 7 planetarum\plain \f1\lang1033\fs26 <. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Dixit Bellemus philosophus, qui vocatus est Appollo: Cognovi effectum planetarum}}\plain \f1\i\lang1033\fs26  in diebus et noctibus \plain \f1\lang1033\fs26 \u8230 \'85 (53\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Unde ab Aristotile spiritus planetarum dicuntur et ignei sunt effectus\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Et hec sunt sigilla et caracteres Jovis et Saturni\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 ut in fine istius alterius tractatus patebit\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Et videbitur magnum secretum\plain \f1\lang1033\fs26 . \endash  Recensio a nach Lucentini/ Perrone Compagni, codici di Ermete, 2001, Nr. 35 (s. Lit.), S. 80 \endash  82; vgl. Carmody, Arabic Sciences, 1956, S. 61, Nr. 20; {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Thorndike/ Kibre 1963, Sp. 450}}\plain \f1\lang1033\fs26 ; Text auch auf 78\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  und 79\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  s.u.; {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 780}}\plain \f1\lang1033\fs26 , 272\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ; au\u223 \'dferdem auf 69\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  kurzes Exzerpt des Schlu\u223 \'dfes s.u.; }

