\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 66\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \endash  68\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Liber Orationum planetarum}}\plain \f1\lang1033\fs26 . (66\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Incipit liber Orationum planetarum septem\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Et primo de Saturno\plain \f1\lang1033\fs26 <. \plain \f1\i\lang1033\fs26 In dei nomine\plain \f1\lang1033\fs26 . {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 O tu, domine Saturne alte et revolutio longi spacii}}\plain \f1\lang1033\fs26  \u8230 \'85 (68\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Oratio Lune\plain \f1\lang1033\fs26 <. \plain \f1\i\lang1033\fs26 In nomine dei\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 O Luna fulgens et domina nobilis\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 portratrix lucis de uno planeta ad alium \plain \f1\lang1033\fs26 \u8230 \'85 \plain \f1\i\lang1033\fs26 quod mihi sis adiutrix in hoc quid peto\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Amen\plain \f1\lang1033\fs26 . >S\plain \f1\i\lang1033\fs26 uffumigium lune est\plain \f1\lang1033\fs26 <. \plain \f1\i\lang1033\fs26 Semen belleni\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 cimbalaria et ungula piretrum ana\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Et impastentur cum sanguinem irundium\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Et inde fiant pillule\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 prout dictum est de aliis\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Et serva\plain \f1\lang1033\fs26 . \endash  Druck (nach dieser Hs.): Perrone Compagni, Il Liber orationum planetarum, 2001/1 (s. Lit.), S. 192 \endash  197; vgl. ebenda, S. 189 \endash  191; Lucentini/ Perrone Compagni, codici di Ermete (s. Lit.), 2001, Nr. 29, S. 68 \endash  69; Parallel\u252 \'fcberlieferung: {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Florenz, Biblioteca Medicea Laurenziana, Plut. 89 sup. 38}}\plain \f1\lang1033\fs26 , 76\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Ottobeuren, Bibliothek der Benediktinerabtei, O. 86}}\plain \f1\lang1033\fs26 , 110\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ; unmittelbar anschlie\u223 \'dfend:}

