\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 68\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \endash  70\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 De tincturis, de figuris seu de characteribus et de minera planetarum}}\plain \f1\lang1033\fs26  etc. (68\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Sequitur de tincturis planetarum\plain \f1\lang1033\fs26 <. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Tinctura Saturni est nigra}}\plain \f1\i\lang1033\fs26  \plain \f1\lang1033\fs26 \u8230 \'85 \plain \f1\i\lang1033\fs26 Et Plines dixit\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 quod hec sunt incausta planetarum\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Et ego extraxi ea de libro dicto Secretum Secretorum\plain \f1\lang1033\fs26 . >\plain \f1\i\lang1033\fs26 Sequitur de figuris seu karacteribus planetarum\plain \f1\lang1033\fs26 <. \plain \f1\i\lang1033\fs26 Hec sunt figure planetarum et extraxi\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 eas ex libro\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 qui dicitur Revolutio animarum et corporum et inveni eas duobus modis sicut apparet in sequentibus \plain \f1\lang1033\fs26 \u8230 \'85 (69\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Sequitur de minera Saturni\plain \f1\lang1033\fs26 <. \plain \f1\i\lang1033\fs26 Minera Saturni est attramentum nigrum \plain \f1\lang1033\fs26 \u8230 \'85 >\plain \f1\i\lang1033\fs26 De suffumagio et incausto Solis et Jovis\plain \f1\lang1033\fs26 <. \plain \f1\i\lang1033\fs26 Arsenicum id est auripigmentum duo genera sunt \plain \f1\lang1033\fs26 \u8230 \'85 >\plain \f1\i\lang1033\fs26 Sequitur de karacteribus planetarum per aliam formam\plain \f1\lang1033\fs26 < \u8230 \'85 Exzerpt aus (Pseudo-){\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Apollonius Tyanensis}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 De imaginibus septem planetarum}}\plain \f1\lang1033\fs26 : \plain \f1\i\lang1033\fs26 Cum enim omnia\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  que sunt ad aliquam planetarum horam\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  pertineant ... Unde ab Aristotile dicitur\plain \f1\lang1033\fs26 :\plain \f1\i\lang1033\fs26  Spiritus planetarum dicuntur ignei et effectus eorum. Sigilla Veneris sex sunt ... \plain \f1\lang1033\fs26 (69\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Et sic est finis huiusmodi opusculi de karacteribus\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Et sigillis planetarum secundum Bellenium maximum philosophum\plain \f1\lang1033\fs26 . >\plain \f1\i\lang1033\fs26 Sequitur alius modus secundum alium philosophum\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Et primo de imagine Solis et karecteribus eius\plain \f1\lang1033\fs26 <. \u8230 \'85 \plain \f1\i\lang1033\fs26 Nota quod alius liber habet istas figuras \plain \f1\lang1033\fs26 \u8230 \'85 \plain \f1\i\lang1033\fs26 scilicet pertinent ad primum textum \plain \f1\lang1033\fs26 \u8230 \'85 \plain \f1\i\lang1033\fs26 Sequuntur annuli planetarum secundum intentionem quorundam aliorum philosophorum\plain \f1\lang1033\fs26  \u8230 \'85 (70\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Imago et karacteribus Saturni\plain \f1\lang1033\fs26  \u8230 \'85 \endash  Text mit mehrspaltigen Tabellen und Tafeln der Symbole, Zeichen und Siegel der Planeten, abwechselnd in roter und schwarzer Tinte; 69\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Thorndike/ Kibre 1963, Sp. 145}}\plain \f1\lang1033\fs26 ; au\u223 \'dferdem mit kurzem Exzerpt aus (Pseudo-){\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Apollonius Tyanensis}}\plain \f1\lang1033\fs26 , De imaginibus septem planetarum, s.o.u.u. 51\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 , 78\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 , 79\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ; }

