\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 198\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  [111\plain \f1\super\lang1033\fs24 +v\plain \f1\lang1033\fs26 ] \endash  201\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  [113\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ] Remedia et formulae ad inveniendum thesaurum. (198\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) [111\plain \f1\super\lang1033\fs24 +v\plain \f1\lang1033\fs26 ] >\plain \f1\i\lang1033\fs26 Ad furtum aliter thesaurum\plain \f1\lang1033\fs26 <. \plain \f1\i\lang1033\fs26\chcbpat17 Ad {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\strike\lang1033\fs26\chcbpat17 furtum }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 thesaurum inveniendum hoc breve infrascriptum}}\plain \f1\lang1033\fs26 : \plain \f1\i\lang1033\fs26 Pende ad collum galli albi per totum \plain \f1\lang1033\fs26 \u8230 \'85; >\plain \f1\i\lang1033\fs26 Alio modo ad thesaurum\plain \f1\lang1033\fs26 <. \plain \f1\i\lang1033\fs26 Ad thesaurum inveniendum recipe upupam avem\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  vinam eiusque collo \plain \f1\lang1033\fs26 \u8230 \'85; (199\plain \f1\super\lang1033\fs24 +r\plain \f1\lang1033\fs26 ) [112\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ] >\plain \f1\i\lang1033\fs26 Aliud ad thesaurum\plain \f1\lang1033\fs26 <. \plain \f1\i\lang1033\fs26 Ad thesaurum inveniendum sed cave quia \plain \f1\lang1033\fs26 (?) \plain \f1\i\lang1033\fs26 est periculosum recipe cornicem vinam masculum \plain \f1\lang1033\fs26 \u8230 \'85; >\plain \f1\i\lang1033\fs26 Ad idem alio modo\plain \f1\lang1033\fs26 <. \plain \f1\i\lang1033\fs26 Ad inveniendum thesaurum dispone animam tuam ad orandum pro anima\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  cuius es recepturus \plain \f1\lang1033\fs26 \u8230 \'85; (199\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) [112\plain \f1\super\lang1033\fs24 +v\plain \f1\lang1033\fs26 ] >\plain \f1\i\lang1033\fs26 Alius modus thesaurum inveniendi\plain \f1\lang1033\fs26 <. \plain \f1\i\lang1033\fs26 Ad thesaurum inveniendum inventum fuit hoc experimentum in libro prefati magistri Demetrii\plain \f1\lang1033\fs26 :\plain \f1\i\lang1033\fs26  Curputamus dare fidem \plain \f1\lang1033\fs26 \u8230 \'85; >\plain \f1\i\lang1033\fs26 Alius modus ad idem\plain \f1\lang1033\fs26 <. \plain \f1\i\lang1033\fs26 Ad thesaurum inveniendum simili experimentum inventum in libro prefati magistri Theodori\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 qui habet colorem veritatis\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Tamen magnam opportet habere fidem\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Et super omniam mundiciamus\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 In die Lune in prima hora noctis \plain \f1\lang1033\fs26 \u8230 \'85 (200\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) [113\plain \f1\super\lang1033\fs24 +r\plain \f1\lang1033\fs26 ] \plain \f1\i\lang1033\fs26 semper benedicaris a domino stella celi in honorem factoris tui\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 tibi gracias ago et mei et \plain \f1\lang1033\fs26 (?) \plain \f1\i\lang1033\fs26 te benedico signando locum crucis signaculo\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Hoc dicitur probatum\plain \f1\lang1033\fs26 . \endash  Sammlung von sechs, wohl aus unterschiedlichen Quellen stammenden mantischen {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Rezepten}}\plain \f1\lang1033\fs26  zur Auffindung von Sch\u228 \'e4tzen. \endash  200\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  [113\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ] \endash  205\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  [119\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ], hinterer Spiegel [120\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ] leer. }

