\par \pard\fi0\li0\qj\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs22 Fol. 1 \endash  140\~\~\u183 \'b7\~\~140: 20,5 x 15\~\~\u183 \'b7\~\~Wasserzeichen: Hund, um 90\u176 \'b0 gedreht, mit Halsband und Ring, zwei Varianten (nur 1 \endash  12): 1. sehr \u228 \'e4hnlich Mosin, Bd. 1, T. 283 Nr. 2565 (Namur, Custines, 1371 \endash  1380); 2. \u228 \'e4hnlich Mosin, Bd. 1, T. 283, Nr. 2566 (Bar-le-Duc 1374); Waage, halbrunde Waagschalen, mehrere Varianten, darunter: 1. (nur 36/25) sehr \u228 \'e4hnlich Mosin, Bd. 1, T. 97, Nr. 908 (Bar-le-Duc, Namur, Waide, Artois, Paris 1374, 1370 \endash  1376); 2. sehr \u228 \'e4hnlich Mosin, Bd. 1, T. 97, Nr. 904 (Troyes, Aube, Autun, Chastellaux, Namur, Maastricht, Laon, Polen 1373 \endash  1377 ); 3. (nur 85/96, 94/87) sehr \u228 \'e4hnlich Mosin, Bd. 1, T. 98, Nr. 911 (Remiremont 1364); 4. (nur 85/96, 92/89) sehr \u228 \'e4hnlich und \u228 \'e4hnlich Piccard, Waage, Bd. 5, Nr. III, 31 (Remiremont 1374) (i.e. Briquet, Nr. 2388); 5. sehr \u228 \'e4hnlich und Typus Briquet Nr. 2384 (Sens, Dijon, 1371 \endash  1374); 6. \u228 \'e4hnlich und Typus Briquet Nr. 2387 (Bar-le-Duc, Waide, Paris, 1374 \endash  1376); Dreiberg, dar\u252 \'fcber einkonturiges Kreuz (nur 129/124, 136) Typus Briquet, Nr. 11686; Birne, Frucht mit zwei Bl\u228 \'e4ttern, Stiele mit Ring (nur 114/115, 133/139) zwei Varianten, sehr \u228 \'e4hnlich und \u228 \'e4hnlich Mosin, Bd. 2, T. 494, Nr. 4415 (Split 1372)\~\~\u183 \'b7\~\~Reklamanten, unterstrichen\~\~\u183 \'b7\~\~Schriftraum: 18 \endash  19 x 10,5 \endash  12\~\~\u183 \'b7\~\~139\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22  \endash  140\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  vier- bzw. zweispaltig\~\~\u183 \'b7\~\~49 \endash  63 Zeilen\~\~\u183 \'b7\~\~gotische Buchkursive von einer Hand; 140\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22  Nachtr\u228 \'e4ge von einer zweiten, wenig sp\u228 \'e4teren Hand\~\~\u183 \'b7\~\~2-3zeilige Anfangsbuchstaben in brauner Feder oder Raum daf\u252 \'fcr ausgespart.}

