\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 140\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  Kurze {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Zitate}}\plain \f1\lang1033\fs26  aus {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Thomas de Aquino}}\plain \f1\lang1033\fs26 , Super IV Sententiis, Liber 4, Distinctio 7, Quaestio 3, Articulus 3, Quaestincula 3, ad 1, und Quaestincula 5, sc. 2 und 3. \endash  Druck: Busa, S. Thomae Aquinatis Opera Omnia, 1980, Bd. 1, S. 538c und 539b.}

