\pard\fi0\li0\qj\ri0\sb0\sa600\itap0 {\field{\*\fldinst HYPERLINK "hida://5260[0]/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Papier}}\plain \f1\lang1033\fs26 \~\~\u183 \'b7\~\~37 Bl.\~\~\u183 \'b7\~\~Belgien (?)\~\~{\field{\*\fldinst HYPERLINK "hida://5060[0].5064/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 um 1400}}
\par \pard\fi0\li0\qj\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs22 Fol. 141 \endash  175\~\~\u183 \'b7\~\~Wasserzeichen: Ochsenkopf mit Augen, Nase, Nasenl\u246 \'f6chern und Mund, gewellte Stirn (nur 146/149) sehr \u228 \'e4hnlich Mosin, Bd. 1, T. 136, Nr. 1264 (Reggio-nell\rquote Emilia 1388 \endash  1395); Pfeil und Bogen, mehrere Varianten (in der Regel Fragmente), darunter: 1. (nur 153/ 158) sehr \u228 \'e4hnlich Piccard, Werkzeuge und Waffen, Bd. 9, 1 + 2, Nr. X, 1140 (Bologna 1385); 2. sehr \u228 \'e4hnlich WZIS DE5580-Clm733_42 (Italien 15. Jh.); 3. sehr \u228 \'e4hnlich WZIS DE5580-Clm733_36 (Italien 15. Jh.)\~\~\u183 \'b7\~\~Schriftraum: 15 \endash  15,5 x 9 \endash  10\~\~\u183 \'b7\~\~ 33 \endash  38 Zeilen\~\~\u183 \'b7\~\~Bastarda mit Schleifen von einer Hand; 142\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22  Notahand\~\~\u183 \'b7\~\~Lemmata bzw. Anfangsworte der Kapitel fett und in vergr\u246 \'f6\u223 \'dfertem Schriftgrad, h\u228 \'e4ufig auch unterstrichen\~\~\u183 \'b7\~\~1-4zeilige Anfangsbuchstaben in brauner Feder oder Aussparungen daf\u252 \'fcr\~\~\u183 \'b7\~\~148\plain \f1\super\lang1033\fs24 r \plain \f1\lang1033\fs22 Wortschema in brauner Feder zur \plain \f1\i\lang1033\fs22 Latitudo Sanitatis\plain \f1\lang1033\fs22  (s.u.).}

