\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 176\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  186\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Arnoldus de Villa Nova}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Regimen sanitatis ad regem Aragonum}}\plain \f1\lang1033\fs26 . Rubrik (Nachtrag): (176\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Regimen sanitatis compositum ab Arnaldo de Villa Nova\plain \f1\lang1033\fs26 . Text: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Prima pars vel consideracio sanitatis conservande pertinet}}\plain \f1\i\lang1033\fs26  aeris electioni\plain \f1\lang1033\fs26  ... (186\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Certum est\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 quod ad servandum regimine supradictum, emoroidarum vexatio omnino cessabit\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 in quo salvia recens et plantago equaliter sumpta et conquassata prius bulliantur\plain \f1\lang1033\fs26 . \endash  Text endet unvermittelt in Kapitel 18; urspr\u252 \'fcnglich 1310 in katalanischer Sprache f\u252 \'fcr Jakob II. von Arag\u243 \'f3n in Barcelona oder in Montpellier geschrieben; Druck: Garc\u237 \'eda-Ballester/ McVaugh, Regimen Sanitatis, 1996, S. 433 \endash  466 (Zeile 42); zur Parallel\u252 \'fcberlieferung vgl. ebenda S. 405 \endash  406 (ohne diese Hs.); Glorieux, R\u233 \'e9per\-toire, Nr. 211bl.); {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Thorndike/ Kibre 1963, Sp. 1095}}\plain \f1\lang1033\fs26 ; Xhayet, M\u233 \'e9decine, 2010, S. 55; C.A.L.M.A., Bd. 1,2 (2003), S. 442 \endash  459, bes. S. 455, Nr. 72 (Marco Toste/ F.S./ Jos\u233 \'e9 Carlos Santos Paz); vgl. auch {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 815}}\plain \f1\lang1033\fs26 , 25\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 . }

