\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 295\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  295\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Expositio}}\plain \f1\lang1033\fs26  lectionum in Vigilis defunctorum. (295\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) Rubrik: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Expositio lectionum, que leguntur in Vigiliis defunctorum}}\plain \f1\lang1033\fs26 . Text: \plain \f1\i\lang1033\fs26 Primi pussilus redeptor\plain \f1\lang1033\fs26  (!) \plain \f1\i\lang1033\fs26 hominis visitet illum\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 nunc sigillatim\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 dicamus omnes\plain \f1\lang1033\fs26 :\plain \f1\i\lang1033\fs26  Parce mihi domine\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 Et quoniam benigne vilitas spiritum meum\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 Abscondit deus faciem suam ab hominem propter peccatum Ade\plain \f1\lang1033\fs26  ... (295\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Et quia concipitur in peccato et in dolore carnis\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 qui solus est deus conceptus cum peccato quasi\plain \f1\lang1033\fs26  (?) \plain \f1\i\lang1033\fs26 de spiritu sancto conceptus est\plain \f1\lang1033\fs26 .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 296\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  296\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Expositiones}}\plain \f1\lang1033\fs26  lectionum mortuorum. (296\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) Rubrik: \plain \f1\i\lang1033\fs26 Expositiones lectionum Vigiliarum\plain \f1\lang1033\fs26 . Text: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Job sedens in sterquilinio id est in putredine ulceribus}}\plain \f1\i\lang1033\fs26  plenus putredinem radens de capite suspirans\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 Parce mihi domine nihil enim sunt dies mei\plain \f1\lang1033\fs26  ... (296\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 quoniam Iob noverat se morituri et honoratum peccato\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 cui se ipsum accusat ulceribus et putretudinem\plain \f1\lang1033\fs26  (?) \plain \f1\i\lang1033\fs26 peccatis\plain \f1\lang1033\fs26  (?) \plain \f1\i\lang1033\fs26 amen\plain \f1\lang1033\fs26 . \endash  Die letzten Worte verbla\u223 \'dft, kaum noch lesbar.}

