\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  5\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 De nominibus numeralibus}}\plain \f1\lang1033\fs26 . (1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Circa nomina numeralia notandum, quod quinque sunt genera}}\plain \f1\i\lang1033\fs26  principaliora numerorum\plain \f1\lang1033\fs26  (?): \plain \f1\i\lang1033\fs26 cardinalia\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 distributiva\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 pondentalia\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 multiplicativa\plain \f1\lang1033\fs26  ... (5\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Nota Florista ponit hos versus de predictis nominibus\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 Et hec dicta de nominibus numeralibus et de adverbiis sufficiant\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Finis\plain \f1\lang1033\fs26 . Nachtrag. \plain \f1\i\lang1033\fs26 Deum \plain \f1\lang1033\fs26 \endash \plain \f1\i\lang1033\fs26  Gott\plain \f1\lang1033\fs26 . \endash  Vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Bursill-Hall, Census, 1981, Nr. 159.6}}\plain \f1\lang1033\fs26 ; Parallel\u252 \'fcberlieferung: {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Mainz, Stb, Hs I 314}}\plain \f1\lang1033\fs26 , 133\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 . }

