\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  Vers de BMV Rubrik: \plain \f1\i\lang1033\fs26 Exemple de notre dame\plain \f1\lang1033\fs26 . Text: \plain \f1\i\strike\lang1033\fs26 Tout ainfin com descend en la fleur\plain \f1\lang1033\fs26 . {\field{\*\fldinst HYPERLINK "hida://5650[0].5666v/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Tout ainsi com descend en la fleur la rosee}}\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 La voix en la maison sans porte deffermee\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 La face en ung miroeil sans point descoloree\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Descendit le filz dieu en la vierge honoree\plain \f1\lang1033\fs26 . \endash  Vier {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Verse}}\plain \f1\lang1033\fs26 ; \u228 \'e4hnliche Verse u.a. in: {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Laon, BM, Ms. 243 ter}}\plain \f1\lang1033\fs26 , 283\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Paris, BN, Ms. fr. 2206}}\plain \f1\lang1033\fs26 , 4\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 ebenda, Ms. Nouv. Acq. lat. 3203}}\plain \f1\lang1033\fs26 , 166\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Vatikan, BAV, Cod. Ottob. 1212}}\plain \f1\lang1033\fs26 , 2\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ;. \endash  1\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  leer. }

