\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 145\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \endash  146\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  Duo {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Orationes}}\plain \f1\lang1033\fs26  ad Deum (Versus sancti Bernardi). (145\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 O bone Jesu\plain \f1\lang1033\fs26 <. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Illumina oculos meos ne unquam ob dormiam in morte}}\plain \f1\lang1033\fs26  ... >\plain \f1\i\lang1033\fs26 Oremus\plain \f1\lang1033\fs26 <. \plain \f1\i\lang1033\fs26 Omnipotens sempiterne deus\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  qui\plain \f1\lang1033\fs26  (146\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Ezequie regi Jude\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 deplorare veniam et graciam secondum \plain \f1\lang1033\fs26 (!)\plain \f1\i\lang1033\fs26  tuam misericordiam obsequi mereamur per Christum dominum nostrum\plain \f1\lang1033\fs26 . \endash  Aufgrund von Blattverlust (s.o.) ist der Schlu\u223 \'df des Textes von anderer, wenig sp\u228 \'e4terer Hand eingetragen; vgl. Leroquais, Les livres d'heures. Manuscrits, Bd. 1, S. XXX, 31, 71, 77, 86, 100, 121, 122, 123, 125, 136, 143, 151, 154, 174, 198; Bd. 2, S. 254. }

