\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 151\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  152\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Oratio}}\plain \f1\lang1033\fs26  ad Corpus Christi. (151\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 O bone >Jesu<, o dulcissime >Jesu<}}\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 o clementissime \plain \f1\lang1033\fs26 >\plain \f1\i\lang1033\fs26 Jesu\plain \f1\lang1033\fs26 <, \plain \f1\i\lang1033\fs26 o \plain \f1\lang1033\fs26 >\plain \f1\i\lang1033\fs26 Jesu\plain \f1\lang1033\fs26 <\plain \f1\i\lang1033\fs26  fili Marie plenus misericordia et pietate\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 o dulce \plain \f1\lang1033\fs26 >\plain \f1\i\lang1033\fs26 Jesu\plain \f1\lang1033\fs26 <\plain \f1\i\lang1033\fs26  secundam magnam misericordiam tuam miserere mei\plain \f1\lang1033\fs26  ... (152\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 et in te gloriari\plain \f1\lang1033\fs26 .\plain \f1\i\lang1033\fs26  Et omnes\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  qui invocavit hoc nomen sanctum tuum\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  quod est\plain \f1\lang1033\fs26  >\plain \f1\i\lang1033\fs26 Jesu\plain \f1\lang1033\fs26 <. \plain \f1\i\lang1033\fs26 Amen\plain \f1\lang1033\fs26 . >\plain \f1\i\lang1033\fs26 Deo gracias\plain \f1\lang1033\fs26 <. \endash  Druck: Horae Eboracenses, 1920 (s.o. 146\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ), S. 179 \endash  180; vgl. Leroquais, Les livres d'heures. Manuscrits, Bd. 2, S. 79; ders., Breviaires, Bd. 6, S. 338; Text auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 1094}}\plain \f1\lang1033\fs26 , 141\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 521}}\plain \f1\lang1033\fs26 , 255\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs26 ; vgl. DA LuHB Kat. 3, S. 61 und 101.}

