\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 152\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  152\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Orationes}}\plain \f1\lang1033\fs26  de sancto {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Paulo}}\plain \f1\lang1033\fs26 , de sancto {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Iodoco}}\plain \f1\lang1033\fs26  et de sancto {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Petro}}\plain \f1\lang1033\fs26 . (152\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) 1. De sancto Paulo. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Sancte Paule Apostole Christi predicator veritatis et doctor gentium intercede}}\plain \f1\lang1033\fs26  ...; 2. De sancto Iodoco. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Deus, qui beatissimum Iudocum confessorem tuum eternitatis gloria}}\plain \f1\lang1033\fs26  (152\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 sublimasti\plain \f1\lang1033\fs26  ...; 3. De sancto Petro. {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Sancte Petre princeps Apostolorum, cui deus tradidit claves regni}}\plain \f1\i\lang1033\fs26  \plain \f1\i\strike\lang1033\fs26 sui\plain \f1\i\lang1033\fs26  celoris\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 ut ibi me in eterna requie\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  cuius omnibus electis\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 permaneam Christo largiente\plain \f1\lang1033\fs26 . \endash  Zu 1. Parallel\u252 \'f