\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 163\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  Duo {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Orationes}}\plain \f1\lang1033\fs26  de sancta {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Barbara}}\plain \f1\lang1033\fs26  cum Versus. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Salve sancta Barbara. Salve virgo et martir benedicta}}\plain \f1\i\lang1033\fs26 , salve\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 corpus virgineum\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 et semper de dono glorie\plain \f1\lang1033\fs26 . >\plain \f1\i\lang1033\fs26 Versus\plain \f1\lang1033\fs26 <. \plain \f1\i\lang1033\fs26 Ora pro nobis beata virgo et martir Barbara\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 ut digni efficiamur promissionibus Christi\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Oremus\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Concede quesumus omnipotens deus\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 ut qui peccatorum nostrorum pondere gravamur per intercessionem beatissime Barbare virginis\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 quod nobis concedat unus deus\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  pater\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  filius et spiritus sanctus\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Amen\plain \f1\lang1033\fs26 . \endash  Zum Versus vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 CAO Nr. 7326}}\plain \f1\lang1033\fs26 . }

