\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 163\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  163\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  Duo {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Orationes}}\plain \f1\lang1033\fs26  de sancto {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Christophoro}}\plain \f1\lang1033\fs26 . (163\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Bonus adleta }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 (!)}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17  Christoforus laudans deum suum}}\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 orabat dicens\plain \f1\lang1033\fs26  ... (163\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Posuisti domine super caput eius coronam de lapide precioso\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Oremus\plain \f1\lang1033\fs26 . \endash  Gebet aus der Passio S. Christofori martyris; Druck: Analecta Bollandiana 3 (1884), S. 171; auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Cambrai, BM, Cod. 98}}\plain \f1\lang1033\fs26 , 204\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Douai, BM, Cod. 857}}\plain \f1\lang1033\fs26 , 123\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ; (163\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Deus, qui beatum Christoforum martirem tuum virtute constancie}}\plain \f1\i\lang1033\fs26  in passione roborasti\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 ad regna celestia pervenire feliciter mereamur\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Per dominum nostrum Jesum Christum\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 etc\plain \f1\lang1033\fs26 . Anschlie\u223 \'dfend Segen: \plain \f1\i\lang1033\fs26 Benedictum sit nomen domini nostri Jesu Christi et gloriose virginis Marie matris eius in eternum et ultra\plain \f1\lang1033\fs26 . >\plain \f1\i\lang1033\fs26 Amen\plain \f1\lang1033\fs26 <. Danach Mt. 8, 8. \endash  Gebet auch in {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Ebstorf, Klosterbibliothek, Cod. IV 16}}\plain \f1\lang1033\fs26 , 17\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://5007[3].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 K\u243 \'f3rnik, BPAN, Cod. 27}}\plain \f1\lang1033\fs26 , 173\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://5007[4].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Stuttgart, WLB, HB I 174}}\plain \f1\lang1033\fs26 , 112\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 . }

