\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 164\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  165\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hymnus}}\plain \f1\lang1033\fs26  BMV. (164\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Salve mater salvatoris, vas electum creatoris, deus celi civium}}\plain \f1\lang1033\fs26  ... (165\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Ave virgo\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  que tuo nato\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 prece commenda placato,\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 celi tradens gaudia\plain \f1\lang1033\fs26 . >\plain \f1\i\lang1033\fs26 Amen\plain \f1\lang1033\fs26 <. \plain \f1\i\lang1033\fs26 Ave Maria\plain \f1\lang1033\fs26 . Anschlie\u223 \'dfend liturgische Anweisung: \plain \f1\i\lang1033\fs26 Si quis cupit videre beatam virginem ante finem obbitus sui\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 dicat illam oracionem devote\plain \f1\lang1033\fs26  \u8218 \'82\plain \f1\i\lang1033\fs26 Salve mater salvatoris\plain \f1\lang1033\fs26 \rquote  \plain \f1\i\lang1033\fs26 con \plain \f1\lang1033\fs26 \u8218 \'82\plain \f1\i\lang1033\fs26 Ave Maria\plain \f1\lang1033\fs26 \u8219 ?\plain \f1\i\lang1033\fs26  et ista oracione graciam tuam mentibus\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 responde nostris etc\plain \f1\lang1033\fs26 . Schreibervermerk: >\plain \f1\i\lang1033\fs26 Dat nobis altissimus adversa com\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 prosperis equo animo tollerare\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Amen\plain \f1\lang1033\fs26 <. \endash  Druck: Mone, Hymnen, 1854, Bd. 2 (Marienlieder), S. 307 \endash  308, Nr. 522; im Vergleich zum Druck mit leichten Abweichungen im Wortlaut; vgl. Mohan, Initia, 1975 \endash  1978 (1978), S. 393; vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Chevalier, Repertorium, Nr. 18049}}\plain \f1\lang1033\fs26 .}

