\pard\fi0\li0\qj\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs22 Staub, Wimpfen, 1967, S. 186 \endash  187 irrt\u252 \'fcmlich mit der Signatur: 2624\~\~\u183 \'b7\~\~Staub, Wimpfen, 1980, S. 22, 117 \endash  118\~\~\u183 \'b7\~\~Kr\u228 \'e4mer, Handschriftenerbe, 1989, Bd. 2, S. 839\~\~\u183 \'b7\~\~Kristeller, Iter, Bd. 6 (1992), S. 504\~\~\u183 \'b7\~\~Hasebrink, Latinit\u228 \'e4t, 2000, S. 49 \endash  76, bes. S. 75 \endash  76\~\~\u183 \'b7\~\~Baldzuhn, Schulb\u252 \'fccher, 2009, Bd. 2, S. 493\~\~\u183 \'b7\~\~Kr\u228 \'e4mer, Scriptores, 2003 \endash  2009, unter: Carnifex (Carnificis), Jacobus, scriptor, vor 1486\~\~\u183 \'b7\~\~Klein-Ilbeck, Dat. Hss. }

