\pard\fi0\li0\qj\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs22 Staub, Wimpfen, 1980, S. 116, S. 133, Nr. 141, S. 135, Nr. 158 und 159\~\~\u183 \'b7\~\~Kr\u228 \'e4mer, Handschriftenerbe, 1989, Bd. 2, S. 839\~\~\u183 \'b7\~\~Kristeller, Iter, Bd. 3 (1983), S. 513; Bd. 6 (1992), S. 504\~\~\u183 \'b7\~\~Polak, Letter Treatises, 1993 \endash  2015, Bd. 3 (2015), S. 370. }

