\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 109\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  113\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Crates Thebanus}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Epistolae}}\plain \f1\lang1033\fs26  cynicae (Translatio {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Athanasii Constantinopolitani}}\plain \f1\lang1033\fs26 ). (109\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) Vorrede. \plain \f1\i\lang1033\fs26 Athanasius Constantinopolitanus Archiensis abbas\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 ad divum principem Karrolum Aragonum primogenitum etc\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Cum superioribus diebus me illustrissime princeps Panthormum cum tuis litteris commendatitys ad excellentissimum Sicilie pro regem pro mei capiendi monastery possessione contulissem possessionem quidem haut habere potui\plain \f1\lang1033\fs26  ... (113\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) Rubrik: \plain \f1\i\lang1033\fs26 Anacharsis Atheniensibus felicitatem\plain \f1\lang1033\fs26 . Text: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Videtes ne quia grece recte non loquor}}\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 nemini huiusmodi cogitacio est\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Finis Cynicarum Cratis\plain \f1\lang1033\fs26 . \endash  M\u246 \'f6glicherweise ebenfalls Abschrift eines Druckes, Druck: {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 GW 07819}}\plain \f1\lang1033\fs26  (Paris, Petrus Caesaris und Johannes Stol um 1474 oder 1478); {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 M34884}}\plain \f1\lang1033\fs26  (Strassburg 1486); {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 M32865}}\plain \f1\lang1033\fs26  (Paris 1472); Textabgleich mit {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 M34884}}\plain \f1\lang1033\fs26  und {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 M32865}}\plain \f1\lang1033\fs26 . \endash  113\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \endash  114\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  leer. }

