\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 125\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26  \endash  127\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Nicolaus Oresmius}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Quaestiones}}\plain \f1\lang1033\fs26  in quartum Librum metheororum. (125\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26 ) Vermerk {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Philippes d\rquote Oth\u233 \'e9e}}\plain \f1\lang1033\fs26 : \plain \f1\i\lang1033\fs26 Questiones supra quartum metheororum sed non sunt nisi tria folia\plain \f1\lang1033\fs26 .\plain \f1\i\lang1033\fs26  \plain \f1\lang1033\fs26 Text:\plain \f1\i\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Queritur primo circa quartum metheororum}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 ,}}\plain \f1\i\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 utrum sint tantum quatuor qualitates}}\plain \f1\i\lang1033\fs26  prime\plain \f1\lang1033\fs26  ... (127\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 post in una parte quam in alia non obstantibus omnibus predictis conditionibus\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Ad aliam sequente\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  quod erat rescripta\plain \f1\lang1033\fs26  (?) \plain \f1\i\lang1033\fs26 infrascripta\plain \f1\lang1033\fs26  (?). \endash  Zu Text und Sekund\u228 \'e4rliteratur s.o. 58\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26 . }

