\pard\fi0\li0\qj\ri0\sb0\sa600\itap0 \plain \f1\lang1033\fs26 6 Bl.\~\~\u183 \'b7\~\~29 x 21\~\~\u183 \'b7\~\~Paris\~\~{\field{\*\fldinst HYPERLINK "hida://5060[0].5064/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 14. Jh. Mitte}}
\par \pard\fi0\li0\qj\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs22 Fol. 193 \endash  198\~\~\u183 \'b7\~\~Wasserzeichen: Vase, offen, ohne Henkel Typus Mosin, T. 435, Nr. 3944\~\~\u183 \'b7\~\~Schrift\-raum: 22 x 16 \endash  16,5; Spaltenbegrenzungen mit Tintenlinien\~\~\u183 \'b7\~\~zweispaltig\~\~\u183 \'b7\~\~62 \endash  66 Zei\-len\~\~\u183 \'b7\~\~gotische Buchkursive in sehr kleinem Schriftgrad wohl von einer Hand\~\~\u183 \'b7\~\~Lemmata und \u220 \'dcber\-schriften fett, in vergr\u246 \'f6\u223 \'dfertem Schriftgrad und in Textualis\~\~\u183 \'b7\~\~Raum f\u252 \'fcr 3-5zeilige Anfangsbuchstaben ausgespart. }

