\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 xvi\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \endash  xxii\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Facetus}}\plain \f1\lang1033\fs26  \u8218 \'82Cum nihil utilius\lquote . (xvi\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Male tibi mente dones ter tresque ducenti annos\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  si queris\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  hic bene doctus eris\plain \f1\lang1033\fs26 <. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Cum nichil utilius humane credo saluti}}\plain \f1\lang1033\fs26  ... (xxi\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 sepe nocet\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  qui multa docet\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 quia vix retinentur\plain \f1\lang1033\fs26  (xxii\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 excogitur quidquid capitur\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  dum pauca docentur\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 >Explicit Facesias deo gracias\plain \f1\lang1033\fs26 <. \endash  Vereinzelt mit interlinearen, h\u228 \'e4ufig deutschen Wortglossen; Reihenfolge der Verse und Versbestand im Vergleich zu dem Druck bei Schr\u246 \'f6der (s.u.) h\u228 \'e4ufig abweichend; offenbar k\u252 \'fcrzende Bearbeitung; letzter Vers ist Vers 153 der genannten Ausgabe; Druck: Schr\u246 \'f6der, Facetus, 1911, S. 18 \endash  25; \plain \f2\lang1024\fs26 Zato\u269 \'e8il, Cato a Facetus, 1952\plain \f1\lang1033\fs26 , S. 287 \endash  292; vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 10632, 3692}}\plain \f1\lang1033\fs26 ; Henkel, \u220 \'dcbersetzungen, 1988, S. 245 \endash  248; VL(2), Bd. 2 (1980), Sp. 701 \endash  703 (R\u252 \'fcdiger Schnell); Bd. 11 (2004), Sp. 436; Orb\u225 \'e1n, Novus Phisiologus, 1989 (s. Lit.), S. 8; Kohush\u246 \'f6lter, Gregorius, 2012 (s. Lit.), S. 52 \endash  53; Rubel, S\u252 \'fcnder, \plain \f1\super\lang1033\fs24 1\plain \f1\lang1033\fs26 2009 /\plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs26 2019 (s. Lit.), S. 39; Daniel Ermens, Views on the Oudenaarde Verse Book, in: Karen Pratt/ Bart Besamusca/ Matthias Meyer/ Ad Putter (Hrsg.), The Dynamics of the Medieval Manuscript, G\u246 \'f6ttingen 2017, S. 111 \endash  130, bes. S. 117 und 127; Text auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 739}}\plain \f1\lang1033\fs26 , 152\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs26  (nur die Anfangsverse); {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 2327}}\plain \f1\lang1033\fs26 , 225\plain \f1\super\lang1033\fs24 r \plain \f1\lang1033\fs26 (Fragment); Fragmente des Facetus auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 2253}}\plain \f1\lang1033\fs26 , Falzstreifen, vgl. DA ULB Kat. 5,2.}

