\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 1\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \endash  6\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Maino de Maineri}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Liber medicinalis}}\plain \f1\lang1033\fs26 , Exzerpt: De aquis artificialibus. (1\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Ex quodam libro tamen theoretice quam practice subtilissime composito}}\plain \f1\i\lang1033\fs26  extraxi ea\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 que secuntur et quorum credo proprius libri Maiminum actorem extitisse\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Ideo hic posui cum hoc regimine sanitatis a prefato Maynino Mediolanensis composito\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Dividitur autem prefatus liber in 4\plain \f1\i\super\lang1033\fs24 or\plain \f1\i\lang1033\fs26  tractatus\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 qualibet tractatus dividitur in summas\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 de summe dividuntur in capitula\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Summa secunda tractatus primi tractat de aquas artificalibus in generali\plain \f1\lang1033\fs26 . >\plain \f1\i\lang1033\fs26 Capitulum primum determinat quare dicuntur\plain \f1\lang1033\fs26  (?) \plain \f1\i\lang1033\fs26 aqua artificalis\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 dicens\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 quod non dicuntur artificiales et quod forma per quam operantur\plain \f1\lang1033\fs26  ... (3\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) Text bricht ab: \plain \f1\i\lang1033\fs26 Capitulum 15\plain \f1\i\super\lang1033\fs24 m\plain \f1\i\lang1033\fs26  de aqua citroniorum et rosis\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 stomacum confortat et ventrem surgat\plain \f1\lang1033\fs26 . \u9553 \'a6 (4\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) Text beginnt: \plain \f1\i\lang1033\fs26 Capitulum 21\plain \f1\i\super\lang1033\fs24 m\plain \f1\i\lang1033\fs26  de aqua plantaginis et factam circa 2\plain \f1\i\super\lang1033\fs24 um\plain \f1\i\lang1033\fs26  gradus\plain \f1\lang1033\fs26  ... (6\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Capitulum 53\plain \f1\i\super\lang1033\fs24 um\plain \f1\i\lang1033\fs26  de aqua juniperi et canda est\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 si fiat balneum ex ea\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Et sic finitur ille primo tractatus cum dei adiutorio\plain \f1\lang1033\fs26 . >\plain \f1\i\lang1033\fs26 Amen\plain \f1\lang1033\fs26 <. \endash  Wohl Auszug aus dem Liber medicinalis; zum Autor Weijers, Travail, 1944ff., Bd. 13,6 (2005), S. 71 \endash  72; \plain \f2\lang1024\fs26 Zdzis\u322 \'b3aw \plain \f1\lang1033\fs26 Kuksewicz, Maino of Milan. A Fourteenth Century Parisian Averroist, in: Medioevo 31 (2006), S. 337 \endash  375; \u228 \'e4hnlich dem Traktat in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Vatikan, BAV, Cod. Pal. lat. 1264}}\plain \f1\lang1033\fs26 , 232\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ; gegen\u252 \'fcber den anderen in Handschriften der Bibliotheca Palatina erhaltenen Textzeugen jedoch stark abweichend. }

