\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 12\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \endash  13\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  Verschiedene {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Inschriften}}\plain \f1\lang1033\fs26 , u.a. aus Spanien (Alicante) und Rom. (12\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) 1. Vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Bertalot, Initia humanistica, Bd. 1 (1985), Nr. 6268}}\plain \f1\lang1033\fs26 ; 2. Vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 6336}}\plain \f1\lang1033\fs26 ; 3. >\plain \f1\i\lang1033\fs26 In alio latere lapidis\plain \f1\lang1033\fs26 <. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f2\i\lang1024\fs26\chcbpat17 Omnis \u281 \'eatas de tempore suo conquesta est}}\plain \f1\lang1033\fs26 . 4. vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Bertalot, Initia humanistica, Bd. 1 (1985), Nr. 5576}}\plain \f1\lang1033\fs26 ; (13\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) 5. vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[2].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Schaller/ K\u246 \'f6nsgen, Initia carminum, 1977, Nr. 16531}}\plain \f1\lang1033\fs26 ; 6. >\plain \f1\i\lang1033\fs26 Praenestinae in templo fortunae\plain \f1\lang1033\fs26 <. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Tu qui Tarpeio coleris vicina tonanti}}\plain \f1\lang1033\fs26  ...; (13\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) 7. >\plain \f2\i\lang1024\fs26 Rom\u281 \'ea infra quandam vineam in monte Virinali\plain \f1\lang1033\fs26 <. {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Votum Silvano solvit libes merito}}\plain \f1\i\lang1033\fs26  T F. Diadumenus Lurneslanus praegustator Augusti. Infoelix fatum prior debui mori mater\plain \f1\lang1033\fs26 . }

