\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 74\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  82\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Giovanni Gioviano Pontano}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 De Tumulis}}\plain \f1\lang1033\fs26 , Exzerpte. (74\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Tumulus Drusille\plain \f1\lang1033\fs26 <. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Tu ne eciam Drusilla taces te ne improba cloto abstuli}}\plain \f1\i\lang1033\fs26  \plain \f1\lang1033\fs26 \u8230 \'85 (81\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Tumulus Myrtisse\plain \f1\lang1033\fs26 <. \plain \f1\i\lang1033\fs26 Hic soli mihi flere licet\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Tu laurus et una myrthus ades \plain \f1\lang1033\fs26 \u8230 \'85 (82\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Et Fluidum me tamen urit amor\plain \f1\lang1033\fs26 . \endash  Enthalten sind aus Liber 1 die Verse VII, IX, XIX \endash  XXI, XXXVIII, LI, aus Liber 2 die Versinschriften II, IV \endash  VI, XIX \endash  XXI, XXXIX, XLI, LV \endash  LVIII der Ausgabe von Oeschger (s.u.); Druck: Johannes Oeschger (Hrsg.), Ioannis Ioviani Pontani Carmina. Ecloghe \endash  Elegie \endash Liriche, Bari 1948 (Scrittori d\rquote Italia, N. 198), S. 189 \endash  258.}

