\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 91\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  92\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Giovanni Gioviano Pontano}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 De amore coniugali libri III}}\plain \f1\lang1033\fs26 , Exzerpt aus Liber 2. (91\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Nenia prima ad somnum provocandum\plain \f1\lang1033\fs26 <. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Somne veni, tibi Luciolus blanditur ocellis}}\plain \f1\i\lang1033\fs26  \plain \f1\lang1033\fs26 \u8230 \'85 (91\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Nenia secundo. Iocatur\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 nutrix\plain \f1\lang1033\fs26 <. \plain \f1\i\lang1033\fs26 Ne vagi\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  ne\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  blande puer\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  ne\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  parvule\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  vagi \plain \f1\lang1033\fs26 \u8230 \'85 (92\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Nenia tertia\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Nutrix cavit\plain \f1\lang1033\fs26 <. \plain \f1\i\lang1033\fs26 Has ego Luciolo mammas hec ubera sevio\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 dextera mamma tua est\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 ipsa sinistra mea est \plain \f1\lang1033\fs26 \u8230 \'85 \plain \f1\i\lang1033\fs26 auferat et clauso scite reconde sinu\plain \f1\lang1033\fs26 . >\plain \f1\i\lang1033\fs26 Finis\plain \f1\lang1033\fs26 <. \endash  Enthalten sind ein Teil der Wiegenlieder f\u252 \'fcr den Sohn des Autors, Lucio, Carmina VIII \endash  X (Naenia prima \endash  tertia); Druck: M. Soldati, Ioannis Ioviani Pontani carmina, Florenz 1902; Oeschger, Ioannis Ioviani Pontani Carmina, 1948 (s.o. 74\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ), S. 163 \endash  165; vgl. Widu-Wolfgang Ehlers, Liebes-, Lebens-, Ehepartner. Pontanos \u8222 \'84Amores coniugales\ldblquote , in: Mittellateinisches Jahrbuch 35 (2000), S. 81 \endash  99; zum Autor, dem italienischen Humanisten {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Giovanni Gioviano Pontano}}\plain \f1\lang1033\fs26  (*1429, \u8224 \'861503) s.o. 74\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 . }

