\pard\fi0\li0\qj\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs22 Teilweise mit Wasserschaden\~\~\u183 \'b7\~\~Lagen: 7 VI\plain \f1\super\lang1033\fs24 84\plain \f1\lang1033\fs22  + V\plain \f1\super\lang1033\fs24 94\plain \f1\lang1033\fs22  + VI\plain \f1\super\lang1033\fs24 106\plain \f1\lang1033\fs22  + 4 V\plain \f1\super\lang1033\fs24 146\plain \f1\lang1033\fs22  + 8 VI\plain \f1\super\lang1033\fs24 242\plain \f1\lang1033\fs22 \~\~\u183 \'b7\~\~Wasserzeichen: Quaste, frei ohne Beizeichen, f\u252 \'fcnf Varianten: 1. \u228 \'e4hnlich WILC WM I 02377 (Niederlande 1477); 2. \u228 \'e4hnlich WZIS DE0960-4Inc820a_999h (K\u246 \'f6ln um 1476); 3. \u228 \'e4hnlich WZIS DE2130-C30_44v (Rhein\-land um 1475/ 1488); 4. \u228 \'e4hnlich WILC WM I 02633 (Niederlande 1477); 5. \u228 \'e4hnlich WZIS DE0960-4Inc1536_182; Buchstabe P, gebrochen, zweikonturig, gespaltener Schaft, dar\u252 \'fcber Stange mit vier\-bl\u228 \'e4ttriger Blume, f\u252 \'fcnf Varianten: 1. sehr \u228 \'e4hnlich WZIS DE9090-PO-111975 (Xanten 1473); 2. sehr \u228 \'e4hnlich WZIS NL0360-PO-111982 (Geldern 1459/60); 3. \u228 \'e4hnlich WZIS DE4440-PO-112415 (Frank\-furt a. M. 1474); 4. sehr \u228 \'e4hnlich WZIS DE8100-PO-111555 (Speyer 1483); 5. \u228 \'e4hnlich WZIS DE8100-PO-111553 (K\u246 \'f6ln 1486); Trinkgef\u228 \'e4\u223 \'df, Krug mit Deckel, ein zweikonturiger Henkel, darauf einkon\-turiges Kreuz, zwei Varianten: 1. \u228 \'e4hnlich WZIS DE6075-PO-31379 (Siegen 1483); 2. sehr \u228 \'e4hnlich WZIS DE7800-PO-31370 (Zweibr\u252 \'fccken 1485/86); Doppelblatt 140/143 ohne erkennbares Wasser\-zeichen\~\~\u183 \'b7\~\~vereinzelt Reklamanten (z.B. 194\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 , 218\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 )\~\~\u183 \'b7\~\~173\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  \endash  176\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  und 195\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 /196\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  \endash  199\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 /200\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  jeweils auf dem Fu\u223 \'dfsteg, links bzw. rechts alte Blattz\u228 \'e4hlung innerhalb der Lagen: \plain \f1\i\lang1033\fs22 3\u176 \'b0\plain \f1\lang1033\fs22  \endash  \plain \f1\i\lang1033\fs22 6\u176 \'b0\plain \f1\lang1033\fs22 ; gr\u246 \'f6\u223 \'dftenteils be\-schnitten und dadurch verloren; moderne Bleistiftfoliierung\~\~\u183 \'b7\~\~Schriftraum: 18 \endash  20 x 12,5 \endash  14; Schriftraumbegrenzung meist blind vorgepr\u228 \'e4gt\~\~\u183 \'b7\~\~32 \endash  43 Zeilen\~\~\u183 \'b7\~\~Bastarda mit Schleifen von mehre\-ren, mindestens zwei H\u228 \'e4nden; vereinzelt Randbemerkungen von einer deutlich sp\u228 \'e4teren Hand\~\~\u183 \'b7\~\~\u220 \'dcber\-schriften in der Regel abgesetzt und einger\u252 \'fcckt\~\~\u183 \'b7\~\~rubriziert\~\~\u183 \'b7\~\~2-6zeilige rote Anfangsbuchstaben, Lombardtypus, gelegentlich mit Aussparungsornamentik\~\~\u183 \'b7\~\~2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  zum Textbeginn 10zeilige, 5\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22  5zeilige, sonst meist 8-9zeilige, zweifarbige Fleuronn\u233 \'e9e-Initialen, jeweils zu Beginn der ersten sechs B\u252 \'fccher (44\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 , 54\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 , 81\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 , 113\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 ): rot-blau gespaltener Buchstabenk\u246 \'f6rper mit Aussparungsornamentik vor Initialfeld aus rotem Knospenfleuronn\u233 \'e9e mit Perlen und Fadenwerk als Besatz; im Binnengrund z.T. strahlen\-f\u246 \'f6rmig oder spiralig angeordnetes Knospenfleuronn\u233 \'e9e, vereinzelt mit Palmetten und Gesichtern im Binnengrund (z.B. 5\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 , 113\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 ); 2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  au\u223 \'dferdem 5zeilige, 16\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  (Buch 2) 8zeilige Initiale mit rot-blau gespaltenem Buchstabenk\u246 \'f6rper.}

