plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Stuttgart, WLB, HB VIII 19}}\plain \f1\lang1033\fs26 , 178\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 . }

