\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 XXX\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs26  \endash  L\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs26  (Pseudo-){\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Gerardus Cremonensis}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Summa}}\plain \f1\lang1033\fs26  de modo medendi. (XXX\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Incipiunt capitula Summe magistri Gerardi de Dando Cartaticis\plain \f1\lang1033\fs26 <. (XXX\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs26  \endash  XXXI\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs26 ) Kapitelverzeichnis. (XXXI\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Incipit prologus Summe magistri Gyrardi\plain \f1\lang1033\fs26 <. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Cum omnis scientia ex fine et ex utilitate sua naturaliter sit appetenda}}\plain \f1\lang1033\fs26  ... (XXXI\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs26 ) Kapitel 1. >\plain \f1\i\lang1033\fs26 Quando corpus sit purgando\plain \f1\lang1033\fs26 <. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Consideremus ergo in primis, utrum corpus purgandum sit}}\plain \f1\lang1033\fs26  ... (L\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Quomodo conservande sunt medicine\plain \f1\lang1033\fs26 <. \plain \f1\i\lang1033\fs26 Collecte autem medicine conservantur hic modo\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 quem ad modum axingie\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 et unguenti invasis resteis\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 De laxativis medicinis hic sufficiant\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Explicit Summa magistri Giraldi\plain \f1\lang1033\fs26 . \endash  Die Verfasserschaft des Textes ist umstritten; er wird auch {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Gerardus (Giraldus) de Monte\-pessulano}}\plain \f1\lang1033\fs26  und {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Gerardus Bituricensis}}\plain \f1\lang1033\fs26  zugeschrieben; vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Thorndike/ Kibre, Sp. 327}}\plain \f1\lang1033\fs26 ; C.A.L.M.A. 4,3 (2013), S. 249 \endash  260 (C. Colomba), bes. S. 258 \endash  259, Nr. 83.}

