\pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs22 Streax, Katalog, 1589\~\~\u183 \'b7\~\~Bouxhon, Summa, 1667, Nr. L. 33\~\~\u183 \'b7\~\~Paquot, Catalogue, 1788, S. 145, Nr. 442\~\~\u183 \'b7\~\~Volk, H\u252 \'fcpsch, 1925, S. 207\~\~\u183 \'b7\~\~Kristeller, Iter, Bd. 6 (1992), S. 502\~\~\u183 \'b7\~\~Mortiaux-DeNo\u235 \'ebl, Fonds, 1991, S. 186 Nr. L.33\~\~\u183 \'b7\~\~Mortiaux-DeNo\u235 \'ebl/Guillaume, Fonds, 1997, S. 366, Nr. 64\~\~\u183 \'b7\~\~Falmagne/ Otis, Surviving Manuscripts, 2009, S. 198, Nr. 2515\~\~\u183 \'b7\~\~Xhayet, M\u233 \'e9decine, 2010\~\~\u183 \'b7\~\~Ana Isabel Mart\u237 \'edn Ferrei\-ra/ Alejandro Garc\u237 \'eda Gonz\u225 \'e1lez, La Tradici\u243 \'f3n manuscrita del Breviarium de Johannes de Sancto Paulo, in: Exemplaria Clasica. Journal of Classical Philology 14 (2010), S. 227 \endash  248, bes. S. 237 \endash  238\~\~\u183 \'b7\~\~Victoria Recio Mun\u7625 ?oz (Hrsg,), La Practica de Plateario, Florenz 2016 (Edizione nazionale dei testi mediolatini d'Italia, Edizione nazionale \u8222 \'84La scuola medica Salernitana\ldblquote , Bd. 40, Serie II, 18), S. 91.}

