\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 91\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26  \endash  100\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Tractatus}}\plain \f1\lang1033\fs26  de Chirurgia. (91\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Incipit Cyrurgia Galieni\plain \f1\lang1033\fs26 <. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Quamquam de iure ac proprietate huius vocabuli Cyrurgia tota practica sic posset merito nuncupari}}\plain \f1\lang1033\fs26  ... (91\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Ad rupturam cranei\plain \f1\lang1033\fs26 <. \plain \f1\i\lang1033\fs26 Ab eo die\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 quo ruptura fuerit\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 usque ad v. vel vii. diem vel quamdiu craneum consolidabitur\plain \f1\lang1033\fs26  ... (100\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 De descenso humori a capite in aures\plain \f1\lang1033\fs26 <. \plain \f1\i\lang1033\fs26 Si humorum aliquis a capite in aurem descendunt\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 Unum enim habent descensum et unum est eorum medicaminis\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Explicit Cirurgia\plain \f1\lang1033\fs26  >\plain \f1\i\lang1033\fs26 G\plain \f1\lang1033\fs26 .< \endash  Der Text wird in der vorlie\-genden Hs. {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Galenus}}\plain \f1\lang1033\fs26  zugeschrieben; er ist deutlich k\u252 \'fcrzer als die von Sudhoff (s.u.) nach zwei Bamberger Handschriften herausgegebene Version; vgl. Throndike/ Kibre 1963, Sp. 1161; Druck: Karl Sudhoff, Beitr\u228 \'e4ge zur Geschichte der Chirurgie im Mittelalter. Graphische und textliche Untersuchungen in mittelalterlichen Handschriften. Zweiter Teil, Leipzig 1918 (Studien zur Geschichte der Medizin, Heft 11 und 12), S. 108 \endash  140, Zeile 1087; vgl. ebenda S. 103 \endash  107; Parallel\u252 \'fcberlieferung: {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Kremsm\u252 \'fcnster, Stifts\-bibliothek, Cod. 70}}\plain \f1\lang1033\fs26 , 177\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 London, BL, Ms Royal 12 D. XII}}\plain \f1\lang1033\fs26 , 99\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Vatikan, BAV, Cod. Pal. lat. 1318}}\plain \f1\lang1033\fs26 , 63\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs26 . \endash  Unmittelbar anschlie\u223 \'dfend Nachtrag: }

