\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 100\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Augensegen}}\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 In nomine patris et filii et spiritus sancti\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 amen\plain \f1\lang1033\fs26 . {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Sanctus Kassianus habuit maculam variolam in oculo et oravit}}\plain \f1\i\lang1033\fs26  ... Sancte Kassiane ora pro famulo \plain \f1\lang1033\fs26 [Rasur]\plain \f1\i\lang1033\fs26  dei tui f\plain \f1\lang1033\fs26 ., \plain \f1\i\lang1033\fs26 ut recedat ab oculo omnis macula quecumque sic\plain \f1\lang1033\fs26 : \plain \f1\i\lang1033\fs26 Si est alba\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 deus eam aboleat\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 Christus vincit\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 Christus regnat\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 Christus imperat et spiritus sanctus famulum f. a dolore oculorum defendat\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Amen\plain \f1\lang1033\fs26 . \endash  100\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \endash  101\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  leer, 101\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  Besitzvermerk (s.o. Geschichte).}

