\uc1
\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 14\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \endash  20\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Calendarium, lat.-dt. mit zwei j\u252 \'fcdischen Festen}}\plain \f1\lang1033\fs26 . \endash  Der Kalender umfa\u223 \'dft f\u252 \'fcnf Spalten: 1. Spalte: goldene Zahl, 2. Spalte: Sonntagsbuchstaben; 3. Spalte: Tage des Monats (nach r\u246 \'f6mischer Datierung); 4. Spalte: Kalenden, Nonen, Iden; auf den Kopfstegen: 1. deutsche Bezeichnungen der Monate: \plain \f1\i\lang1033\fs26 Wolborn Hartma\u868 ?n\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 Hornung\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 Mercz\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 April\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 Mey\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 Bra\u868 ?chma\u868 ?n\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 Hauma\u868 ?n\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 Aust\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 Austimne\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 Herwestma\u868 ?n\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 Naherbestma\u868 ?n\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 Winterma\u868 ?n\plain \f1\lang1033\fs26 ; 2. Kalenderverse: (14\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Iani prima dies et septima fine timetur}}\plain \f1\lang1033\fs26  ... (20\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Dat duodena cohors septima inde decemque Decembris.\plain \f1\lang1033\fs26  \endash  Der Vers f\u252 \'fcr Februar fehlt; vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 9771, 10724, 4058}}\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Schaller/ K\u246 \'f6nsgen, Initia carminum, 1977, Nr. 7597}}\plain \f1\lang1033\fs26 ; Druck: Henning, Versus, 1955, S. 83; die gleichen Verse auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 1020}}\plain \f1\lang1033\fs26 , 9\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ; vor allem auf den Fu\u223 \'dfstegen, im Verlauf aber auch auf den Seitenstegen, dann meist um 90\u176 \'b0 gedreht zum urspr\u252 \'fcnglichen Schriftspiegel zahlreiche Erl\u228 \'e4uterungen und Erkl\u228 \'e4rungen, u.a. auch zu den jeweiligen Bibellesungen; z.B. (14\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Post festum stelle}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 , }}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 que sit nova Luna}}\plain \f1\lang1033\fs26\chcbpat17 , {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 require}}\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Post bis quinque dies ibi Septuagesima fiet\plain \f1\lang1033\fs26 ; (15\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Post Agathe festum videas ubi Luna secunda\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Prima die Solis ibi Quadragesime fiet\plain \f1\lang1033\fs26 ; (15\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Post Martis Nonas ubi sit nova Luna requiras\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Que post quam simul septima Pasce patebit.\plain \f1\lang1033\fs26  \endash  Vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge Nr. 14302}}\plain \f1\lang1033\fs26 ; ungew\u246 \'f6hnlich: Es werden zwei j\u252 \'fcdische Feste verzeichnet: 18\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  zum 15.09. \plain \f1\i\lang1033\fs26 Festum scenophegie vel tabernaculorum\plain \f1\lang1033\fs26  i.e. Laubh\u252 \'fcttenfest; 20\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  zum 05.12. \plain \f1\i\lang1033\fs26 Festum enceniorum\plain \f1\lang1033\fs26  i.e. Chanukka (s.o. Geschichte). }

