\pard\fi0\li0\qj\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs22 Knaus, Herkunft, 1958/1961 (1992), S. 47 \endash  49\~\~\u183 \'b7\~\~Deighton, Bibliothek, 1986, bes. S. 278, Nr. 15\~\~\u183 \'b7\~\~Beckers, Handschriften, 1990, bes. S. 76, Nr. 60.}

