\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 80\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  80\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  Epigramma ecclesiae s. Albani, lat. (80\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Aepigramma hic\plain \f1\lang1033\fs26  (?) \plain \f1\i\lang1033\fs26 habentur sculpta in lapidibus apud s. Albanum\plain \f1\lang1033\fs26 <. 1. >\plain \f1\i\lang1033\fs26 Epigramma ecclesie s. Albani\plain \f1\lang1033\fs26 <. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Antistes humilis Rycholff hanc condidit aram}}\plain \f1\i\lang1033\fs26  \plain \f1\lang1033\fs26 ...\plain \f1\i\lang1033\fs26 ;\plain \f1\lang1033\fs26  2. >\plain \f1\i\lang1033\fs26 Aliud\plain \f1\lang1033\fs26 . {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Ecclesia hec est consecrata in honore sancti salvatoris}}\plain \f1\i\lang1033\fs26  domini nostri Jesu Christi ...;\plain \f1\lang1033\fs26  3. >\plain \f1\i\lang1033\fs26 Aliud insculptum marmorea albo\plain \f1\lang1033\fs26 <. {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Fastradana pia Carolo coniunx vocitata}}\plain \f1\lang1033\fs26  ...; 4. >\plain \f1\i\lang1033\fs26 Aliud\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Epigramma regine Fastradane beatissime \plain \f1\lang1033\fs26 (?) \plain \f1\i\lang1033\fs26 uxoris Karoli Magni imperatoris, que obiit Franckfordie et ducta in monte s. Albani indigni\plain \f1\lang1033\fs26  (?)<. {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Inclita Fastradane regine hic membra quiescit}}\plain \f1\lang1033\fs26  ...\~; (80\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) 5. >\plain \f1\i\lang1033\fs26 Aliud in Ambitu\plain \f1\lang1033\fs26 <. {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Postquam primus homo Paradisi gaudia liquit}}\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 qui clauditur isto nomine Megingor fonte sacrante pio\plain \f1\lang1033\fs26  ... \plain \f2\i\lang1024\fs26 ante diem magnum evat\u367 \'f9et tum\u367 \'f9lum\plain \f1\lang1033\fs26 . \endash  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Inschriften}}\plain \f1\lang1033\fs26  aus dem Kloster {\field{\*\fldinst HYPERLINK "hida://bezsoz[0].4600/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 St. Alban zu Mainz}}\plain \f1\lang1033\fs26 ; Druck: Fritz Viktor Arens (Bearb.), Die Inschriften der Stadt Mainz von fr\u252 \'fchmittelalterlicher Zeit bis 1650, Stuttgart 1958 (Die deutschen Inschriften, Heidelberger Reihe, Bd. 2), S. 346, Nr. 649; S. 345, Nr. 648; S. 1, Nr. 1; S. 343, Nr. 2; S. 344, Nr. 11; vgl. K\u246 \'f6nig, Quellenkritik, 1878 (s. Lit.), S. 74. }

