\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 206\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  207\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Jakob Wimpfeling}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Widmungsbrief}}\plain \f1\lang1033\fs26  zur Querulosa Excusatio an {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Philipp von Daun und Oberstein}}\plain \f1\lang1033\fs26 . (206\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) >\plain \f2\i\lang1024\fs26 Generoso clarissimoque domino Philippo de D\u367 \'f9no et L\plain \f1\i\lang1033\fs26 apide superiori nobilissime Argentinensis Aecclesie prepostio\plain \f1\lang1033\fs26 : \plain \f2\i\lang1024\fs26 domino s\u367 \'f9o observandissimo\plain \f1\lang1033\fs26 <. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Non possum te clarissime domine preposite non ex intimis medullis colere}}\plain \f1\lang1033\fs26  ... (207\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 quamvis interim mihi solatio non mediocri futura sint magna hec magni theologi verba\plain \f1\lang1033\fs26 : \plain \f1\i\lang1033\fs26 Abel fieri non potest quem Cayn malicia non exercet\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Vale denuo\plain \f1\lang1033\fs26 . \endash  Druck: Dieter Mertens/ Otto Herding (Hrsg.), Jakob Wimpfeling. Briefwechsel, 2 Bde., M\u252 \'fcnchen 1990 (Jacobi Wimpfeling Opera Selecata, Bd. 3), Bd. 2, S. 615 \endash  617; Nr. 237; vgl. K\u246 \'f6nig, Quellenkritik, 1878 (s. Lit.), S. 74 \endash  75. }

