\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  1\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  Fragment eines {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Tonars}}\plain \f1\lang1033\fs26 . (1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Da mercedem\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Evovae\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Ante me\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Syon renovaberis \plain \f1\lang1033\fs26 ...\plain \f1\i\lang1033\fs26  \plain \f1\lang1033\fs26 >\plain \f1\i\lang1033\fs26 Quinti Toni\plain \f1\lang1033\fs26 <. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Quinque prudentes interaverunt ad nuptias}}\plain \f1\i\lang1033\fs26  ...\plain \f1\lang1033\fs26  (1\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Sexti Toni Antiphone\plain \f1\lang1033\fs26 <. \plain \f1\i\lang1033\fs26 Sexta hora sedit super puteum\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 Reges Tharsis quia manducat Pascha enim panis\plain \f1\lang1033\fs26 . \endash  Umfa\u223 \'dft die Bereiche der quarti toni (Schlu\u223 \'df), quinti toni und sexti toni (Anfang); die Initien der Antiphonen jeweils nur mit einem oder zwei Worten wieder\-gegeben; die Merkverse aus (s.o.) Berno Augiensis, De consona tonorum diverstitate; vgl. PL, Bd. 142, Sp. 1156 \endash  1157; enthalten sind (in der Reihenfolge der Handschrift), u.a.: {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 CAO Nr. 2087, 1436, 4970, 4045, 3881, 5040, 2865, 3229, 1197, 1717, 2285, 2177, 4155, 1120, 6320}}\plain \f1\lang1033\fs26  (\plain \f1\i\lang1033\fs26 quarti toni\plain \f1\lang1033\fs26 ); {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Nr. 4543, 2817, 4982, 2523, 4156, 2520, 5506, 4305, 3562, 2631, 3287, 2811, 2751, 5361, 2373, 3634, 8060, 1674}}\plain \f1\lang1033\fs26  (\plain \f1\i\lang1033\fs26 quinti toni\plain \f1\lang1033\fs26 ); {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Nr. 3877, 3985, 4058, 3104, 3828, 3938, 2459, 6128, 8165, 3119, 4594}}\plain \f1\lang1033\fs26  (\plain \f1\i\lang1033\fs26 sexti toni\plain \f1\lang1033\fs26 ); vgl. Walther Lipphardt (Hrsg.), Der karolingische Tonar von Metz, M\u252 \'fcnster 1965 (Litur\-giewissenschaftliche Quellen und Forschungen Heft 43); Clyde W. Brockett (Hrsg.), Anonymi. De modorum formulis et tonarius, Neuhausen 1997 (Corpus scriptorum de Musica, Bd. 37).}

