\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 204\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  207\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Johannes Simonis de Zelandia}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Speculum planetarum}}\plain \f1\lang1033\fs26 . (204\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Speculum planetarum\plain \f1\lang1033\fs26 <. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 In isto instrumento velud}}\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 (!) }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 in speculo omnium planetarum}}\plain \f1\i\lang1033\fs26  \plain \f2\i\lang1033\fs26 \u9738 ?\plain \f1\i\lang1033\fs26  et \plain \f2\i\lang1033\fs26 \u9739 ? \plain \f2\lang1033\fs26 [\plain \f1\lang1033\fs26 capitis et caude]\plain \f1\i\lang1033\fs26  traconis \plain \f1\lang1033\fs26 (!)\plain \f1\i\lang1033\fs26  vera loca in nona spera clarissime intuentur\plain \f1\lang1033\fs26  ... (207\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 in sua precisione perpetua hoc modo permanere\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  de quo laudetur veritas eterna per infinita secula seculorum\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Amen\plain \f1\lang1033\fs26 . >\plain \f1\i\lang1033\fs26 Finit\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 canon novi instrumenti seu speculi planetarum magistri Johannis Simonis de Zelandia etc. feci anno 1417 completis in Vienna, in Italia ducalis domini subaudie etc\plain \f1\lang1033\fs26 . \endash  Vgl. Olaf Pedersen, Two Medieval Equatoria, in: Actes du XI\plain \f1\super\lang1033\fs24 e\plain \f1\lang1033\fs26  congr\u232 \'e8s internationale d\rquote histoire des sciences, Breslau 1968 (Collection des travaux de l\lquote Acad\u233 \'e9mie internationale d\rquote Histoire des Sciences, Bd. 17,1), Bd. 3, S. 68 \endash  72; Paul Lehmann, Skandinaviens Anteil an der lateinischen Literatur des Mittelalters. 1. St\u252 \'fcck, in: Sitzungsberichte der Bayerischen Akademie der Wissenschaften, Philosophisch-Historische Klasse 1936,2, bes. S. 55 (Reprint in: ders., Erforschung des Mittelalters, Bd. 5, Stuttgart 1962, S. 275 \endash  429, bes. S. 315); {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Thorndike/ Kibre 1963, Sp. 685}}\plain \f1\lang1033\fs26 ; Bischoff, Katalog, 1966 (s. Lit.), S. 134 \endash  135. }

