\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 231\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \endash  235\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Johannes de Gmunden}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 De compositione cylindri}}\plain \f1\lang1033\fs26 . (231\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) Rubrik: \plain \f1\i\lang1033\fs26 Kylindrium\plain \f1\lang1033\fs26 . Text: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Tractatus Kilinderi duas habet partes}}\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 quarum prima est de composicione\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 secunda de usu ipsius\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Prima pars habet octo capitula\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 Est enim quoddam horologio, quoniam quidem vocatur Kilindrus\plain \f1\lang1033\fs26  ... (235\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Altitudine rei\plain \f1\lang1033\fs26 <. \plain \f1\i\lang1033\fs26 Si vis scire altitudine rei implano erecte\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 scias primo puncta umbre verse secundum doctrinam secundi capituli\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 quos ostendit tibi altitudine rei\plain \f1\lang1033\fs26 . >\plain \f1\i\lang1033\fs26 Editus\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 a magistro Johanne Gm\u252 \'fcnd finitur iste tractatus\plain \f1\lang1033\fs26 . \endash  Vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Thorndike/ Kibre 1963, Sp. 509, 1580}}\plain \f1\lang1033\fs26 ; zu {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Johannes de Gmunden}}\plain \f1\lang1033\fs26  s.o. 116\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ; Klug, Johannes von Gmunden, 1943 (s.o. 116\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ), S. 52 \endash  54; Bischoff, Katalog, 1966 (s. Lit.), S. 135; Chlench, Johannes von Gmunden \endash  Handschriftenverzeichnis, 2006 (s. 116\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ), S. 222 \endash  223. }

