\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 244\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  245\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Quadrans vetus}}\plain \f1\lang1033\fs26 , Exzerpte. (244\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) Rubrik: \plain \f1\i\lang1033\fs26 De declinacione Solis post quadrantem\plain \f1\lang1033\fs26 . Text: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Si vis scire declinacionem Solis}}\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  id est que sit distancia eius ab equali per cursorem\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 Si vis scire latitudinem regionis\plain \f1\lang1033\fs26  ... Rubrik: \plain \f1\i\lang1033\fs26 Ad mensurandum cum virga\plain \f1\lang1033\fs26 . Text: \plain \f1\i\lang1033\fs26 Si non habes quadrante et velis mensurare altitudine rei\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  accipe unam virgam et erigatur super planum\plain \f1\lang1033\fs26  ... (245\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Dictum est de mensuranda rerum altitudine et planicie\plain \f1\lang1033\fs26 : \plain \f1\i\lang1033\fs26 Nunc de puteorum profunditate et vasorum capacitate dicamus\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 et productum dabit capacitatem\plain \f1\lang1033\fs26 . \endash  Enthalten sind die Kapitel 39 \endash  43, 60 \endash  87 des Traktats; Druck: Tannery, Le Trait\u233 \'e9, 1897, S. 561 \endash  632, bes. S. 612 \endash  632; Hahn, Mensuration, 1982, S. 51 \endash  57, 83 \endash  113; zur Verfasserfrage vgl. ebenda S. XV \endash  XXIII; Thomson, Writings, 1940; S. 261, Nr. 53; Thorndike, Quadrans Vetus, 1947, S. 150 \endash  153; {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Thorndike/ Kibre 1963, Sp. 585}}\plain \f1\lang1033\fs26 ; Glorieux, Facult\u233 \'e9, Nr. 399b.); Weijers, Travail, 1994ff., Bd. 25,8 (2010), S. 154 \endash  156, unter: {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Robertus Anglicus}}\plain \f1\lang1033\fs26  (in Montepessulano magister) [vers 1270], bes. S. 155 \endash  156; Bischoff, Katalog, 1966 (s. Lit.), S. 135; Teile des Textes auch 300\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  (s.u.); sowie in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 739}}\plain \f1\lang1033\fs26 , 246\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26  und {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 2661}}\plain \f1\lang1033\fs26 , 135\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 . }

