\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 254\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \endash  256\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f2\fs26\chcbpat17 Mu\u7717 ?ammad Ibn-\u486 ?\u257 \'e2bir Batt\u257 \'e2n\u299 \'ee}}\plain \f2\fs26  \plain \f1\lang1033\fs26 (Bethen), {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Centiloquium}}\plain \f1\lang1033\fs26  (Translatio {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Petri de Abano}}\plain \f1\lang1033\fs26 ). (254\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Incipit liber Beten\plain \f1\lang1033\fs26 <. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Nunc inchoabo librum de consuetudinibus in iudiciis stellarum}}\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Scias\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 quod planete\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  quando sunt retrogradi\plain \f1\lang1033\fs26  ... (256\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Veneris dies bona in omni opere precipue\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Expliciunt Centiloquia Beten\plain \f1\lang1033\fs26 . \endash  Vgl. Glorieux, Facult\u233 \'e9, Nr. 335k.); Carmody, Arabic Sciences, 1956, S. 74 \endash  75; {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Thorndike/ Kibre 1963, Sp. 965}}\plain \f1\lang1033\fs26 ; Druck: {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 GW M36394}}\plain \f1\lang1033\fs26 , fol. 119\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  120\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ; Bischoff, Katalog, 1966 (s. Lit.), S. 135. }

