\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 266\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  268\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  (Pseudo-){\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Apollonius Tyanensis}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Liber imaginum Lunae}}\plain \f1\lang1033\fs26 . (266\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Incipit liber magnus et ymaginum ab Hermete}}\plain \f1\lang1033\fs26\chcbpat17 , {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 quid Latine prestigium Mercurii dicitur}}\plain \f1\i\lang1033\fs26  a lingua elevuens\plain \f1\lang1033\fs26  (?) \plain \f1\i\lang1033\fs26 in linguam Hebrayiam translatus\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Cum enim ille sapientius indagator suanitatis\plain \f1\lang1033\fs26  ... Rubrik: \plain \f1\i\lang1033\fs26 Hic incipit sensus libri\plain \f1\lang1033\fs26 . Text: \plain \f1\i\lang1033\fs26 In nomine divini misericordissimi soli deo honor et gloria hic incipit liber Lune\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 cuius circulus inest habitacionibus terre\plain \f1\lang1033\fs26  ... (266\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) Rubrik: \plain \f1\i\lang1033\fs26 Hec Hermes\plain \f1\lang1033\fs26 . Text: \plain \f1\i\lang1033\fs26 Dixit magister Hermes\plain \f1\lang1033\fs26 : \plain \f1\i\lang1033\fs26 Probavi omnes libros prophetarum neque in diversiorem nec perfeccionem isto teste omnipotenti deo\plain \f1\lang1033\fs26  ... Rubrik: \plain \f1\i\lang1033\fs26 Hec est scientia magistri Balemith\plain \f1\lang1033\fs26 . Text: \plain \f1\i\lang1033\fs26 Dixit magister Balemith\plain \f1\lang1033\fs26 : \plain \f1\i\lang1033\fs26 Summus et percissius per planetarum secundum magistrum suum Hermetem\plain \f1\lang1033\fs26  ... (267\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) Rubrik: \plain \f1\i\lang1033\fs26 Suffimigaciones Hermetis\plain \f1\lang1033\fs26 . Text: \plain \f1\i\lang1033\fs26 Hec sunt suffumigaciones\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  ut dicit Hermes\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 quius suffumigantur omnes ymagines boni\plain \f1\lang1033\fs26  ... Rubrik: \plain \f1\i\lang1033\fs26 Suffimigaciones mali\plain \f1\lang1033\fs26 . (268\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Hec vero sunt suffumigaciones\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  quius effumigantur imagines mali\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 cereantur et misteriis habeantur\plain \f1\lang1033\fs26 . Rubrik: \plain \f1\i\lang1033\fs26 Nomina angelorum serviencia ymaginibus Lune\plain \f1\lang1033\fs26 . Text: \plain \f1\i\lang1033\fs26 Nomina vero angelorum serviencia ymaginibus Lune et circulus eius\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  per quem exeret utriusque ymaginibus Lune hora\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 Hemyn\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 Mandesinlyn\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 Teby\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 Aledio\plain \f1\lang1033\fs26 . \endash  Nach Lucentini/ Perrone Compagni, codici di Ermete, 2001, Nr. 30, S. 70 \endash  73, Recensio a des Textes; Druck (recensio c): Lucentini, L\rquote ermetismo magico, 2000, S. 409 \endash  450, bes. S. 442 \endash  444; vgl. Thorndike, Images, 1947, S. 238, Nr. 7; Carmody, Arabic Sciences, S. 63 \endash  64, Nr. 21a; Gilly, Collezione, 1999, S. 238; Recensio c auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 1410}}\plain \f1\lang1033\fs26 , 35\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  und 44\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 .}

