\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 300\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  305\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Quadrans vetus}}\plain \f1\lang1033\fs26 , Exzerpte. (300\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Capitulum primum de mensura astrolabii\plain \f1\lang1033\fs26 <. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Si altitudine alicuius rei accessibilis et inplano constitute}}\plain \f1\i\lang1033\fs26  per eius umbram scire volueris\plain \f1\lang1033\fs26  ... (305\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Cum volueris mensurare longitudinem fenestri in altitudine terris respice\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 et remanet altitudo fenestri\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Exemplum\plain \f1\lang1033\fs26 . Anschlie\u223 \'dfend Zeichnung (s.o.) sowie nachgetragene Tabelle \plain \f1\i\lang1033\fs26 Kilindrum ad Sultzpach\plain \f1\lang1033\fs26 . \endash  Enthalten sind die Kapitel 49 \endash  87; Teile des gleichen Textes auch 244\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  (s.o.); zu Drucken, Sekund\u228 \'e4rliteratur und Parallel\u252 \'fcberlieferung s. dort; vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Thorndike/ Kibre 1963, Sp. 1441}}\plain \f1\lang1033\fs26 ; Bischoff, Katalog, 1966 (s. Lit.), S. 136. \endash  306\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  leer.}

