\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 26\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  26\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  (Pseudo-){\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Arnoldus de Villa Nova}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Flos Florum}}\plain \f1\lang1033\fs26 , Exzerpte. (26\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Intellige hic: Accipe precii libram}}\plain \f1\i\lang1033\fs26  i et sit limatura munda et commisce cum xl libras \plain \f1\lang1033\fs26 ... (26\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 ut in eis multiplicetur multitudine magna\plain \f1\lang1033\fs26 . \endash  \u196 \'c4hnliche Exzerpte, dort jedoch umfangreicher und aus weiteren Zusammenh\u228 \'e4ngen, in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 2226}}\plain \f1\lang1033\fs26 , 35\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 , vgl. Smits van Waesberghe, Aribonis De Musica, 1951 (s. Lit.), S. iv; Duck: Mangetus, Bibliotheca, 1702, S. 681. Anschlie\u223 \'dfend Notizen, Nachtr\u228 \'e4ge des 14. Jhs., u.a. \plain \f1\i\lang1033\fs26 Modus purificandi Solem et Lunam\plain \f1\lang1033\fs26 .}

