\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 67\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 De fornacem, quae perpetuo ardet}}\plain \f1\lang1033\fs26 . {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Hec descriptio demonstrat, qualiter fiat fornax}}\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 que perpetuo ardet et hec adinvenet philosophi \plain \f1\lang1033\fs26 ... \plain \f1\i\lang1033\fs26 quidam alius lapis\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 qui dicitur larbre\plain \f1\lang1033\fs26  (?) \plain \f1\i\lang1033\fs26 et est rubei coloris\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 qui si forcetur\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  attrahit paleas et est gummi\plain \f1\lang1033\fs26  (?) \plain \f1\i\lang1033\fs26 similiter\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 de quo tantum est in hac confectione necessum quantum de Gagate\plain \f1\lang1033\fs26 . \endash  Text mit Erw\u228 \'e4hnung L\u252 \'fcttichs (s.o. Geschichte); vgl. Smits van Waesberghe, Aribonis De Musica, 1951 (s. Lit.), S. iv; Pesce, Guido d\rquote Arezzo, 1999 (s. Lit.), S. 61.}

