\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 87\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \endash  92\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Guido von Arezzo}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Regulae rhythmicae}}\plain \f1\lang1033\fs26 . (87\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Gliscunt corda meis hominum mollita camenis}}\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 Musicorum et cantorum magna est distantia\plain \f1\lang1033\fs26  ... (92\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 refert alterius cum suscipit altera vires\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 unde duo signum variant loca cuius ad ipsum\plain \f1\lang1033\fs26 . \endash  Die ersten f\u252 \'fcnf Verse ergeben erneut das Akrostichon \plain \f1\i\lang1033\fs26 Guido\plain \f1\lang1033\fs26 ; vgl. Roth, musikalischer Codex, 1897 (s. Lit.), S. 488; {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 7219}}\plain \f1\lang1033\fs26 ; Smits van Waesberghe, Aribonis De Musica, 1951 (s. Lit.), S. iv; ders., Tres tractatuli Guidonis, 1975 (s. 93\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ), S. 30; ders./ Eduard Vetter (Hrsg.), Guidonis Aretini "Regulae rhythmicae", Buren 1985 (Divitiae musicae artis, Bd. A/IV), S. 51 \endash  52, Sigle D; Huglo/ Meyer, Theory, 1986 (s. Lit.), S. 39; Druck (nach dieser Hs.) Roth, Schriften, 1888 \endash  1890 (s. Lit.); PL, Bd. 141, Sp. 406 \endash  414; Gerbert, Scriptores (s. 71\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ), Bd. 2, S. 25 \endash  34; Smits van Waesberghe/ Vetter, "Regulae rhythmicae", 1985 (s.o.), S. 93 \endash  133; vgl. McCarthy, Music, 2009 (s. Lit.), S. 200 \endash  203; Pesce, Guido d\rquote Arezzo, 1999 (s. Lit.), S. 61 (Sigle D) u.\u246 \'f6.; Druck: ebenda, S. 328 \endash  402. }

