\pard\fi0\li0\qj\ri0\sb600\sa0\itap0 \plain \f1\lang1033\fs26 144\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  145\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 , 146\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Johannes Ianuensis}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Catholicon}}\plain \f1\lang1033\fs26 , Exzerpte. (144\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Ex libro catholicon fratris Johannis Ianunensis\plain \f1\lang1033\fs26 <. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Annus, anni, masculini generis}}\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 Menses a mane\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 quod est Lune dicitur hic\plain \f1\lang1033\fs26  ... (145\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Sol a solus dicitur\plain \f1\lang1033\fs26  ... (146\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Zodiacus zodia grece, latine animalia vel signa\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 cum Sole elevat eos et Mars incendendo corrumpit eosdem et ita fit aer venenosus\plain \f1\lang1033\fs26 . \endash  Exzerpte zu astronomisch-astrologischen und komputistischen Themen, wie Jahr, Monat, Woche, Sonne, Mond, Planeten und Tierkreiszeichen; Druck: {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 GW 03182 \endash  03205}}\plain \f1\lang1033\fs26 ; vgl. Powitz, Catholicon \endash  Sicht, 1988, S. 125 \endash  137, bes. S. 132; ders., Catholicon \endash  Esquisse, 1996, S. 299 \endash  336, bes. S. 324, Zusammenstellung der handschriftlichen \u220 \'dcberlieferung auf S. 322 \endash  336; au\u223 \'dferdem Marigo, Derivationes, 1936, S. 31 \endash  40; Grubm\u252 \'fcller, Vocabularius Ex quo, 1967, S. 26, Anm. 3; vgl. Smits van Waesberghe, Aribonis De Musica, 1951 (s. Lit.), S. v; Huglo/ Meyer, Theory, 1986 (s. Lit.), S. 40; Pesce, Guido d\rquote Arezzo, 1999 (s. Lit.), S. 62; Text in Ausz\u252 \'fcgen auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 317}}\plain \f1\lang1033\fs26 , 76\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26 ; vgl. DA ULB Kat. 5,2; {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 729}}\plain \f1\lang1033\fs26 , 1\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26 , und in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 739}}\plain \f1\lang1033\fs26 , 152\plain \f1\super\lang1033\fs24 vab\plain \f1\lang1033\fs26 . Dazwischen:
\par \pard\fi0\li0\qj\ri0\sb0\sa360\itap0 146\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Carmen}}\plain \f1\lang1033\fs26  \u8218 \'82Vado mori\lquote . >\plain \f1\i\lang1033\fs26 Hos versus composuit frater Lambertus dictus Boreis prior ordinis predicatorum Leodiensium in extremis\plain \f1\lang1033\fs26 <. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Vado mori, mori nature cedo, recedo}}\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 Hoc leve sive breve desero\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Vado mori\plain \f1\lang1033\fs26 . \endash  Der Text wird hier \plain \f1\i\lang1033\fs26 Lambertus dictus Boreis\plain \f1\lang1033\fs26  i.e. {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Lambertus de Leodio}}\plain \f1\lang1033\fs26  (Lambert Fare) zugeschrieben; zu ihm vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Kaeppeli, Scriptores, Bd. 3, S. 59 \endash  60, bes. Nr. 2793}}\plain \f1\lang1033\fs26 ; v\plain \f2\lang1024\fs26 gl. Storck, \u8218 \'82Vado mori\lquote ,1910, S. 422 \endash  428, bes. S. 426 \endash  428; Rudolf, Ars moriendi, 1957, S. 49 \endash  51, 122 \endash  123; Zato\u269 \'e8il, Lateinische Texte, 1977, S. 7 \endash  21; {\field{\*\fldinst HYPERLINK "hida://bezlit[2].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 4962}}\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://bezlit[3].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Proverbia, Nr. II/1, 4962}}\plain \f1\lang1033\fs26 ; Druck (nach dieser Handschrift): Roth, Literatur, 1891, S. 43 \endash  44; {\field{\*\fldinst HYPERLINK "hida://bezlit[4].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 AH, Bd. 36, S. 351 \endash  352}}\plain \f1\lang1033\fs26 ; vgl. Pesce, Guido d\rquote Arezzo, 1999 (s. Lit.), S. 62; Text auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 815}}\plain \f1\lang1033\fs26 , hinterer Spiegel; {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 2225}}\plain \f1\lang1033\fs26 , 59\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 . }

