\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 167\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  169\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 De ratione proportione et divisione semitonii}}\plain \f1\lang1033\fs26 . (167\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 De ratione proportione\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 et divisione semitonii\plain \f1\lang1033\fs26  (?)<. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Cum diatessarum consonancia constet sesquitercia proportione}}\plain \f1\lang1033\fs26  ... (169\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Proportio alterius ad alterum est cum minor numerus superatur a maiori\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 tercia sui parte\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 et tercie partis centesima quarta\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Explicit\plain \f1\lang1033\fs26 . \endash  Vgl. Roth, musikalischer Codex, 1897 (s. Lit.), S. 489; {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Thorndike/ Kibre 1963, Sp. 292}}\plain \f1\lang1033\fs26 ; Smits van Waesberghe, Aribonis De Musica, 1951 (s. Lit.), S. v; Huglo/ Meyer, Theory, 1986 (s. Lit.), S. 40; Alison M. Peden, De semitonio: Some Medieval Exercises in Arithmetic, in: Studi medievali, 3. Serie, 35,1 (1994), S. 367 \endash  403; Druck: ebenda, S. 391 \endash  397; vgl. ferner Pesce, Guido d\rquote Arezzo, 1999 (s. Lit.), S. 62; Stoppachi, Clavis Gerbertiana, 2016, S. 106, Nr. 24. }

