\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  47\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Gerardus de Vliederhoven}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Cordiale de Quattuor Novissimis}}\plain \f1\lang1033\fs26  cum multis exemplis pulcherrimis. (1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) Rubrik: \plain \f1\i\lang1033\fs26 In nomine\plain \f1\lang1033\fs26  <domini>. \plain \f1\i\lang1033\fs26 Amen\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Incipit Libellus\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 qui intitulatur Cordiale scripturarum sive Quattuor Novissima\plain \f1\lang1033\fs26 . Text: (M)\plain \f1\i\lang1033\fs26 emorare novissima tua\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 \u8230 \'85\plain \f1\lang1033\fs26  (Sir 7,40). {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Sicut dicit Augustinus in libro suarum meditacionum}}\plain \f1\lang1033\fs26  \u8230 \'85 (47\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 saperent et intelligent\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 ac\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 novissima providerent. Amen\plain \f1\lang1033\fs26 . \endash  Druck: {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 GW 07469 \endash  07541, 0748810N, 0748910N, 0750010N, 7 Sp.50a, 7 Sp.52a\endash c}}\plain \f1\lang1033\fs26 ; Welter, L\rquote exemplum, 1927, S. 427 \endash  429; Bloomfield, Nr. 498; Schneyer, Wegweiser, S. 366 \endash  367; {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Bloomfield/ Guyot, Incipits, Nr. 3057}}\plain \f1\lang1033\fs26 ; zur Verfasserschaft des Gerardus de Vliederhoven (\u8224 \'86vor 1402) vgl. Madre, Nikolaus von Dinkelsb\u252 \'fchl, 1965, S. 329; VL(2), Bd. 2, 1980, Sp. 1217 \endash  1221 (Richard Byrn), mit weiterer Literatur; zur \u220 \'dcberlieferung vgl. Dusch, De veer utersten, 1975 (s. Lit.), S. 46*, Nr. *54; H.\plain \f1\lang1033\fs24  \plain \f1\lang1033\fs26 Beckers, Zur mittelniederdeutschen \u220 \'dcberlieferung des Cordiale de quatuor novissimis Gerhards van Vliederhoven, in: Korrespondenzblatt des Vereins f\u252 \'fcr niederdeutsche Sprachforschung 86, 1979, S. 64 \endash  66; Newhauser/ Bejczy, Bloomfield, 2008, Nr. 3057; Text auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 2667}}\plain \f1\lang1033\fs26 , 180\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  (nddt.); vgl. DA LuHB Kat. 6, S. 80; {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 685}}\plain \f1\lang1033\fs26 , 155\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ; vgl. DA LuHB Kat. 4, S. 166; {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 767}}\plain \f1\lang1033\fs26 , 45\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 796}}\plain \f1\lang1033\fs26 , 1\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 3105}}\plain \f1\lang1033\fs26 , 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ; vgl. DA LuHB Kat. 5,1, S. 96, 119, 165); {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 1225}}\plain \f1\lang1033\fs26 , 216\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 397}}\plain \f1\lang1033\fs26 , 95\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ; DA ULB Kat. 5,2.}

