\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 81\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Versus}}\plain \f1\lang1033\fs26  de quattuor temperamentis. Rubrik: \plain \f1\i\lang1033\fs26 Octo versus de quatuor complexionibus\plain \f1\lang1033\fs26 . Text: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Sanguineus. Largus amans hylaris ridens}}\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 luteique coloris\plain \f1\lang1033\fs26 . \endash  Vgl. Sudhoff, Sanitatis Salernitanum (Schlu\u223 \'df), 1920, S. 149 \endash  180, bes. S. 152; {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 17266, 8114, 9549, 10131}}\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Thorndike/ Kibre, Sp. 1374}}\plain \f1\lang1033\fs26 ; Thorndike, De complexionibus, 1958, S. 398 \endash  408, bes. S. 399; Goehl/ Mayer/ Staub, Was tun, 2000 (s. Lit.), S. 129; Xhayet, M\u233 \'e9decine, 2010, S. 56, 58, 184; Druck: {\field{\*\fldinst HYPERLINK "hida://bezlit[2].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 GW M26340}}\plain \f1\lang1033\fs26 , 15\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ; Verse auch in in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 329}}\plain \f1\lang1033\fs26 , 103\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 739}}\plain \f1\lang1033\fs26 , 98\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 1415}}\plain \f1\lang1033\fs26 , 29\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 1571}}\plain \f1\lang1033\fs26 , 23\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26 . }

