\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 100\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 De Peccato}}\plain \f1\lang1033\fs26 . (100\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) Rubrik: \plain \f1\i\lang1033\fs26 Diffinitio peccati\plain \f1\lang1033\fs26 . Text: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Nota peccatum secundum beatum Augustinum est spreto incommutabili bono}}\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 bono commutabili adhere vel peccatum est omnem dictum vel factum cel concupitum\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 Et est sciendum\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 quod peccatum in spiritum sanctum commissum reservata de dictis specibus quinta species non potest remitti\plain \f1\lang1033\fs26 . Rubrik: \plain \f1\i\lang1033\fs26 Forma absolutinis\plain \f1\lang1033\fs26 . Text: {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Deus per suam magnam misericordiam te absolvat}}\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 quam fungor in nomine patris et filii et spiritu sancti\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Amen\plain \f1\lang1033\fs26 . }

