\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 100\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Abla\u223 \'dfgebet}}\plain \f1\lang1033\fs26  zur Eucharistie. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Si quis subscriptam orationem in presencia venerabilis sacramenti dixit}}\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 acquirit l\plain \f1\lang1033\fs26  (?) \plain \f1\i\lang1033\fs26 xxx dies indulgencie relaxate per papam Johannem vicesimum secundum\plain \f1\lang1033\fs26 : \plain \f1\i\lang1033\fs26 Anima Christi sanctifica me\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 corpus Christi salva me\plain \f1\lang1033\fs26 , ... \plain \f1\i\lang1033\fs26 ut cum angelis tuis laudem te in secula seculorum amen\plain \f1\lang1033\fs26 . \endash  Vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Chevalier, Repertorium, Nr. 1090}}\plain \f1\lang1033\fs26 ; Leroquais, Les livres d'heures. Manuscrits, Bd. 1, S. 40, 47, 83 u.\u246 \'f6.; Bd. 2, S. 25; Leroquias, Breviaires, Bd. 3, S. 26; Bd. 4, S. 312, 318; Leroquais, Psaultiers, Bd. 1, S. 89, 119; Andrieu, Le pontifical, 1938 \endash  1941, Bd. 2, S. 208; Mohan, Initia, 1975 \endash  1978, (1985), S. 277.}

