\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 108\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  114\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Henricus de Langenstein}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Speculum animae}}\plain \f1\lang1033\fs26 . (108\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) Rubrik: \plain \f1\i\lang1033\fs26 Incipit\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Speculum anime editum a magistro\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Heynrico de Hassia. \plain \f1\lang1033\fs26 Text:\plain \f1\i\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Anima mea novi quod curiosa sis}}\plain \f1\lang1033\fs26  \u8230 \'85 (114\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 mirificam in finem ultimum reductionem. Explicit Speculum anime editum a magistro Heynrico de Hassia deo gracias. \plain \f1\lang1033\fs26 Daneben verwischter Schreibervers:\plain \f1\i\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Dum finis bonus est totum, laudabile tunc est}}\plain \f1\lang1033\fs26 . \endash  Zu Heinrich von Langenstein (1325 \endash  1397) und dem Speculum animae vgl. Roth, Bibliographie, 1888, S. 9 \endash  10, Nr. 6.1; Hohmann, Initienregister, 1976, S. 399 \endash  426, bes. S. 402, Nr. 12; {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Thorndike/ Kibre (1963), S. 97}}\plain \f1\lang1033\fs26 ; VL(2), Bd. 3 (1981), Sp. 763 \endash  773 (Thomas Hohmann/ Georg Kreuzer); Newhauser/ Bejczy, Bloomfield, 2008, Nr. 418; zum Schreibervers am Schlu\u223 \'df vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Proverbia, Bd. II/4, Nr. 28485}}\plain \f1\lang1033\fs26 ; Text auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 675}}\plain \f1\lang1033\fs26 , 54\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ; vgl. DA LuHB Kat. 4; S. 160; {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 79}}\plain \f1\lang1033\fs26 , 17\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ; vgl. DA ULB Kat. 5,2.}

