\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 116\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \endash  117\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  Tres {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 orationes}}\plain \f1\lang1033\fs26 . (116\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) Rubrik {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Philippes d\rquote Oth\u233 \'e9e}}\plain \f1\lang1033\fs26 : \plain \f1\i\lang1033\fs26 Oracio\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Benedictus papa contulit omnibus devote dicentibus tecentes dies indulgencie\plain \f1\lang1033\fs26 . 1. Text: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Benedicat me imperialis maiestas, protegat me regalis divinitas}}\plain \f1\lang1033\fs26  ...\plain \f1\i\lang1033\fs26  ista\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 invocatio salus et protectio in nomine patris et filii et spiritus sancti\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 ...; \plain \f1\lang1033\fs26 \endash  vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 AH, Bd. 31, S. 14}}\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Chevalier, Repertorium, Nr. 24134}}\plain \f1\lang1033\fs26 ; Leroquais, Les livres d'heures. Manuscrits, Bd. 2, S. 68; 2. Rubrik: \plain \f1\i\lang1033\fs26 Oracio\plain \f1\lang1033\fs26 . Text: {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Precor te amantissime domine Jesu Christe propter illam eximiam caritatem}}\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 propter tuam magnum misericordium in tribuem digneris\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 qui vivis et regnas deus per omnia secula seculorum\plain \f1\lang1033\fs26 . \endash  Vgl. Leroquais, Les livres d'heures. Manuscrits, Bd. 1, S. XXXI, 336; Leroquais, Psaultiers, Bd. 1, S. 41; Bd. 2, S. 252; 3. Rubrik: \plain \f1\i\lang1033\fs26 Item alia oracio\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 De 7 verba domini dictis in cruce\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 per eundem\plain \f1\lang1033\fs26 . Text: {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Domine Jesu Christe}}\plain \f1\lang1033\fs26\chcbpat17 , {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 fili dei vivi}}{\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 , }}{\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 qui septem verba dic ultima vite tue in cruce pendens}}\plain \f1\lang1033\fs26  ... (117\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 in regno meo epulari\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 iocundari et commorari per infinita secula seculorum amen\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 ... \plain \f1\lang1033\fs26 Nachtrag von der Hand {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Philippes d\rquote Oth\u233 \'e9e}}\plain \f1\lang1033\fs26 : \plain \f1\i\lang1033\fs26 In repertorio librarie inveniens unam aliam oracionem\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  que sic intitulatur\plain \f1\lang1033\fs26 : \plain \f1\i\lang1033\fs26 Septem oraciones\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  in quibus continentur septem verba\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  que Jesus locutus fuit in cruce\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Et sic incipit\plain \f1\lang1033\fs26 : \plain \f1\i\lang1033\fs26 Domine Jesu Christe\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  qui pendens in cruce scilicet multum different ad crucem\plain \f1\lang1033\fs26 . \endash  Vgl. Leroquais, Les livres d'heures. Manuscrits, Bd. 1, S. 155; Wilmart, po\u232 \'e8me, 1935, S. 235 \endash  278, S. 235 \endash  278, bes. S. 273; zwischen den Gebeten jeweils Angaben zu dem durch das Beten gew\u228 \'e4hrten Abla\u223 \'df. }

