\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 117\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Alanus ab Insulis}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Anticlaudianus}}\plain \f1\lang1033\fs26 , Exzerpt. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Iam pedites in bella ruunt}}\plain \f1\i\lang1033\fs26  \plain \f1\lang1033\fs26 ... \plain \f1\i\lang1033\fs26 In terris\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 dum tela pluunt\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 dum pulveris imber\plain \f1\lang1033\fs26 . \endash  Distinctio 9, Capitulum 1, Versus 1 \endash  5; Druck: PL, Bd. 210, Sp. 565; Wright, Poets, 1872, Bd. 2, S. 268 \endash  426; bes. S. 412. \endash  118\plain \f1\super\lang1033\fs24 r/v\plain \f1\lang1033\fs26  leer; 119\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  bis auf Blattrest herausgerissen (s.o. Lagen). }

