\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 182\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 De Laude BMV}}\plain \f1\lang1033\fs26 . {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 O felicissima rerum magna dearum sanctior omni Maria Mariarum virgo virginum}}\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 domina dominantium\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 Reminiscere miserationum tuarum piisima recordare nostram miseriam\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 oblivisce iniquitatum nostrarum domina de memorare tuam iusticiam\plain \f1\lang1033\fs26 . \endash  Die Handschrift enth\u228 \'e4lt 21 Verse, ist im Vergleich zum Druck damit deutlich k\u252 \'fcrzer und verzichtet auf dessen grammatikalische Glossen; vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 12625}}\plain \f1\lang1033\fs26 ; Druck: {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 GW M17197}}\plain \f1\lang1033\fs26 . \endash  183\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  leer. }

