\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 183\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \endash  184\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  (183\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Carmen}}\plain \f1\lang1033\fs26  \u8218 \'82Cisioianus\rquote  cum expositio. Text beginnt: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Januarius. Cisio ianus epy sibi vendicat}}\plain \f1\i\lang1033\fs26  oc feli mar an\plain \f1\lang1033\fs26  ... Text endet: \plain \f1\i\lang1033\fs26 Sanctus ab inde Thomas modo nat Steph Io Pu Thome sil\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Sillaba queque diem duo versus dant tibi mensum\plain \f1\lang1033\fs26 . Expositio beginnt: {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Calende. Prima dies cuiuslibet mensis vocatur}}\plain \f1\i\lang1033\fs26  Kalendas\plain \f1\lang1033\fs26  ... Expositio endet: \plain \f1\i\lang1033\fs26 ultima dies mensis semper est pridie Calende\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 octo tenet Ydus mensis generatur omnis\plain \f1\lang1033\fs26 .  \endash  Vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 2808}}\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Thorndike/ Kibre, Sp. 226}}\plain \f1\lang1033\fs26 ; Kully, Cisiojanus, 1974, S. 93 \endash  12; VL(2), Bd. 1 (1978), Sp. 1285 \endash  1289 (Arne Holtorf); die gleichen Verse auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 76}}\plain \f1\lang1033\fs26 , 13\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 1415}}\plain \f1\lang1033\fs26 , 31\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 1571}}\plain \f1\lang1033\fs26 , 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  6\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 1941}}\plain \f1\lang1033\fs26 , 74\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 . \endash  184\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  184\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  Federproben, darunter (184\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) der Anfang des Pater Noster; (184\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) Federzeichnungen von Knospenfleuronn\u233 \'e9e und von grotesken Masken.}

