\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 49\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \endash  50\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 In Aristotelis De anima}}\plain \f1\lang1033\fs26  (?), lat. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 \u8218 \'82Sensus quia sentit\lquote  id est sensus non sentit}}\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 sentire est agere\plain \f1\lang1033\fs26  ... \u8218 \'82\plain \f1\i\lang1033\fs26 Intellectus quia intellexit\plain \f1\lang1033\fs26 \lquote  \plain \f1\i\lang1033\fs26 propter quidem unumquidemque thema \plain \f1\lang1033\fs26 ... (50\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \u8218 \'82\plain \f1\i\lang1033\fs26 Intellectui vero ultilitas\plain \f1\lang1033\fs26 \lquote . \plain \f1\i\lang1033\fs26 Contra intellectui non est utilitas coniuncta\plain \f1\lang1033\fs26  ... \u8218 \'82\plain \f1\i\lang1033\fs26 Qualiter autem extremis\plain \f1\lang1033\fs26 \lquote . \plain \f1\i\lang1033\fs26 Illa dicuntur se tangere per Aristotelem\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 quinto physicorum\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 quorum extrema sunt simul scilicet extrema particularitatis\plain \f1\lang1033\fs26  ... \u8218 \'82\plain \f1\i\lang1033\fs26 Hoc fit per ipsum extrema\plain \f1\lang1033\fs26 \lquote . \plain \f1\i\lang1033\fs26 Inter extrema non est transitus\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 sensus vertit spiritum sensibilem\plain \f1\lang1033\fs26 . }

