\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 52\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \endash  54\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Notizen}}\plain \f1\lang1033\fs26 , kurze Sentenzen und Verse. (52\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) Zur Naturphilosophie, Logik und Theologie u.a. {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Raimundus Lullus}}\plain \f1\lang1033\fs26  zugeschrieben; (53\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \endash  54\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) zu juristischen Themen; (54\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) zu theologischen Fragen, erneut z.T. {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Raimundus Lullus}}\plain \f1\lang1033\fs26  zugeschrieben. Verse, u.a.: (53\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) 1. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Os mulier mordens fodens}}\plain \f1\lang1033\fs26  ... .\endash  Vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 13516}}\plain \f1\lang1033\fs26 ; 2. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Balnea vina Venus super alea fumus}}\plain \f1\i\lang1033\fs26  et ignis hec nocent oculis scilicet vigilare magis\plain \f1\lang1033\fs26 ; 3. {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Eya, rumpe moras varum}}\plain \f1\i\lang1033\fs26  ..\plain \f1\lang1033\fs26 . .\endash  Verse aus {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Publius Vergilius Maronis}}\plain \f1\lang1033\fs26 , Aeneidos Lib. IV, Verse 569 \endash  570 (s.a. 482\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ); \plain \f1\i\lang1033\fs26 Armigritam\plain \f1\lang1033\fs26  (?) \plain \f1\i\lang1033\fs26 moribus urbanam munere unices\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 claustralem subito ruralem precibus adde\plain \f1\lang1033\fs26 ; 4. {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Inconstans animus, oculus vagus}}\plain \f1\lang1033\fs26  ... .\endash  Vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Proverbia, II/2, Nr. 12215}}\plain \f1\lang1033\fs26 ; 5. {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Cor, cordi, corda, cordatum}}\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 cor mihi\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 corda\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 cordatum\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 corda\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 sic concordant duo corda\plain \f1\lang1033\fs26 . 6. {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Futurum despicitur suadent presencia fructum}}\plain \f1\lang1033\fs26 . 7. {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Ad presens ova sunt cras pullis meliora}}\plain \f1\lang1033\fs26 . \endash  Vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Proverbia, II/1, Nr. 429}}\plain \f1\lang1033\fs26 ; 8. {\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 In capitis cella fabrorum sensio bella}}\plain \f1\lang1033\fs26 . 9. {\field{\*\fldinst HYPERLINK "hida://5650[8].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Pugnant malleolis est caput earum unicus}}\plain \f1\lang1033\fs26 ; 10. {\field{\*\fldinst HYPERLINK "hida://5650[9].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Non est in speculo res}}\plain \f1\lang1033\fs26  ... . \endash  Vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Proverbia, II/3, Nr. 17651}}\plain \f1\lang1033\fs26 ; 11. {\field{\*\fldinst HYPERLINK "hida://5650[10].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Fallere, flere, nere mentis mulierque tacere}}\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Hec quinque versus statuit deus in muliere\plain \f1\lang1033\fs26 . \endash  \u196 \'c4hnlich {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Proverbia, Nr. 8751}}\plain \f1\lang1033\fs26 ; 12. {\field{\*\fldinst HYPERLINK "hida://5650[11].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Adam, Sampsonem, David, Lot et Salomonem femina decepit}}\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  quis modo tutus erit\plain \f1\lang1033\fs26 . \endash  Vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 520}}\plain \f1\lang1033\fs26 ; (53\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) 13. {\field{\*\fldinst HYPERLINK "hida://5650[12].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Esurit ars decreta tument lex lucra ministrat}}\plain \f1\i\lang1033\fs26 .\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Pontificat Moyses thalamos medicina subintrat\plain \f1\lang1033\fs26  \endash  Vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 5910}}\plain \f1\lang1033\fs26 ; 14. {\field{\*\fldinst HYPERLINK "hida://5650[13].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Super ripam Acherontis vitulus depascus est}}\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Non intravit\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  sed regavit\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  queritur\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  quod iuris est\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Novella Johannis Andree an filia\plain \f1\lang1033\fs26 . }

