\pard\fi0\li0\qj\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs22 Schriftspiegel z.T. stark verbr\u228 \'e4unt; Schrift schl\u228 \'e4gt durch\~\~\u183 \'b7\~\~Lagen: II\plain \f1\super\lang1033\fs24 4\plain \f1\lang1033\fs22  + 23 IV\plain \f1\super\lang1033\fs24 188\plain \f1\lang1033\fs22  + III\plain \f1\super\lang1033\fs24 194\plain \f1\lang1033\fs22  + 5 IV\plain \f1\super\lang1033\fs24 234\plain \f1\lang1033\fs22  + VI\plain \f1\super\lang1033\fs24 246\plain \f1\lang1033\fs22  + 5 III\plain \f1\super\lang1033\fs24 276\plain \f1\lang1033\fs22  +  (II \endash  2)\plain \f1\super\lang1033\fs24 278\plain \f1\lang1033\fs22 ; am Schlu\u223 \'df fehlen zwei Bl. (ohne Textverlust)\~\~\u183 \'b7\~\~Wasserzeichen: Hand, Handschuh mit zweikonturigem Kreuz zwei Varianten sehr \u228 \'e4hnlich und \u228 \'e4hnlich WZIS DE8085-PO-154719 (Worms 1495); Buchstabe P, gebrochen, gespaltener Schaft mit Blume dar\u252 \'fcber, mehrere Varianten: 1. sehr \u228 \'e4hnlich und \u228 \'e4hnlich Piccard, Buchstabe P, Bd. 4,2, Nr. VIII, 338 (Kleve 1503); 2. \u228 \'e4hnlich Piccard, Buchstabe P, Bd. 4,2, Nr. VIII, 16 (Mecheln 1494); 3. \u228 \'e4hnlich Piccard, Buchstabe P, Bd. 4,2, Nr. VIII, 18 \endash  19 (Maastricht 1502, Kleve 1491); 4. \u228 \'e4hnlich Piccard, Buchstabe P, Bd. 4,2, Nr. VIII, 276 (Melcheln 1485, 1489); 5. \u228 \'e4hnlich Piccard, Buchstabe P, Bd. 4,2, Nr. VIII, 303 (D\u252 \'fcsseldorf, Utrecht 1488); 6. \u228 \'e4hnlich Piccard, Buchstabe P, Bd. 4,2, Nr. VIII, 561 (K\u246 \'f6ln 1482); 7. \u228 \'e4hnlich Piccard, Buchstabe P, Bd. 4,2, Nr. VIII, 311 (Mecheln 1487); 8. \u228 \'e4hnlich Piccard, Buchstabe P, Bd. 4,2, Nr. VIII, 289 (Essen 1491); 9. \u228 \'e4hnlich Piccard, Buchstabe P, Bd. 4,2, Nr. VIII, 309 (Mecheln 1495); 10. \u228 \'e4hnlich Piccard, Buchstabe P, Bd. 4,2, Nr. VIII, 331 (Franchemont 1492); 11. \u228 \'e4hnlich Piccard, Buchstabe P, Bd. 4,2, Nr. VIII, 241 Utrecht 1486); 12. \u228 \'e4hnlich Piccard, Buchstabe P, Bd. 4,2, Nr. VIII, 136 (Culemborg 1488); 13. \u228 \'e4hnlich Piccard, Buchstabe P, Bd. 4,2, Nr. VIII,  254; 14. sehr \u228 \'e4hnlich Piccard, Buchstabe P, Bd. 4,2, Nr. III, 491 (Stra\u223 \'dfburg 1484 (nur 189/194); Buchstabe P gebrochen, gespaltener Schaft sehr \u228 \'e4hnlich WZIS DE8100-PO-102191 (L\u246 \'f6wen 1481) (nur 192); Wappen mit drei Lilien, dar\u252 \'fcber Krone mit Blume, darunter Buchstabe, mehrere Varianten: 1. sehr \u228 \'e4hnlich WZIS AT8100-PO-128593 (Sitten 1494); 2. \u228 \'e4hnlich Piccard, Lilie, Bd. 13, Nr. III, 1719 (Poppelsdorf 1496); 3. \u228 \'e4hnlich Piccard, Lilie, Bd. 13, Nr. III, 1731 (Siegen 1496); 4. \u228 \'e4hnlich Piccard, Lilie, Bd. 13, Nr. III, 1734 \endash  1735 (Siegen, Sitten 1494); 5. \u228 \'e4hnlich Piccard, Lilie, Bd. 13, Nr. III, 1741 (Siegen 1494); Krug mit Deckel, mit einem Henkel, mit Deckelverzierung und Blume dar\u252 \'fcber, mehrere Varianten, darunter: 1. sehr \u228 \'e4hnlich und \u228 \'e4hnlich WZIS NL8370-PO-31320 (Middelburg/ Seeland 1489); 2. \u228 \'e4hnlich Briquet, Nr. 12618 (Troyes 1483); 3. \u228 \'e4hnlich Briquet, Nr. 12620 (Nancy 1484); 4. \u228 \'e4hnlich und Typus Briquet Nr. 12619 (Paris 1483)\~\~\u183 \'b7\~\~im ersten Text Satzreklamanten, beschnitten\~\~\u183 \'b7\~\~6\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  \endash  10\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  auf dem Kopfsteg rechts alte Tintenfoliierung mit arabischen Ziffern: \plain \f1\i\lang1033\fs22 1 \endash  4\plain \f1\lang1033\fs22 ; Foliobezeichnung \plain \f1\i\lang1033\fs22 3\plain \f1\lang1033\fs22  zweimal vergeben; moderne Bleistiftfoliierung;\~\~\u183 \'b7\~\~Schriftraum: 15,5 \endash  18 x 8,5 \endash  13,5; Schriftraum je nach Text und Schreiberhand stark variierend; Schriftraumbegrenzung in der Regel blind vorgepr\u228 \'e4gt\~\~\u183 \'b7\~\~1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  \endash  2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  zweispaltig\~\~\u183 \'b7\~\~24 \endash  56 Zeilen; Zeilenzahl je nach Text und Schreiberhand stark variierend\~\~\u183 \'b7\~\~Bastarda mit Schleifen, sp\u228 \'e4te gotische Kursive und Textualis von mehreren, mindestens drei oder vier H\u228 \'e4nden; teilweise bereits mit Elementen der Kurrentschrift; gelegentlich Nachtr\u228 \'e4ge von zeitgleichen H\u228 \'e4nden auf den Blattr\u228 \'e4ndern; vereinzelt Notah\u228 \'e4nde oder Notazeichen\~\~\u183 \'b7\~\~\u220 \'dcberschriften abgesetzt und einger\u252 \'fcckt, meist fett, in vergr\u246 \'f6\u223 \'dfertem Schriftgrad, z.T. rot unterstrichen und/ oder in Textualis; Lemmata in der Regel ebenfalls rot unterstrichen\~\~\u183 \'b7\~\~5\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  \endash  174\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 , 195\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  \endash  196\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 , 219\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  \endash  222\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 , 227\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  \endash  229\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  rubriziert\~\~\u183 \'b7\~\~3-8zeilige rote Lombarden, 124\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  in Blau, 183\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22  Umrisse in brauner Feder; oder Aussparungen daf\u252 \'fcr\~\~\u183 \'b7\~\~231\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22  kleine Zeichnung mit brauner Feder eines {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 medizinischen}}\plain \f1\lang1033\fs22  Z\u228 \'e4pfchens (Suppositorium). }

