\uc1
\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 9\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  85\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Antonius Guaynerius}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Summarium de febribus}}\plain \f1\lang1033\fs26 . (9\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) Rubrik: \plain \f1\i\lang1033\fs26 Tractatus de febribus editus per magistrum Anthonium Guaynerum arcium et medicine doctorem egregium Papiensem feliciter incipit\plain \f1\lang1033\fs26  ... Text: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Tui amoris gracia in Anthoni Magliane ad hunc debem locum omnium}}\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 Summarium hoc de febribus in tres divisum est partes sive differencias\plain \f1\lang1033\fs26 : \plain \f1\i\lang1033\fs26 Prima pars sive differencia de febre erit effimeris\plain \f1\lang1033\fs26  ... (10\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) Rubrik: \plain \f1\i\lang1033\fs26 Prima pars sive differencia in se continet unum capitulum De febribus effimeris\plain \f1\lang1033\fs26 . Text: \plain \f1\i\lang1033\fs26 Cum me sit intencionis hoc in summario febre negocium una cum principe\plain \f1\lang1033\fs26  ... (83\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) Rubrik: \plain \f1\i\lang1033\fs26 Capitulum tercium et ultimum de signis causis et cura ethice senectutis\plain \f1\lang1033\fs26 . Text: \plain \f1\i\lang1033\fs26 Ut omnia sub hoc vocabulo ethica comprehensa\plain \f1\lang1033\fs26  ... (85\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 et hec de ethica senectutis et eius cura sic breviter dicta sufficiant\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 que hinc summario finem imponitur pro quo Jesu Christo crucifixo infinite sint laudes\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Amen\plain \f1\lang1033\fs26 . \endash  Vgl. Thorndike, History, 1923 \endash  1958, Bd. 4 (\plain \f1\super\lang1033\fs24 1\plain \f1\lang1033\fs26 1934, \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs26 1966), S. 170 \endash  174; {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Thorndike/ Kibre 1963, Sp. 1592, 318}}\plain \f1\lang1033\fs26 ; Druck: {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 GW 11581}}\plain \f1\lang1033\fs26 , fol. 121\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs26  \endash  141\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs26 ; C.A.L.M.A., Bd. 1.4 (2001), S. 377 \endash  378, bes. S. 378, Nr. 8 (Simona Polidori). }

