\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 186\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  188\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Gentilis de Fulgineo}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 De balneis}}\plain \f1\lang1033\fs26 , unvollst\u228 \'e4ndig. (186\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Intendo mediocriter docere medicos quam brevius potero}}\plain \f1\i\lang1033\fs26  de natura balneorum\plain \f1\lang1033\fs26  ... (188\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Aliqua sunt enea et alminosa et sulphurea\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 et\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 hec ad presens de balneis nos circumstantibus sufficiant\plain \f1\lang1033\fs26 . \endash  Text unvollst\u228 \'e4ndig, endet mit dem Kapitel \u8222 \'84De Balneis conpositis\ldblquote  bzw. \u8222 \'84De balneo de Avinione\ldblquote ; vgl. Glorieux, Facult\u233 \'e9; S. 274, Nr. 335af.); {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Thorndike/ Kibre 1963, Sp. 759}}\plain \f1\lang1033\fs26 ; Jo\u235 \'ebl Chandelier, La naissance d'un savoir m\u233 \'e9dical sur les bains thermaux: les trait\u233 \'e9s de Gentile da Foligno (m. 1348) in: Didier Boisseuil/ Marilyn Nicoud (Hrsg.), S\u233 \'e9journer au bain. Le thermalisme entre m\u233 \'e9decine et soci\u233 \'e9t\u233 \'e9 (XIV\plain \f1\super\lang1033\fs24 e\plain \f1\lang1033\fs26 -XVI\plain \f1\super\lang1033\fs24 e\plain \f1\lang1033\fs26  si\u232 \'e8cle), Lyon 2010, S. 15 \endash  30; Druck: {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 GW 10617}}\plain \f1\lang1033\fs26  (u.\u246 \'f6.); C.A.L.M.A., Bd. 4 (2014), S. 153 \endash  159, bes. S. 155, Nr. 23 (Victoria Recio Mu\u241 \'f1oz).}

