\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 146\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  168\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  (\plain \f2\fs26 Pseudo-){\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f2\fs26\chcbpat17 M\u257 \'e2\u353 \'f0\u257 \'e2\rquote all\u257 \'e2h Ibn-Athar\u299 \'ee}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Astrolabium}}\plain \f1\lang1033\fs26  (Translatio {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Johannis Hispalensis}}\plain \f1\lang1033\fs26 ). (146\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Incipit Astrolabium secundum Meselem\plain \f1\lang1033\fs26 <. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Sscito }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 (!)}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 , quod astrolabium est nomen Grecum}}\plain \f1\lang1033\fs26  ... Compositio, Kapitel 1: >\plain \f1\i\lang1033\fs26 Composicio materis\plain \f1\lang1033\fs26 <. \plain \f1\i\lang1033\fs26 Cum volueris facere astrolabium ad cuius cumque latitudinem regionis \plain \f1\lang1033\fs26 ... (161\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) Practica. >\plain \f1\i\lang1033\fs26 De usu astrolabii et primus de nominibus instrumentorum eius\plain \f1\lang1033\fs26 <. \plain \f1\i\lang1033\fs26 Nomina instrumentorum sunt hec\plain \f1\lang1033\fs26 : \plain \f1\i\lang1033\fs26 Primum est armilla suspensoria\plain \f1\lang1033\fs26  ... (164\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 vel si volueris accipe altitudinem cuiusvis stelle altiorem\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 que est altitudo in eadem regione\plain \f1\lang1033\fs26 . >\plain \f1\i\lang1033\fs26 Inventio hore in aliqua regione per non suam\plain \f1\lang1033\fs26  (?) \plain \f1\i\lang1033\fs26 tabulam\plain \f1\lang1033\fs26 <. \plain \f1\i\lang1033\fs26 Cum in aliqua regione cuius latitudo in tabulis astrolabii non fuerit descripta volueris inve\plain \f1\lang1033\fs26 - (164\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 )\plain \f1\i\lang1033\fs26 nire per illud astrolabium\plain \f1\lang1033\fs26  ... (168\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\lang1033\fs24 >\plain \f1\i\lang1033\fs26 De planicie mensuranda<. Si queris cum astrolabio metiri planiciem ... talis est comparacio stature tue ad planiciem. >Explicit<.\plain \f1\lang1033\fs24  \plain \f1\lang1033\fs26 \endash  Textbestand und Reihenfolge der Kapitel von Compositio und Practica im Vergleich zum Druck bei Thomson, On the Astrolabe, 2019 (\plain \f1\super\lang1033\fs24 1\plain \f1\lang1033\fs26 2012), stark abweichend; zum Textbestand der Compositio vgl. ebenda Teil I, Sigle D\plain \f3\sub\lang1032\fs24 \u947 \'e3;\plain \f1\lang1033\fs26 ; die Practica ab 164\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  deutlich (um 23 Kapitel) erweitert; zu dieser Version vgl. Moritz Steinschneider, Maschallah, in: Zeitschrift der Deutschen morgenl\u228 \'e4ndischen Gesellschaft 52,3 (1898), S. 434 \endash  440, bes. S. 436; Druck: Thomson, On the Astrolabe, 2019 (\plain \f1\super\lang1033\fs24 1\plain \f1\lang1033\fs26 2012), Teil 2 und 5; vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Thorndike/ Kibre 1963, Sp. 1409}}\plain \f1\lang1033\fs26 ; Carmody, Astronomical Works, 1960, S. 24 \endash  25, S. 169, Nr. 2a; zur Tafel 156\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  vgl. Kunitzsch, Sternverzeichnisse, 1966, S. 68 \endash  69, Typ XIe; zur Tafel 157\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  ebenda, S. 47: Typ XIIb; Text auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 1227}}\plain \f1\lang1033\fs26 , 113\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 . \endash  168\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \endash  169\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  leer. }

