\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 170\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  192\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Johannes de Sacrobosco}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Compotus Ecclesiasticus seu De Anni Ratione}}\plain \f1\lang1033\fs26 . (170\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) Text beginnt: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Computus est sciencia considerans tempora ex Solis et Lune motibus}}\plain \f1\lang1033\fs26  ... (192\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) Text endet: \plain \f1\i\lang1033\fs26 interim evum dicitur idem quod mora\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Unde Boetius consolationis\plain \f1\lang1033\fs26 : \plain \f1\i\lang1033\fs26 O qui perpetua mundum ratione gubernas\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 quod nos hinc fructificemus amen\plain \f1\lang1033\fs26 . (170\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) Glosse beginnt marginal:{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17  Iste liber solum tractat de motibus Solis et Lune et nec aliorum planetarum}}\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Residet auctor dicens\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 quod ecclesia creat solum de motibus\plain \f1\lang1033\fs26  ... (192\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) Glosse endet marginal: \plain \f1\i\lang1033\fs26 Quinque pedes passum faciunt passus quoque centum\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 octo facit stadia\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 duplicatum dat tibi leucam\plain \f1\lang1033\fs26 . \endash  Text mit zahlreichen interlinearen und marginalen Glossen und mit abschlie\u223 \'dfendem {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Boetius}}\plain \f1\lang1033\fs26 -Zitat; Druck (Textabgleich mit): {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 VD16: ZV 8727}}\plain \f1\lang1033\fs26 ; vgl. Glorieux, Facult\u233 \'e9, S. 235 \endash  236, Nr. 267b.); {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Thorndike/ Kibre 1963, Sp. 243}}\plain \f1\lang1033\fs26 ; VL(2), Bd. 4 (1983), Sp. 731 \endash  736 (Francis B. Br\u233 \'e9vart/ Menso Folkerts), bes. Sp. 735; Weijers, Travail, 1994ff., Bd. 11,5 (2003), S. 157 \endash  160, bes. S. 159; zu den abschlie\u223 \'dfenden Versen der Glosse vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[2].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 16033a}}\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Thorndike/ Kibre 1963, Sp. 243}}\plain \f1\lang1033\fs26 ; Text auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 2827}}\plain \f1\lang1033\fs26 , 27\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 1227}}\plain \f1\lang1033\fs26 , 21\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 . \endash  192\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  leer.}

