\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 205\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  207\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Ars algorismi de fractionibus}}\plain \f1\lang1033\fs26 . (205\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Certificatur quandoque totum per partes quandoque partes per totum}}\plain \f1\lang1033\fs26  ... (207\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 eodem modo potes probare ut in predicta questione\plain \f1\lang1033\fs26 . \endash  Vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Thorndike/ Kibre 1963, Sp. 201}}\plain \f1\lang1033\fs26 ; Parallel\u252 \'fcberlieferung: {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 London, BL, Ms Harley 1}}\plain \f1\lang1033\fs26 , 79\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs26 . }

