\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 184\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  186\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Raimundus Gaufredi}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Verbum abbreviatum de Leone viridi}}\plain \f1\lang1033\fs26 , unvollst\u228 \'e4ndig. (184\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) Rubrik: \plain \f1\i\lang1033\fs26 Raymundus Gamfredi\plain \f1\lang1033\fs26 . Text: \plain \f1\i\lang1033\fs26 Incipit opus fratris Raymundi Gamfredi de modo preparacionis lapidis occulti.\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 In Christi nomine\plain \f1\lang1033\fs26 . {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Recipe acetum fortissimum in bona quantitate}}\plain \f1\lang1033\fs26  ... (186\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) Text endet unvermittelt: \plain \f1\i\lang1033\fs26 Excepto\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 quod non ponas nisi unam partem terre et in bibe ipsum tantum et tocius cum suo sulfure\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 quod aer appellatur donec biberit\plain \f1\lang1033\fs26  \u9553 \'a6 <triplum sui, terendo bene et imbibendo super marmor atque dessicando ...>. \endash  Text endet aufgrund von Blattverlust unvermittelt; vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Thorndike/ Kibre 1963, Sp. 1317}}\plain \f1\lang1033\fs26 ; Druck (Textabgleich mit): Sanioris medicinae, 1603 ({\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 VD17: 39:115705L}}\plain \f1\lang1033\fs26 ), S. 265 \endash  282; vgl. Glorieux, R\u233 \'e9pertoire, S. 60 \endash  76, Nr. 312, bes. S. 62, Nr. 312m.); Glorieux, Facult\u233 \'e9, S. 338 \endash  342, bes. S. 339, Nr. 416m.); Little, Roger Bacon\rquote s Works, 1914, S. 373 \endash  419, bes. S. 397 \endash  398, Nr. 21; Thorndike, History, 1923 \endash  1958, Bd. 3 (1934), S. 95; Bd. 4 (1934), S. 15 \endash  17; {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Thorndike/ Kibre 1963, Sp. 1688}}\plain \f1\lang1033\fs26 ; Mohan, Initia, 1975 \endash  1978, (1976), S. 313, (1978), S. 482; Text auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hs 2226}}\plain \f1\lang1033\fs26 , 50\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 . }

