\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 9\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  9\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Merlini}}\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Allegoria}}\plain \f1\lang1033\fs26  profundissimum philosophici lapides archanum perfectae continens. (9\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Cuidam rex potens, volens alios superare potentes}}\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  paravit se ad bellum\plain \f1\lang1033\fs26  ... (9\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Solutos in sero caprino etc\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 videbant aptum ad omnia\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Hec est ergo via trium dierum pro regibus et principibus\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  qui parum laborem et multam lucri affectant\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 haberis\plain \f1\lang1033\fs26 . >\plain \f1\i\lang1033\fs26 Finis\plain \f1\lang1033\fs26 <. \endash  Vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Thorndike/ Kibre 1963, Sp. 1246}}\plain \f1\lang1033\fs26 ; Druck: Mangetus, Bibliotheca, 1702, Bd. 2, S. 191 \endash  192 u.\u246 \'f6.}

