\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 24\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  31\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  (Pseudo-){\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Raimundus Lullus}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Anima artis transmutatoriae}}\plain \f1\lang1033\fs26 , Pars 1 (Versio \u8218 \'82Iam saepe et saepius\lquote ). (24\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) Rubrik (Nachtrag 16. Jh.): \plain \f1\i\lang1033\fs26 Anime transmutationis metallorum compendium\plain \f1\lang1033\fs26 . Schreibervers: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Ablue, sublima, tere, fige, coagula, solve}}\plain \f1\lang1033\fs26 . Text: \plain \f1\i\lang1033\fs26 In nomine sancte trinitatis indivise \plain \f1\lang1033\fs26 (!)\plain \f1\i\lang1033\fs26  et eterne unitatis\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Incipit compendium huius principii\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 quod cognominamus\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Animam Transmutationis Metallorum et missum regi Roberto nostrum\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Lapidarium preciosissimum\plain \f1\lang1033\fs26 . {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Iam sepe et sepius allocuti recolimus multis et diversis modis practicandi}}\plain \f1\lang1033\fs26  ... (31\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 et sic habebis omnia completum\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Cum intencio nostra in presenti compedio non sit nisi practicam nudam a theorica designare cum adiuvamine\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 que est trinus personaliter et unus eternaliter et essentialiter\plain \f1\lang1033\fs26 . \endash  Druck (Textabgleich mit): Mangetus, Bibliotheca, 1702, Bd. 1, S. 780 \endash  790; vgl. Thorndike, History, 1923 \endash  1958, Bd. 4 (1934/ Reprint 1966), S. 619 \endash  652, S. 626 \endash  627; Glorieux, R\u233 \'e9pertoire, Nr. 335ld.); {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Thorndike/ Kibre 1963, Sp. 650, 698}}\plain \f1\lang1033\fs26 ; Mohan, Initia, 1975 \endash  1978, (1977), S. 179*; Pereira, Alchemical Corpus, 1989 (s.o. 10\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ), S. 68 \endash  69, Nr. I.12.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 31\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \endash  34\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  (Pseudo-){\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Raimundus Lullus}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Anima artis transmutatoriae}}\plain \f1\lang1033\fs26 , Pars 1 (Versio \u8218 \'82Fulgeat regis\lquote ), Lateinisch mit franz\u246 \'f6sischen Einsprengseln. (31\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Incipit anima artis transmutatorie magistri Raymundi\plain \f1\lang1033\fs26 <. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Fulgeat regis diadema Roberti regum illustrissimi recolimus rex illustrissime}}\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 In nomine sancte trinitatis et eterne unitatis\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Incipit compendium huius principii\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 Iam\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 sepius allocuti recolimus multis et diversis modis practicandi \plain \f1\lang1033\fs26 ... (33\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Nam tu colligere potest et fabricare de te ipso alia plura\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 unde de modo practicandi sic sit processus\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 qui est 3\plain \f1\i\super\lang1033\fs24 a\plain \f1\i\lang1033\fs26  pars principalis huius brevis conpedii \plain \f1\lang1033\fs26 (!). >\plain \f1\i\lang1033\fs26 De prima parte huius\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 3\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs26  partis\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 que est de modo dissolvendi pretacta principalia materialia. Et primo de signacione literarum et de oppositione figurarum\plain \f1\lang1033\fs26 <. \plain \f1\i\lang1033\fs26 Unde in huius operis primus dio \plain \f1\lang1033\fs26 (?) \plain \f1\i\lang1033\fs26 ostendit te scire quodam alphabetum de quo figuram\plain \f1\lang1033\fs26  ... (34\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Et hoc tibi sufficiat causa brevitatis et quia larga doctrina tibi data est per Codocillum et Testamentum et Quintam Essenciam et Terciam Distinctionem ordinis practicabilis et Questionarium et cetera alia volumina. Hic revera istius\plain \f1\lang1033\fs26  (?) \plain \f1\i\lang1033\fs26 tibi ab illustrissimo regi Eduardo missa\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  per quem satis poteris discurrere\plain \f1\lang1033\fs26  (?). \plain \f1\i\lang1033\fs26 De secunda huius\plain \f1\lang1033\fs26  >\plain \f1\i\lang1033\fs26 partis dissolutius in signis contente\plain \f1\lang1033\fs26 <. \endash  Vor allem auf (32\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) Initien der zitierten Werktitel, aber auch l\u228 \'e4ngere Passagen auf Franz\u246 \'f6sisch; vgl. Thorndike, History, 1923 \endash  1958, Bd. 4 (1934/ Reprint 1966), S. 619 \endash  652, S. 625 und 627; Glorieux, R\u233 \'e9pertoire, Nr. 335lx.); {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Thorndike/ Kibre (1963), Sp. 572}}\plain \f1\lang1033\fs26 ; M\u225 \'e1rio Martins, Uma obra ap\u243 \'f3crifa de Raimundo l\u250 \'falio, in: Revista Portuguesa de Filosofia 18 (1962), S. 68 \endash  72; Mohan, Initia, 1975 \endash  1978, (1976), S. 161*; Pereira, Alchemical Corpus, 1989 (s.o. 10\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ), S. 68 \endash  69, Nr. I. 12; Druck (Textabgleich mit): Mangetus, Bibliotheca, 1702, Bd. 1, S. 853 \endash  858. \endash  34\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  leer. }

