\pard\fi0\li0\qj\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs22 Vernet, Manuscrits, 1954, S. 114\~\~\u183 \'b7\~\~Knaus, Ewig und Grafschaft, 1960, bes. S. 59\~\~\u183 \'b7\~\~Knaus, Westf\u228 \'e4lische Handschriften, 1967, S. 166\~\~\u183 \'b7\~\~Kr\u228 \'e4mer, Handschriftenerbe, 1989, Bd. 1, S. 200 und 240\~\~\u183 \'b7\~\~Klein-Ilbeck, dat. Hss.}

