\pard\fi0\li0\qj\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs22 Die Handschrift besteht aus drei Teilen: fol. 1 \endash  189 (I); 190 \endash  229 (II); 230 \endash  236 (III)\~\~\u183 \'b7\~\~Lagen: (IV + 1)\plain \f1\super\lang1033\fs24 9\plain \f1\lang1033\fs22  + 8 IV\plain \f1\super\lang1033\fs24 73\plain \f1\lang1033\fs22  + 2 V\plain \f1\super\lang1033\fs24 93\plain \f1\lang1033\fs22  + IV\plain \f1\super\lang1033\fs24 101\plain \f1\lang1033\fs22  + 2 V\plain \f1\super\lang1033\fs24 121\plain \f1\lang1033\fs22  + IV\plain \f1\super\lang1033\fs24 129\plain \f1\lang1033\fs22  + III\plain \f1\super\lang1033\fs24 135\plain \f1\lang1033\fs22  + 4 IV\plain \f1\super\lang1033\fs24 167\plain \f1\lang1033\fs22  + III\plain \f1\super\lang1033\fs24 173\plain \f1\lang1033\fs22  + 2 IV\plain \f1\super\lang1033\fs24 189\plain \f1\lang1033\fs22  + 2 VI\plain \f1\super\lang1033\fs24 213\plain \f1\lang1033\fs22  + VIII\plain \f1\super\lang1033\fs24 229\plain \f1\lang1033\fs22  + (III + 1)\plain \f1\super\lang1033\fs24 236\plain \f1\lang1033\fs22 ; 1 und 236 Einzelbl\u228 \'e4tter\~\~\u183 \'b7\~\~moderne Bleistiftfoliierung.}

