\pard\fi0\li0\qj\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs22 Axters, Bibliotheca Dominicana Neerlandica, 1970, S. 72\plain \f1\i\lang1033\fs22 \~\~\u183 \'b7\~\~\plain \f1\lang1033\fs22 Stefano Caroti/ Michela Pereira/ Stefano Zamponi/ Paola Zambelli (Hrsg.), Alberto Magno, Speculum Astronomiae, Pisa 1977, S. 118 \endash  120, Nr. 14\~\~\u183 \'b7\~\~Kr\u228 \'e4mer, Handschriftenerbe, 1989, Bd. 2, S. 452\~\plain \f1\i\lang1033\fs22 \~\u183 \'b7\~\~\plain \f1\lang1033\fs22 Emery, Dionysius Cartusianus, 1991, S. 172, 212 \endash  213, 242 \endash  243. }

