\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 160\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  160\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Fridericus de Heilo}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Epistola}}\plain \f1\lang1033\fs26  de regimine monalium. (160\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) Rubrik: \plain \f1\i\lang1033\fs26 Epistola Gerardi Groit de regimine sororum\plain \f1\lang1033\fs26 . Text: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Spiritum consilii ac pietatis domino in Christo multum dilecto}}\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Hortatur me sanguis et officii communio aliquid tibi scribere\plain \f1\lang1033\fs26  ... (160\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 et sic curemus vulnera aliena\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  ne propria negligamus\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Vale\plain \f1\lang1033\fs26 . \endash  Text wird hier {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Geert Groote}}\plain \f1\lang1033\fs26  zugeschrieben; vgl. Jan Carel Pool, Frederik van Heilo en zijn Schriften. Akademisch Proefschrift ..., Amsterdam 1866, S. 34, Nr. 19b; LThK\plain \f1\super\lang1033\fs24 3\plain \f1\lang1033\fs26 , Bd. 4 (2009), Sp. 150 (Johannes Staub); C.A.L.M.A., Bd. 3,5 (2011), S. 576 \endash  577, bes. S. 576, Nr. 2 (E. Chiti); Parallel\u252 \'fcberlieferung: {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 K\u246 \'f6ln, HistASt, Best. 7004 (Handschriften (GB quart)), 146}}\plain \f1\lang1033\fs26 , 25\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Paris, Bibl. Mazarine, Cod. 1565 (1308)}}\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Prag, NB, Cod. XIV.E.5}}\plain \f1\lang1033\fs26 , 114\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 . }

