\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 197\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs26  \endash  204\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Dionysius Cartusianus}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Contra simoniam}}\plain \f1\lang1033\fs26  liber secundus. (197\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs26 ) Rubrik: \plain \f1\i\lang1033\fs26 De eadem questione\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 Dionisio Ruermundensi Chartusiano auctore\plain \f1\lang1033\fs26 : \plain \f1\i\lang1033\fs26 In modum apologie defendendo tractatum suum precedentem\plain \f1\lang1033\fs26 . Text: (P)\plain \f1\i\lang1033\fs26 ecunia tua tecum sit in perditionem \plain \f1\lang1033\fs26 ... (Act. 8, 20). {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Ista sunt verba sacratissimi principis Apostolorum}}\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 qui quantum in seipso saluberrimam consecraverit paupertatem in victu atque vestitu\plain \f1\lang1033\fs26  ... (204\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 procurrentur ad laudem et gloriam omnipotentis\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 qui est deus super omnia sublimis et benedictus\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Amen\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Explicit opusculum de simonia vitanda Dionisii a Ryckel Chartusiani in Ruermunda dum viveret\plain \f1\lang1033\fs26 . \endash  Druck: Dionysius Cartusianus, Opera omnia, Bd. 39, Tournai 1910, S. 308 \endash  325; vgl. Emery, Dionysius Cartusianus, 1991, S. 243, Nr. 118; weitere Lit. s.o. 190\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs26 ; Parallel\u252 \'fcberlieferung bei Emery (s.o.); au\u223 \'dferdem noch: {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 D\u252 \'fcsseldorf, ULB, Ms. B 60}}\plain \f1\lang1033\fs26 , 221\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Wien, \u214 \'d6NB, Cod. 4931}}\plain \f1\lang1033\fs26 , 30b. }

