\pard\fi0\li0\qj\ri0\sb0\sa600\itap0 \plain \f1\lang1033\fs26 7 Bl.\~\~\u183 \'b7\~\~K\u246 \'f6ln\~\~{\field{\*\fldinst HYPERLINK "hida://5060[0].5064/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 15. Jh. Ende}}
\par \pard\fi0\li0\qj\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs22 Fol. 230 \endash  236\~\~\u183 \'b7\~\~Wasserzeichen: Deckelkrug mit einkonturigem Kreuz und einem einfachen Henkel, zwei Varianten: 1. WZIS DE4500-PO-31296 (K\u246 \'f6ln 1493 \endash  1495); 2. sehr \u228 \'e4hnlich WZIS DE4500-PO-31297 (K\u246 \'f6ln 1495)\~\~\u183 \'b7\~\~Schriftraum: 20,5 \endash  21,5 x 16 \endash  17,5; Spaltenbegrenzungen entweder mit Tintenlinien oder blind vorgepr\u228 \'e4gt\~\~\u183 \'b7\~\~zweispaltig\~\~\u183 \'b7\~\~44 \endash  48 Zeilen\~\~\u183 \'b7\~\~sp\u228 \'e4te kursive Bastarda mit Schleifen von einer Hand\~\~\u183 \'b7\~\~230\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  \u220 \'dcberschrift in vergr\u246 \'f6\u223 \'dfertem Schriftgrad, fett und in Textualis\~\~\u183 \'b7\~\~Aussparungen mit Rubrikatorvorgaben f\u252 \'fcr 2-5zeilige Anfangsbuchstaben.}

