\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 clvi\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  clxxxv\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Novus Physiologus}}\plain \f1\lang1033\fs26 . (clvi\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Que sit natura vegetans animalia plura}}\plain \f1\lang1033\fs26  ... (clxxxv\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 qua fuerat natus et sacra fonte levatu\plain \f1\lang1033\fs26  (!). >\plain \f1\i\lang1033\fs26 Explicit Novus\plain \f1\lang1033\fs26  (?) \plain \f1\i\lang1033\fs26 Phisiologus\plain \f1\lang1033\fs26 <. \endash  Text bis clxxxii\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  mit interlinearen lateinischen und deutschen Wortglossen; einzig bislang bekannter Textzeuge; vermutlich in Deutschland zwischen 1294 und 1298 entstanden; zu Datierung, Lokalisierung und Textbestand vgl. Orb\u225 \'e1n, Novus Phisiologus, 1989 (s. Lit.), S. 1 \endash  21; Druck: ebenda S. 25 \endash  68 (nach dieser Handschrift); vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 15037}}\plain \f1\lang1033\fs26 ; Henkel, Studien, 1976, S. 41 \endash  42; Willene B. Clark, A Medieval Book of Beasts: The Second-Family Bestiary: Commentary, Art, Text and Translation, Woolbridge/ Rochester 1989, S. 110; Kohush\u246 \'f6lter, Gregorius, 2012 (s. Lit.), S. 56; Rubel, S\u252 \'fcnder, \plain \f1\super\lang1033\fs24 1\plain \f1\lang1033\fs26 2009 /\plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs26 2019 (s. Lit.), S. 41.}

