\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 cclxxxxvii\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \endash  ccciii\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Vita}}\plain \f1\lang1033\fs26  metrica s. {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Alexii}}\plain \f1\lang1033\fs26 . (cclxxxxvii\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Vir quidam magnus Rome fuit Ephamianus}}\plain \f1\lang1033\fs26  ...(cccii\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 et lepra mundatur\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 claudis gressus reparatur\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Talia cum vident reges cum presule summo\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 Corpus sanctum propriis mantibus\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 quoque petant\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 corporis a tactum sancti\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 quoque sanctificentur\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Corporis et animo\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 quoque sit medicamina sumunt\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Os\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 qui per turbam sanctum non facere valebant\plain \f1\lang1033\fs26  .... (ccciii\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Alexii vitam conscripsi in ordine totam\plain \f1\lang1033\fs26 . >\plain \f1\i\lang1033\fs26 Explicit Vita sancti Alexii\plain \f1\lang1033\fs26 <. \endash  281 Verse umfassender Text; vor allem am Schlu\u223 \'df von den beiden edierten Fassungen (s.u.) abweichend; Verse z.T. in von den Editionen abweichender Reihenfolge; unglossiert, ohne interlineare Zahlglossen; von L\u246 \'f6ffler (s.u.), S. 132 \endash  133 der metrischen f-Fassung zugeordnet; Druck: Hans Ferd. Massmann, Sanct Alexius Leben in acht gereimten mittelhochdeutschen Behandlungen, Quedlinburg/ Leipzig 1843 (Bibliothek der gesammten deutschen National-Literatur von der \u228 \'e4ltesten bis auf die neuere Zeit, Bd. 9), S. 176 \endash  179 (Teiledition bis ccc\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 , Zeile 21); \plain \f2\lang1024\fs26 Stefan Vrtel-Wierczy\u324 \'f1ski, Staropolska legenda o \u347 \'9cw. Aleksym: Na por\u243 \'f3wnawczem tle literatur s\u322 \'b3owia\u324 \'f1skich, Posen 1937 (Pozna\u324 \'f1skie Towarzystwo Przyjaci\u243 \'f3\u322 \'b3 Nauk Prace Komisji Filologicznej, Bd. 9)\plain \f1\lang1033\fs26 , S. 206 \endash  215 (Teiledition bis cccii\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  Zeile 5); vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 20422}}\plain \f1\lang1033\fs26 ; Stohlmann, Nachtr\u228 \'e4ge, 1972, S. 313; Mitteilungen \u252 \'fcber die in K\u246 \'f6ln betriebenen Forschungsarbeiten (s.o. xxxvi\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) S. 224, Nr. 6; {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 BHL, Nr. 295}}\plain \f1\lang1033\fs26 ; VL(2), Bd. 1 (1978), Sp. 226 \endash  235 (Hans Friedrich Rosenfeld); Roland L\u246 \'f6ffler, Alexius: Studien zur lateinischen Alexius-Legende und zu den mittelhochdeutschen Alexiusdichtungen, Diss. Freiburg 1991, S. 132 \endash  133 und 288; Orb\u225 \'e1n, Novus Phisiologus, 1989 (s. Lit.), S. 12; Kohush\u246 \'f6lter, Gregorius, 2012 (s. Lit.), S. 58; Rubel, S\u252 \'fcnder, \plain \f1\super\lang1033\fs24 1\plain \f1\lang1033\fs26 2009 /\plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs26 2019 (s. Lit.), S. 42; Parallel\u252 \'fcberlieferung: {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Breslau, UB, Ms. IV. 07}}\plain \f1\lang1033\fs26 , 20\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ; {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 M\u252 \'fcnchen, BSB, Clm 4413}}\plain \f1\lang1033\fs26 , 93\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 .}

