\pard\fi0\li0\qj\ri0\sb600\sa360\itap0 \plain \f1\lang1033\fs26 ccciii\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  cccxi\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hugo von Trimberg}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Laurea Sanctorum}}\plain \f1\lang1033\fs26 . (ccciii\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Cum sit necessarium sanctos invocare}}\plain \f1\lang1033\fs26  ... (cccxi\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 vos male tornatos incudi reddite versus\plain \f1\lang1033\fs26 . >\plain \f1\i\lang1033\fs26 Explicit Flores Sanctorum\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Expliciunt Flores \plain \f1\i\strike\lang1033\fs26 S\plain \f1\i\lang1033\fs26 sanctorum\plain \f1\lang1033\fs26 <. \endash  Unglossierter Text ohne interlineare Zahlglossen; Druck: Heinrich Grotefend, Laurea sanctorum, ein lateinischer Cisiojanus des Hugo von Trimberg, in: Anzeiger f\u252 \'fcr Kunde der deutschen Vorzeit N.F. 17 (1870), Sp. 301 \endash  311; vgl. ebenda Sp. 279 \endash  284; Karl Langosch, Das \u8218 \'82Registrum Multorum Auctorum\lquote  des Hugo von Trimberg. Untersuchungen und kommentierte Textausgabe, Berlin 1942 / Reprint Nendeln 1969 (Germanische Studien, Heft 235), S. 278 \endash  281; {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Walther, Versanf\u228 \'e4nge, Nr. 3796}}\plain \f1\lang1033\fs26 ; Stohlmann, Nachtr\u228 \'e4ge, 1972, S. 297; VL(2), Bd. 4 (1983), Sp. 268 \endash  282 (G\u252 \'fcnther Schweikle); Orb\u225 \'e1n, Novus Phisiologus, 1989 (s. Lit.), S. 12; Kohush\u246 \'f6lter, Gregorius, 2012 (s. Lit.), S. 58 \endash  59; Rubel, S\u252 \'fcnder, \plain \f1\super\lang1033\fs24 1\plain \f1\lang1033\fs26 2009 /\plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs26 2019 (s. Lit.), S. 42. }

